CID_FALLBACK = "HYGothic-Medium"

def _win_fonts_dir():
    return os.path.join(os.environ.get("WINDIR") or os.environ.get("SystemRoot") or r"C:\Windows", "Fonts")


def _font_dirs(recursive=False):
    """글꼴을 찾아볼 폴더 목록 (실제로 있는 폴더만). recursive=True 면 하위 폴더까지 찾을 대상."""
    home = Path.home()
    app = _app_dir()
    flat = [app / "fonts", app, Path.cwd() / "fonts", Path.cwd(), _font_cache_dir(),
            Path(_win_fonts_dir()),
            Path(os.environ.get("LOCALAPPDATA", "")) / "Microsoft" / "Windows" / "Fonts" if os.environ.get("LOCALAPPDATA") else None,
            Path("/System/Library/Fonts/Supplemental"), Path("/System/Library/Fonts"), Path("/Library/Fonts"),
            home / "Library" / "Fonts"]
    deep = [home / ".fonts", home / ".local" / "share" / "fonts", Path("/usr/share/fonts"),
            Path("/usr/local/share/fonts")]
    out = []
    for d in (deep if recursive else flat):
        try:
            if d is not None and d.is_dir() and d not in out:
                out.append(d)
        except OSError:
            pass
    return out


def _font_cache_dir():
    """내려받은 글꼴을 보관하는 사용자 캐시 폴더 (프로그램 폴더에 쓸 수 없을 때 사용)."""
    base = os.environ.get("LOCALAPPDATA") or os.environ.get("XDG_CACHE_HOME") or str(Path.home() / ".cache")
    return Path(base) / "summary_report" / "fonts"


def find_font_file(*names):
    """이름(대소문자 무시)이 같은 글꼴 파일을 찾아 경로를 돌려준다. 없으면 None."""
    wanted = {n.lower() for n in names}
    for d in _font_dirs():
        try:
            for f in d.iterdir():
                if f.name.lower() in wanted and f.is_file():
                    return str(f)
        except OSError:
            continue
    for d in _font_dirs(recursive=True):
        try:
            for f in d.rglob("*"):
                if f.name.lower() in wanted and f.is_file():
                    return str(f)
        except OSError:
            continue
    return None


def _fallback_candidates():
    """(경로, subfontIndex) — 기본 글꼴에 없는 글자(한자 등)를 그릴 대체 글꼴. TrueType 윤곽 글꼴만 가능."""
    found = []
    for names, idx in ((("malgun.ttf",), 0), (("batang.ttc",), 0), (("gulim.ttc",), 0),
                       (("wqy-zenhei.ttc",), 0), (("AppleGothic.ttf",), 0)):
        path = find_font_file(*names)
        if path:
            found.append((path, idx))
    return found


FALLBACK_CANDIDATES = []     # register_fonts 에서 채운다 (실행 시점의 폴더 기준)

_NANUM_URL = "https://github.com/google/fonts/raw/main/ofl/nanumgothic/"

FONT_CHOICE = "coding"        # 1.89: "coding" = 나눔고딕코딩(없으면 D2Coding) 우선, "gulim" = 굴림체 우선(굵게는 테두리로)
_CODING_URL = "https://github.com/google/fonts/raw/main/ofl/nanumgothiccoding/"
_CODING_FILES = ("NanumGothicCoding-Regular.ttf", "NanumGothicCoding-Bold.ttf")
_D2_ZIP_URL = "https://github.com/naver/d2codingfont/releases/download/VER1.3.2/D2Coding-Ver1.3.2-20180524.zip"


def _is_ttf(data, min_size=300_000):
    return len(data) >= min_size and data[:4] in (b"\x00\x01\x00\x00", b"true")


def _urlread(url, timeout=60):
    import urllib.request
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()


def _download_coding():
    """1.89: 굵은 글꼴이 있는 고정폭 한글 글꼴을 웹에서 내려받는다. 나눔고딕코딩(Regular·Bold) → 안 되면 D2Coding(zip).
    성공하면 (일반 경로, 굵게 경로), 실패하면 None. 받은 파일은 fonts/ 폴더(안 되면 사용자 캐시 폴더)에 저장한다."""
    import io as _io
    import zipfile
    for target in (_app_dir() / "fonts", _font_cache_dir()):
        try:
            target.mkdir(parents=True, exist_ok=True)
        except OSError:
            continue
        reg_p, bold_p = target / _CODING_FILES[0], target / _CODING_FILES[1]
        if reg_p.exists() and bold_p.exists():
            return str(reg_p), str(bold_p)
        try:
            blobs = []
            for name in _CODING_FILES:
                print(f"[글꼴] 나눔고딕코딩을 내려받는 중: {name}")
                data = _urlread(_CODING_URL + name)
                if not _is_ttf(data):
                    raise ValueError("올바른 TTF 가 아닙니다")
                blobs.append(data)
            for p, data in zip((reg_p, bold_p), blobs):
                tmp = p.with_suffix(".part")
                tmp.write_bytes(data)
                tmp.replace(p)
            return str(reg_p), str(bold_p)
        except Exception as ex:
            print(f"[글꼴] 나눔고딕코딩을 {target} 에 내려받지 못했습니다: {ex}")
        d2r, d2b = target / "D2Coding.ttf", target / "D2CodingBold.ttf"
        if d2r.exists() and d2b.exists():
            return str(d2r), str(d2b)
        try:
            print("[글꼴] D2Coding 을 내려받는 중")
            with zipfile.ZipFile(_io.BytesIO(_urlread(_D2_ZIP_URL, 120))) as z:
                found = {}
                for info in z.infolist():
                    base = info.filename.replace("\\", "/").split("/")[-1]
                    low = base.lower()
                    if not low.endswith(".ttf") or "d2coding" not in low or "ligature" in info.filename.lower() or "all" in low:
                        continue
                    found["bold" if "bold" in low else "reg"] = z.read(info)
                if "reg" not in found or "bold" not in found or not (_is_ttf(found["reg"]) and _is_ttf(found["bold"])):
                    raise ValueError("zip 안에서 D2Coding Regular·Bold TTF 를 찾지 못했습니다")
            for p, key in ((d2r, "reg"), (d2b, "bold")):
                tmp = p.with_suffix(".part")
                tmp.write_bytes(found[key])
                tmp.replace(p)
            return str(d2r), str(d2b)
        except Exception as ex:
            print(f"[글꼴] D2Coding 을 {target} 에 내려받지 못했습니다: {ex}")
    return None


def _download_nanum():
    """한글 TTF 가 어디에도 없을 때 나눔고딕을 한 번 내려받는다. 성공하면 (일반, 굵게) 경로, 실패하면 None."""
    import urllib.request
    for target in (_app_dir() / "fonts", _font_cache_dir()):
        try:
            target.mkdir(parents=True, exist_ok=True)
            paths = []
            for remote, local in (("NanumGothic-Regular.ttf", "NanumGothic.ttf"), ("NanumGothic-Bold.ttf", "NanumGothicBold.ttf")):
                dest = target / local
                if not dest.exists():
                    print(f"[글꼴] 한글 글꼴을 찾지 못해 내려받는 중: {remote}")
                    with urllib.request.urlopen(_NANUM_URL + remote, timeout=30) as r:
                        data = r.read()
                    if len(data) < 500_000 or data[:4] not in (b"\x00\x01\x00\x00", b"true"):
                        raise ValueError("올바른 TTF 가 아닙니다")
                    tmp = dest.with_suffix(".part")
                    tmp.write_bytes(data)
                    tmp.replace(dest)
                paths.append(str(dest))
            return paths[0], paths[1]
        except Exception as ex:
            print(f"[글꼴] {target} 에 내려받지 못했습니다: {ex}")
    return None


def esc(text):
    """XML 이스케이프 + 현재 글꼴에 없는 글자(한자·로마숫자 등)만 대체 글꼴로 표시."""
    t = _xml_escape(text)
    if not GLYPHS:
        return t
    out = []
    for ch in t:
        if ord(ch) < 128 or ord(ch) in GLYPHS:
            out.append(ch)
            continue
        name = next((n for n, g in FALLBACKS if ord(ch) in g), CID_FALLBACK)
        out.append(f'<font name="{name}">{ch}</font>')
    return "".join(out)


_FONTS_READY = False


def register_fonts():
    global _FONTS_READY
    if _FONTS_READY:
        return
    _FONTS_READY = True
    _register_fonts()


GULIMCHE_INDEX = 1


def _font_candidates():
    """(일반, 굵게) 글꼴 쌍을 우선순위대로. 파일이 있는 것만."""
    pairs = []
    if FONT_CHOICE == "coding":                           # 1.89: 굵은 글꼴이 따로 있는 고정폭 한글 글꼴을 굴림체보다 먼저
        for reg_names, bold_names in ((("NanumGothicCoding-Regular.ttf", "NanumGothicCoding.ttf"), ("NanumGothicCoding-Bold.ttf", "NanumGothicCodingBold.ttf")),
                                      (("D2Coding.ttf",), ("D2CodingBold.ttf",))):
            reg = find_font_file(*reg_names)
            bold = find_font_file(*bold_names)
            if reg and bold:
                pairs.append((reg, bold, 0))
    gul = find_font_file("gulim.ttc")                    # 1.48: 굴림체 = gulim.ttc 의 두 번째 글꼴(0 굴림, 1 굴림체, 2 돋움, 3 돋움체)
    if gul:
        pairs.append((gul, gul, GULIMCHE_INDEX))
    for reg_names, bold_names in (
            (("malgun.ttf",), ("malgunbd.ttf",)),
            (("NanumGothic.ttf", "NanumGothic-Regular.ttf", "NanumGothicRegular.ttf"),
             ("NanumGothicBold.ttf", "NanumGothic-Bold.ttf")),
            (("NotoSansKR-Regular.ttf", "NotoSansKR-Medium.ttf"), ("NotoSansKR-Bold.ttf",)),
            (("AppleGothic.ttf",), ("AppleGothic.ttf",))):
        reg = find_font_file(*reg_names)
        if reg:
            pairs.append((reg, find_font_file(*bold_names) or reg, 0))
    return pairs


def _try_register_ttf(reg, bold, idx=0):
    """KR / KR-B 로 등록. CFF(.otf) 처럼 reportlab 이 못 읽는 글꼴이면 False. idx = 글꼴 모음(.ttc) 안 번호."""
    global FONT, FONT_B, GLYPHS, BOLD_FAKE
    try:
        pdfmetrics.registerFont(TTFont("KR", reg, subfontIndex=idx))
        BOLD_FAKE = False
        try:
            if os.path.normcase(bold) == os.path.normcase(reg):
                raise ValueError("굵은 글꼴 파일 없음")
            pdfmetrics.registerFont(TTFont("KR-B", bold))
        except Exception:
            pdfmetrics.registerFont(TTFont("KR-B", reg, subfontIndex=idx))
            BOLD_FAKE = True
        pdfmetrics.registerFontFamily("KR", normal="KR", bold="KR-B", italic="KR", boldItalic="KR-B")
        FONT, FONT_B = "KR", "KR-B"
        GLYPHS = set(pdfmetrics.getFont("KR").face.charToGlyph.keys())
        register_fallbacks(reg)
        print(f"[글꼴] {reg}")
        print("[글꼴] 굵은 글꼴: " + ("테두리로 만든 굵게(굵은 글꼴 파일 없음 — 일부 PDF 보기에서 덜 굵어 보일 수 있음)" if BOLD_FAKE
                                  else f"실제 Bold 파일({os.path.basename(bold)}) — PDF 에 포함되어 태블릿·폰 어느 PDF 보기에서도 같은 굵기로 보임"))
        return True
    except Exception as ex:
        print(f"[글꼴] {reg} 을(를) 쓸 수 없어 다음 후보로 넘어갑니다: {ex}")
        return False


def _register_fonts():
    """한글 글꼴 등록. 시스템·폴더에서 찾고, 없으면 나눔고딕을 내려받고, 그래도 없으면 내장 CID 글꼴로 대체."""
    global FONT, FONT_B
    pdfmetrics.registerFont(UnicodeCIDFont(CID_FALLBACK))
    if FONT_CHOICE == "coding" and not any(os.path.basename(c[0]).lower().startswith(("nanumgothiccoding", "d2coding")) for c in _font_candidates()):
        got_c = _download_coding()                        # 1.89: PC 에 없으면 웹에서 내려받는다
        if got_c and _try_register_ttf(got_c[0], got_c[1]):
            return
    for reg, bold, idx in _font_candidates():
        if _try_register_ttf(reg, bold, idx):
            return
    got = _download_nanum()
    if got and _try_register_ttf(*got):
        return
    pdfmetrics.registerFontFamily("HYGothic-Medium", normal="HYGothic-Medium", bold="HYGothic-Medium",
                                  italic="HYGothic-Medium", boldItalic="HYGothic-Medium")
    FONT = FONT_B = "HYGothic-Medium"
    print("[글꼴] TTF를 찾지 못해 내장 CID 글꼴(HYGothic-Medium)을 사용합니다. "
          "(PDF 보기 프로그램에 한글 글꼴이 있어야 글자가 보입니다)")


def register_fallbacks(primary_path):
    """기본 글꼴에 없는 글자를 그릴 대체 TTF를 등록한다 (기본 글꼴과 같은 파일은 제외)."""
    FALLBACK_CANDIDATES[:] = _fallback_candidates()
    for i, (path, idx) in enumerate(FALLBACK_CANDIDATES):
        if os.path.exists(path) and os.path.normcase(path) != os.path.normcase(primary_path):
            try:
                name = f"KR-FB{i}"
                pdfmetrics.registerFont(TTFont(name, path, subfontIndex=idx))
                FALLBACKS.append((name, set(pdfmetrics.getFont(name).face.charToGlyph.keys())))
            except Exception:
                pass


def build_styles():
    base = dict(fontName=FONT, textColor=INK)
    S["body"] = ParagraphStyle("body", fontSize=9.5, leading=14, **base)
    S["bullet"] = ParagraphStyle("bullet", parent=S["body"], leftIndent=11, bulletIndent=1, spaceAfter=3)
    S["gen"] = ParagraphStyle("gen", parent=S["body"], fontSize=8.8, leading=12.2, leftIndent=11, bulletIndent=1,
                              spaceAfter=2)
    S["h2"] = ParagraphStyle("h2", fontName=FONT_B, fontSize=11, leading=15, textColor=NAVY,
                             spaceBefore=9, spaceAfter=3)
    S["sub"] = ParagraphStyle("sub", fontName=FONT, fontSize=8.5, leading=12, textColor=GRAY)
    S["title"] = ParagraphStyle("title", fontName=FONT_B, fontSize=16, leading=20, textColor=colors.white)
    S["tag"] = ParagraphStyle("tag", fontName=FONT, fontSize=9, leading=12, textColor=colors.white, alignment=2)
    S["kpi_l"] = ParagraphStyle("kpi_l", fontName=FONT, fontSize=8, leading=11, textColor=GRAY, alignment=1)
    S["kpi_v"] = ParagraphStyle("kpi_v", fontName=FONT_B, fontSize=13, leading=17, textColor=NAVY, alignment=1)
    S["en_small"] = ParagraphStyle("en_small", fontName=FONT_B, fontSize=9.5, leading=13, textColor=colors.HexColor("#374151"))
    S["en_tag"] = ParagraphStyle("en_tag", fontName=FONT, fontSize=8.5, leading=12, textColor=GRAY, alignment=2)
    S["en_title"] = ParagraphStyle("en_title", fontName=FONT_B, fontSize=25, leading=32, textColor=colors.HexColor("#111827"))
    S["en_sub"] = ParagraphStyle("en_sub", fontName=FONT, fontSize=12.5, leading=19, textColor=colors.HexColor("#4B5563"))
    S["en_card_l"] = ParagraphStyle("en_card_l", fontName=FONT, fontSize=9.5, leading=13, textColor=colors.HexColor("#4B5563"))
    S["en_card_v"] = ParagraphStyle("en_card_v", fontName=FONT_B, fontSize=14, leading=34, textColor=colors.HexColor("#111827"))
    S["en_card_s"] = ParagraphStyle("en_card_s", fontName=FONT, fontSize=9, leading=13, textColor=colors.HexColor("#6B7280"))
    S["en_th"] = ParagraphStyle("en_th", fontName=FONT_B, fontSize=10.5, leading=15, textColor=colors.HexColor("#1F2937"))
    S["en_td"] = ParagraphStyle("en_td", fontName=FONT, fontSize=11.5, leading=17.5, textColor=colors.HexColor("#1F2937"))
    S["en_note"] = ParagraphStyle("en_note", fontName=FONT, fontSize=8.5, leading=12, textColor=colors.HexColor("#6B7280"))
    S["tp_title"] = ParagraphStyle("tp_title", fontName=FONT_B, fontSize=TP_TITLE_PT, leading=TP_TITLE_PT * 1.3,
                                   textColor=colors.HexColor("#111827"))
    S["tp_sub"] = ParagraphStyle("tp_sub", fontName=FONT, fontSize=TP_SUB_PT, leading=TP_SUB_PT * 1.5,
                                 textColor=colors.HexColor("#4B5563"))
    S["tp_card_l"] = ParagraphStyle("tp_card_l", fontName=FONT, fontSize=8.5, leading=11.5, textColor=colors.HexColor("#4B5563"))
    S["tp_card_v"] = ParagraphStyle("tp_card_v", fontName=FONT_B, fontSize=14, leading=TP_CARD_VALUE_PT * 1.3,
                                    textColor=colors.HexColor("#111827"))
    S["tp_card_s"] = ParagraphStyle("tp_card_s", fontName=FONT, fontSize=8, leading=11, textColor=colors.HexColor("#6B7280"))
    S["cover_sub"] = ParagraphStyle("cover_sub", fontName=FONT, fontSize=15, leading=22, textColor=INK)
    S["cover_title"] = ParagraphStyle("cover_title", fontName=FONT_B, fontSize=30, leading=38, textColor=NAVY,
                                      spaceAfter=6)
    if BOLD_ALL:                                             # 1.49: 요약 PDF 문단 글꼴도 굵은 글꼴로
        for st in S.values():
            if isinstance(st, ParagraphStyle) and st.fontName == FONT:
                st.fontName = FONT_B


# ----------------------------------------------------------------------------
# 3. 원본 PDF 파싱  (숫자는 항상 '문자열 그대로' 보관)
# ----------------------------------------------------------------------------
class ParseError(Exception):
    pass


def clean(s):
    return re.sub(r"\s+", " ", (s or "").replace("\n", " ")).strip()


NUM_TOKENS = r"(?:(?:[\d,]+|-)(?:\s+|$))+"
MEMBER_RE = re.compile(r"^(\S+)\s*\((\d+)\)\s+(" + NUM_TOKENS + r")$")
AGE_RE = re.compile(r"^(\d+세|종신)\s+(" + NUM_TOKENS + r")$")


_FP_BAD = ("소속", "H.P", "Email", "Financial", "Planner", "출력")


def _fp_name(page, t):
    """담당 FP 이름을 읽는다. 1) 글줄에서 'Financial Planner' 뒤 낱말 2) 같은 줄의 오른쪽 낱말(위치) 3) '소속' 줄 바로 위의 한글 이름."""
    m = re.search(r"Financial\s*Planner\s*[:：]?\s*([^\s:：]+)", t)
    if m and not m.group(1).startswith(_FP_BAD):
        return m.group(1).strip()
    try:
        words = page.extract_words(x_tolerance=1.5, y_tolerance=3)
    except Exception:
        return ""
    ref = next((w for w in words if "Planner" in w["text"]), None)
    if ref:
        g = re.search(r"Planner[:：]?(.+)$", ref["text"])
        if g and not g.group(1).startswith(_FP_BAD):
            return g.group(1).strip()
        cy = (ref["top"] + ref["bottom"]) / 2
        tol = max(6, (ref["bottom"] - ref["top"]) * 0.8)
        cand = sorted((w for w in words if w is not ref and abs((w["top"] + w["bottom"]) / 2 - cy) < tol
                       and w["x0"] >= ref["x1"] - 1 and not w["text"].startswith(_FP_BAD)), key=lambda w: w["x0"])
        if cand:
            return cand[0]["text"].strip()
    sok = next((w for w in words if w["text"].startswith("소속")), None)
    if sok:
        up = [w for w in words if re.fullmatch(r"[가-힣]{2,4}", w["text"]) and w["bottom"] <= sok["top"] + 2
              and sok["top"] - w["bottom"] < 45 and not w["text"].startswith(_FP_BAD) and w["text"] != "고객님"]
        if up:
            return max(up, key=lambda w: (w["bottom"], w["x0"]))["text"]
    return ""


def parse_cover(page):
    t = page.extract_text() or ""

    def g(pat):
        m = re.search(pat, t)
        return m.group(1).strip() if m else ""

    cv = dict(name=g(r"(\S+)\s*고객님\s*을\s*위한"), fp=_fp_name(page, t),
              branch=g(r"소속:\s*(.+)"), phone=g(r"H\.P:\s*(\S+)"), email=g(r"Email:\s*(\S+)"),
              print_date=g(r"출력\s*\|\s*([\d-]+)"))
    if not cv["fp"]:
        print("[주의] 표지에서 담당 FP 이름을 읽지 못했습니다.")
    return cv


def parse_enrollment(page):
    t = page.extract_text() or ""

    def g(pat):
        m = re.search(pat, t)
        return m.group(1) if m else ""

    info = dict(birth=g(r"\((\d{4}\.\d{2}\.\d{2})일생\)"), ins_age=g(r"보험나이\s*(\d+)세"),
                age_date=g(r"상령일\s*([\d.]+)"), n_contracts=g(r"유지계약\s*(\d+)건"),
                monthly=g(r"월보험료\s*([\d,]+)원"), paid_total=g(r"기납입보험료\s*([\d,]+)원"))
    m = re.search(r"(\d{4})년\s*(\d{1,2})월\s*(\d{1,2})일 기준", t)
    info["basis"] = f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}" if m else ""

    contracts = []
    for tb in page.extract_tables():
        for row in tb:
            if len(row) >= 13 and re.fullmatch(r"\d+", clean(row[0])):
                c = [clean(x) for x in row]
                contracts.append(dict(no=c[0], origin=c[1], company=c[2], name=c[3], holder=c[4],
                                      insured=c[5], coinsured=c[6], date=c[7], expiry=c[8],
                                      premium=c[9], count=c[10], last=c[11], paid=c[12]))
    if not contracts:
        raise ParseError("2쪽에서 계약 목록을 찾지 못했습니다.")
    return info, contracts


def parse_generation(page):
    t = page.extract_text() or ""
    m = re.search(r"(\d+)건\s+(\d+)건\s+(\d+)건\s+(\d+)건\s+(\d+)건", t)
    counts = dict(zip(["total", "kyobo", "life", "nonlife", "mutual"], m.groups())) if m else {}
    members = []
    for line in t.splitlines():
        mm_ = MEMBER_RE.match(line.strip())
        if mm_ and len(mm_.group(3).split()) == 18:
            members.append((mm_.group(1), mm_.group(2), mm_.group(3).split()))
    if not members or len(members) % 2:
        raise ParseError("3쪽에서 구성원별 보장 행을 찾지 못했습니다.")
    n = len(members) // 2
    result = []
    for i in range(n):
        name, age, a = members[i]
        _, _, b = members[n + i]
        result.append(dict(name=name, age=age, a=a, b=b))
    return counts, result


def parse_products(page, labels):
    """4·5쪽: 필요/준비/부족 + 상품별 준비 금액."""
    t = page.extract_text() or ""
    m = re.search(r"(\d+)\s*개\s+(\d+)\s*개\s+(\d+)\s*개\s+(\d+)\s*개", t)
    head = dict(zip(["total", "ok", "low", "none"], m.groups())) if m else {}
    n = len(labels)
    d = dict(need=None, prep=None, short=None, total=None, products=[], head=head)
    for tb in page.extract_tables():
        for row in tb:
            if len(row) < 3:
                continue
            key = clean(row[1])
            vals = [clean(c) for c in row[2:] if c is not None and clean(c) != ""]
            if key in ("필요", "준비", "부족") and len(vals) == n:
                d[{"필요": "need", "준비": "prep", "부족": "short"}[key]] = vals
            elif not key and row[0] and len(vals) == n:
                cell = row[0].strip()
                if cell.startswith("보장 합계"):
                    d["total"] = vals
                    continue
                lines = [l.strip() for l in cell.split("\n") if l.strip()]
                if len(lines) < 3:
                    continue
                tail = re.match(r"([\d,]+)원\s*\((.+)\)$", lines[-1])
                d["products"].append(dict(company=lines[0], name="".join(lines[1:-1]),
                                          premium=tail.group(1) + "원" if tail else lines[-1],
                                          expiry=tail.group(2) if tail else "", vals=vals))
    if not (d["need"] and d["prep"] and d["short"]):
        raise ParseError("상품별 분석에서 필요/준비/부족 행을 찾지 못했습니다.")
    return d


def canonical_names(products, contracts):
    """상품명이 줄바꿈으로 잘린 경우, 2쪽 계약 목록의 상품명으로 바로잡는다."""
    for p in products:
        key = re.sub(r"\s+", "", p["name"])
        for c in contracts:
            if c["company"] == p["company"] and re.sub(r"\s+", "", c["name"]).startswith(key):
                p["name"] = c["name"]
                break


def color_status(col, text):
    """6쪽 숫자 글자색 → 충분/부족/미보장 (원본 범례 색 기준)."""
    try:
        r, g, b = [float(x) for x in col[:3]]
        if r > 0.7 and g < 0.4:
            return "미보장"
        if r > 0.8 and 0.4 <= g < 0.75:
            return "부족"
        return "충분"
    except Exception:
        return "미보장" if text == "0" else "부족"


def parse_body(page):
    """항목명과 금액을 위치로 하나씩 짝짓는다. 같은 숫자가 여러 항목에 있어도 각 숫자는 자기 줄·자기 쪽(좌/우)의
    항목에만 배정하며, 한 숫자가 두 항목에 쓰이면 오류로 멈춘다. (모든 수치는 개별 값)"""
    words = page.extract_words(extra_attrs=["non_stroking_color"])
    nums = [w for w in words if re.fullmatch(r"[\d,]+", w["text"])]
    mid = float(page.width) / 2
    out, used = {}, {}
    for _, labs in BODY_GROUPS:
        for lab in labs:
            cand_labels = [w for w in words if w["text"] in (lab, BODY_ALT.get(lab, lab))]
            if not cand_labels:
                raise ParseError(f"6쪽에서 '{lab}' 항목을 찾지 못했습니다.")
            lw = cand_labels[0]
            left = lw["x0"] < mid
            cands = [n for n in nums if abs(n["top"] - lw["top"]) < 4 and n["x0"] > lw["x1"] and (n["x0"] < mid) == left]
            if not cands:
                raise ParseError(f"6쪽에서 '{lab}' 금액을 찾지 못했습니다.")
            n = min(cands, key=lambda w: w["x0"] - lw["x1"])
            key = (round(n["x0"], 1), round(n["top"], 1))
            if key in used:
                raise ParseError(f"6쪽에서 한 금액({n['text']})이 '{used[key]}'와 '{lab}' 두 항목에 배정되었습니다.")
            used[key] = lab
            out[lab] = (n["text"], color_status(n.get("non_stroking_color"), n["text"]))
    return out


def parse_ages(page, n_labels):
    rows = []
    for line in (page.extract_text() or "").splitlines():
        m = AGE_RE.match(line.strip())
        if m and len(m.group(2).split()) == n_labels:
            rows.append((m.group(1), m.group(2).split()))
    if not rows:
        raise ParseError("연령별 분석 행을 찾지 못했습니다.")
    return rows


# ----------------------------------------------------------------------------
# 3-B. 쪽 종류 자동 인식 (쪽 번호가 아니라 '쪽 제목'으로 판단) + 범용 요약
# ----------------------------------------------------------------------------
# (제목 키워드, 종류). 전용 요약 양식이 있는 종류만 generic 이 아니다.
KINDS = [
    ("Pride of KYOBO", "generic"),
    ("종합요약", "generic"),
    ("보험 가입 현황", "enrollment"),
    ("세대 분석", "generation"),
    ("상품별 분석", "products"),
    ("신체부위별 보장현황", "body"),
    ("보장밸런스", "generic"),
    ("연령별 분석", "ages"),
    ("보장항목별 분석", "generic"),
    ("보장 제안", "generic"),
]
COMPARE_KEY = "전/후 비교"       # 제목에 이 말이 있으면 전용 양식이 없으므로 항상 범용 요약


def _nos(s):
    return re.sub(r"\s+", "", s)


def title_zone(text, n=6):
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    return " ".join(lines[:n])


def find_part(text, kw):
    """'제목 (1/2)', '제목 1/6' 같은 쪽 순번을 찾는다."""
    pat = r"\s*".join(re.escape(c) for c in kw.replace(" ", ""))
    m = re.search(pat + r"[^\d\n]{0,14}?\(?\s*(\d+)\s*/\s*(\d+)\s*\)?", text)
    return f"{m.group(1)}/{m.group(2)}" if m else ""


def classify(idx, text):
    """-> (종류, 표시 제목, 순번)"""
    zone = _nos(title_zone(text)).lower()
    if idx == 0 and "고객님을위한" in zone:
        return "cover", "표지", ""
    if "가입상품보장내역" in zone:                                    # 1.72: 가입상품 보장내역 → 상품별 가입 현황으로 읽는다
        return "prodcov", "가입상품 보장내역", find_part(text, "가입상품 보장내역") or ""
    compare = _nos(COMPARE_KEY) in zone
    best = None
    for kw, kind in KINDS:
        pos = zone.find(_nos(kw).lower())
        if pos >= 0 and (best is None or pos < best[0]):
            best = (pos, kw, kind)
    if best:
        _, kw, kind = best
        base = kw + (" " + COMPARE_KEY if compare else "")
        part = find_part(text, base)
        return ("generic" if compare else kind), base + (f" ({part})" if part else ""), part
    if compare:
        part = find_part(text, COMPARE_KEY)
        return "generic", COMPARE_KEY + (f" ({part})" if part else ""), part
    first = next((l.strip() for l in text.splitlines() if l.strip()), "")
    return "generic", (first[:30] or "(내용 없음)"), ""


def find_basis(texts):
    for t in texts:
        m = re.search(r"(\d{4})년\s*(\d{1,2})월\s*(\d{1,2})일 기준", t)
        if m:
            return f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}"
    return ""


def customer_name(entries):
    for e in entries:
        if e["kind"] == "cover" and e["mode"] == "전용" and e["data"].get("name"):
            return e["data"]["name"]
    for e in entries:
        m = re.search(r"(\S+?)\s*(?:고객님의|님의)", e["text"])
        if m:
            return m.group(1)
    return ""


def _pick_labels(text):
    if "일반사망" in text:
        return LABELS_A, GROUPS_A, "사망·진단"
    if "재해골절" in text:
        return LABELS_B, GROUPS_B, "항암·수술·입원·통원·실손"
    raise ParseError("열 구성을 알 수 없습니다.")


def run_parser(e, ctx):
    pg, k = e["page"], e["kind"]
    if k == "cover":
        d = parse_cover(pg)
        if not d["name"]:
            raise ParseError("고객명을 찾지 못했습니다.")
        return d
    if k == "enrollment":
        info, cs = parse_enrollment(pg)
        return dict(info=info, contracts=cs)
    if k == "generation":
        counts, members = parse_generation(pg)
        return dict(counts=counts, members=members)
    if k == "products":
        labels, groups, suffix = _pick_labels(e["text"])
        d = parse_products(pg, labels)
        canonical_names(d["products"], ctx["contracts"])
        e["title"] += " " + suffix
        return dict(d=d, labels=labels, groups=groups)
    if k == "prodcov":
        return parse_prodcov_page(pg)
    if k == "body":
        return dict(body=parse_body(pg))
    if k == "ages":
        labels, groups, suffix = _pick_labels(e["text"])
        rows = parse_ages(pg, len(labels))
        e["title"] += " " + suffix
        return dict(rows=rows, labels=labels, groups=groups)
    raise ParseError("전용 양식 없음")


def analyze_pdf(pdf, force_generic=False):
    """모든 쪽을 읽어 쪽별 항목(entries)을 만든다. 쪽 수·순서는 PDF 그대로 따른다."""
    entries, texts = [], []
    for i, pg in enumerate(pdf.pages):
        text = pg.extract_text() or ""
        texts.append(text)
        kind, title, part = classify(i, text)
        entries.append(dict(n=i + 1, kind=kind, title=title, part=part, text=text, page=pg,
                            mode="범용", data=None, note=""))
    ctx = dict(contracts=[], basis=find_basis(texts))
    for e in sorted(entries, key=lambda x: x["kind"] != "enrollment"):    # 계약 목록(상품명 보정용)을 먼저
        if force_generic or e["kind"] == "generic":
            continue
        try:
            e["data"] = run_parser(e, ctx)
            e["mode"] = "전용"
            if e["kind"] == "enrollment":
                ctx["contracts"] = e["data"]["contracts"]
        except Exception as ex:                                            # 실패하면 범용 요약으로 대체
            if e["kind"] == "products" and "필요/준비/부족 행을 찾지 못했습니다" in str(ex):
                e["note"] = "상품별 분석 이어지는 쪽(계약 행만 있음): 계약별 보장 현황 슬라이드에서 다룸 → 범용 요약도 함께 제공"
            else:
                e["note"] = f"전용 양식 인식 실패 → 범용 요약 ({ex})"
    ctx["name"] = customer_name(entries)
    ctx["cover"] = next((e["data"] for e in entries if e["kind"] == "cover" and e["mode"] == "전용"), {})
    return entries, ctx


# ---- 범용 요약: 원문 글자 + 표를 문장으로 (숫자는 원본 문자열 그대로) ----
NUM_RE = re.compile(r"-?[\d,]+(?:\.\d+)?(?:%|원|세|건|개|만원|억원)?")


def _is_num(c):
    return bool(NUM_RE.fullmatch(c))


def is_boiler(s):
    """매 쪽 반복되는 안내 문구·머리글·바닥글."""
    return (s.startswith("*") or s.startswith("본 자료는") or "동일한 번호에 한하여" in s
            or ("Financial Planner" in s and "|" in s)
            or re.fullmatch(r"K\s*Y\s*O\s*B\s*O\s*L\s*I\s*F\s*E", s) is not None
            or re.search(r"보장분석 보고서\s*\d+\s*$", s) is not None
            or re.fullmatch(r"[-\s.·]+", s) is not None)


def clean_grid(tb):
    """표 한 개 → (머리글 행 수, 행 목록). 빈 행·빈 열·안내 문구 행을 제거한다. 쓸 수 없는 표는 None."""
    rows = [[clean(c) for c in r] for r in tb]
    rows = [r for r in rows if any(r) and not any(is_boiler(c) for c in r if c and c != "-")]
    if len(rows) < 2:
        return None
    width = max(len(r) for r in rows)
    rows = [r + [""] * (width - len(r)) for r in rows]
    keep = [j for j in range(width) if any(r[j] for r in rows)]
    rows = [[r[j] for j in keep] for r in rows]
    if len(keep) < 2:
        return None
    first = next((i for i, r in enumerate(rows) if any(_is_num(c) for c in r[1:])), None)
    head = 1 if first is None else min(max(first, 1), 3)
    return head, rows


def _dlen(s):
    return sum(2 if ord(ch) > 0x2E80 else 1 for ch in s)


def grid_table(head_n, rows, width=None):
    """범용 쪽의 표를 그대로 표로 옮긴다. 열 폭은 글자 길이에 비례, 열이 많으면 글자 크기를 줄인다."""
    n = len(rows[0])
    size = 8 if n <= 6 else 7 if n <= 10 else 6.2 if n <= 14 else 5.5
    weights = [min(max(max(_dlen(r[j]) for r in rows) + 2, 4), 30) for j in range(n)]
    widths = [(width or CW) * w / sum(weights) for w in weights]
    data = []
    for i, r in enumerate(rows):
        if i > head_n and r[0] and r[0] == rows[i - 1][0]:      # 앞 행과 같은 구분 값은 한 번만 표시
            r = [""] + r[1:]
        if i < head_n:
            data.append([cell(esc(v), size, 1, True, INK) for v in r])
        else:
            data.append([cell(esc(v), size, 2 if (_is_num(v) or v == "-") else 0, j == 0) for j, v in enumerate(r)])
    t = Table(data, colWidths=widths, repeatRows=head_n)
    t.setStyle(TableStyle(list_table_style() + [("LINEBELOW", (0, head_n - 1), (-1, head_n - 1), 1.0, TP_HEAD_LINE)]))
    return t


def generic_items(page):
    text = page.extract_text() or ""
    unit, lines, seen = "", [], set()
    for raw in text.splitlines():
        s = raw.strip()
        if not s:
            continue
        m = re.fullmatch(r"\(\s*단위\s*:\s*([^)]+?)\s*\)", s)
        if m:
            unit = m.group(1)
            continue
        if is_boiler(s) or s in seen:
            continue
        seen.add(s)
        s = " ".join(t for t in s.split() if t != "-")          # '없음' 표시(-)는 생략
        if s:
            lines.append(s)
    grids, tok = [], set()
    for tb in page.extract_tables():
        g = clean_grid(tb)
        if g:
            grids.append(g)
            for r in tb:
                for c in r:
                    tok.update((c or "").split())
    rest = [l for l in lines if not tok or any(t not in tok for t in l.split())]
    return rest, grids, unit


def story_generic(e):
    rest, grids, unit = generic_items(e["page"])
    if grids:                                                # 표가 있는 쪽은 표 쪽 공통 양식(보험 가입 현황과 같은 형식)
        nt = _nos(e["title"])
        rest = [l for l in rest if _nos(l) not in nt and nt not in _nos(l)]
        if len(rest) > 40:
            rest = [" · ".join(esc(x) for x in rest[i:i + 6]) for i in range(0, len(rest), 6)]
        else:
            rest = [esc(x) for x in rest]

        def body(W):
            out = [Paragraph(c, S["gen"], bulletText="•") for c in rest]
            for head_n, rows in grids:
                out += [Spacer(1, 5), grid_table(head_n, rows, W)]
            return out
        return table_page(e["n"], "내용 정리", e["title"], f"단위: {unit}" if unit else "원본의 표를 그대로 정리", [], body)
    st = page_header(e["title"], e["n"], f"단위: {unit}" if unit else "", WCW)
    nt = _nos(e["title"])
    rest = [l for l in rest if _nos(l) not in nt and nt not in _nos(l)]      # 쪽 제목과 같은 줄은 제외
    if not rest and not grids:
        st.append(P("텍스트 없음 (이미지·그래프)", "sub"))
        return st
    if len(rest) > 40:                                       # 줄이 너무 많으면 이어 붙여 촘촘하게
        rest = [" · ".join(esc(x) for x in rest[i:i + 6]) for i in range(0, len(rest), 6)]
    else:
        rest = [esc(x) for x in rest]
    for c in rest:
        st.append(Paragraph(c, S["gen"], bulletText="•"))
    for head_n, rows in grids:
        st += [Spacer(1, 5), grid_table(head_n, rows, WCW)]
    return st


# ----------------------------------------------------------------------------
# 4. 표·레이아웃 도우미
# ----------------------------------------------------------------------------
def col(text, color):
    return f'<font color="{color}">{text}</font>'


def P(text, style="body"):
    return Paragraph(text, S[style])


def bullet(text):
    return Paragraph(text, S["bullet"], bulletText="•")


def h2(text):
    return Paragraph(text, S["h2"])


CUSTOMER_NAME = ""          # 모든 쪽 헤더에 넣을 고객 이름 (build_pdf 가 채운다)


def page_header(title, src, sub="", width=None):
    tag = f"{esc(CUSTOMER_NAME)} 고객님 · 원본 p.{src}" if CUSTOMER_NAME else f"원본 p.{src}"
    t = Table([[Paragraph(title, S["title"]), Paragraph(tag, S["tag"])]],
              colWidths=[(width or CW) - 80 * mm, 80 * mm])
    t.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, -1), NAVY), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                           ("LEFTPADDING", (0, 0), (-1, -1), 10), ("RIGHTPADDING", (0, 0), (-1, -1), 10),
                           ("TOPPADDING", (0, 0), (-1, -1), 8), ("BOTTOMPADDING", (0, 0), (-1, -1), 8)]))
    out = [t]
    if sub:
        out += [Spacer(1, 4), P(sub, "sub")]
    out.append(Spacer(1, 6))
    return out


def kpi(items):
    """핵심 수치 카드. items = [(라벨, 값, 색상(옵션))]"""
    w = CW / len(items)
    labels = [Paragraph(i[0], S["kpi_l"]) for i in items]
    values = []
    for i in items:
        c = i[2] if len(i) > 2 else None
        txt = col(i[1], c) if c else i[1]
        values.append(Paragraph(txt, S["kpi_v"]))
    t = Table([labels, values], colWidths=[w] * len(items))
    t.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, -1), LIGHT), ("LINEAFTER", (0, 0), (-2, -1), 2, colors.white),
                           ("TOPPADDING", (0, 0), (-1, 0), 6), ("BOTTOMPADDING", (0, 1), (-1, 1), 7),
                           ("TOPPADDING", (0, 1), (-1, 1), 0), ("BOTTOMPADDING", (0, 0), (-1, 0), 0),
                           ("VALIGN", (0, 0), (-1, -1), "MIDDLE")]))
    return t


_PS = {}
LINE = colors.HexColor("#D1D5DB")
_BASE_STYLE = [("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
               ("LEFTPADDING", (0, 0), (-1, -1), 3), ("RIGHTPADDING", (0, 0), (-1, -1), 3),
               ("TOPPADDING", (0, 0), (-1, -1), 2.2), ("BOTTOMPADDING", (0, 0), (-1, -1), 2.2),
               ("LINEBELOW", (0, 0), (-1, -1), 0.3, LINE), ("BOX", (0, 0), (-1, -1), 0.6, NAVY)]


def cell(text, size=8, align=0, bold=False, color=None):
    """표 칸. align: 0 왼쪽, 1 가운데, 2 오른쪽"""
    key = (size, align, bold, str(color), FONT)
    if key not in _PS:
        _PS[key] = ParagraphStyle(f"cell{len(_PS)}", fontName=FONT_B if bold else FONT, fontSize=size,
                                  leading=size * 1.3, alignment=align, textColor=color or INK)
    return Paragraph(text, _PS[key])


def fit(widths_mm):
    """열 폭(mm) 목록을 본문 폭에 맞춰 비례 조정한다."""
    tot = sum(widths_mm)
    return [CW * w / tot for w in widths_mm]


def data_table(head, rows, widths, aligns=None, size=7.5, spans=None, head_size=None):
    """머리글 + 본문 표. spans = [(시작행, 끝행)] 이면 첫 열을 그 행들에 걸쳐 병합(구분 열)."""
    n = len(head)
    aligns = aligns or [0] * n
    data = [[cell(h, head_size or size, 1, True, colors.white) for h in head]]
    for r in rows:
        data.append([cell(v, size, aligns[j], bold=(bool(spans) and j == 0)) for j, v in enumerate(r)])
    t = Table(data, colWidths=widths, repeatRows=1)
    st = _BASE_STYLE + [("BACKGROUND", (0, 0), (-1, 0), NAVY)]
    if spans:
        for a, b in spans:
            st.append(("BACKGROUND", (0, a + 1), (0, b + 1), LIGHT))
            if b > a:
                st.append(("SPAN", (0, a + 1), (0, b + 1)))
            if a > 0:
                st.append(("LINEABOVE", (0, a + 1), (-1, a + 1), 0.9, GRAY))
    else:
        st.append(("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, LIGHT]))
    t.setStyle(TableStyle(st))
    return t


def grouped_rows(groups, getter, start=0):
    """[(구분, [항목...])] → 표 행과 병합 범위. getter(항목순번, 항목명) → 값 칸 목록(이미 이스케이프된 문자열)"""
    rows, spans, idx = [], [], 0
    for gname, glabels in groups:
        a = start + len(rows)
        for k, lab in enumerate(glabels):
            rows.append([esc(gname) if k == 0 else "", esc(lab)] + list(getter(idx, lab)))
            idx += 1
        spans.append((a, start + len(rows) - 1))
    return rows, spans


def status_of(prep, short):
    if prep == "-":
        return "미보장"
    if short == "-":
        return "적정"
    return "부족"


STATUS_COLOR = {"적정": C_OK, "충분": C_OK, "부족": C_LOW, "미보장": C_NONE}


def status_cell(s):
    return f"<b>{col(s, STATUS_COLOR[s])}</b>"


def num_size(w_mm):
    return 7.5 if w_mm >= 14 else 6.5 if w_mm >= 10 else 5.8


