# ---- tall (세로 띠) ------------------------------------------------------------------------------
# 첫 쪽(표지) 맨 오른쪽의 남색 세로 띠 + 세로 글자 'KYOBO LIFE' + 초록 점. 이 그림의 이름이 'tall' 이다.
# logo_square(정사각형 로고)와는 다른 별개의 그림이며, 모든 쪽 오른쪽 끝에 표지와 똑같은 모양·크기로 넣는다.
# 좌표는 표지 설계 좌표(가로 1600 × 세로 900)를 쪽 크기에 맞춰 확대한 것이라 표지의 tall 과 완전히 같다.
TALL_NAME = "tall"
TALL_SHOW_ON_PAGES = True               # 모든 쪽 오른쪽에 tall 을 넣는다. False 면 표지에만 남는다
TALL_GREEN = colors.HexColor("#52AE30")


def draw_tall(c):
    """현재 쪽의 오른쪽 끝에 tall 을 그린다. (왼쪽 아래만 둥근 남색 띠, 위에서 아래로 읽히는 흰 글자, 초록 점)"""
    K = WIDE_W / 1600

    def X(x):
        return x * K

    def Y(y):
        return WIDE_H - y * K

    c.saveState()
    x0, x1, yb, r = X(1544), X(1600) + 4, Y(500), 24 * K
    p = c.beginPath()
    p.moveTo(x0, Y(-4))
    p.lineTo(x1, Y(-4))
    p.lineTo(x1, yb)
    p.lineTo(x0 + r, yb)
    p.curveTo(x0 + r * 0.45, yb, x0, yb + r * 0.45, x0, yb + r)
    p.close()
    c.setFillColor(COVER_BAR)
    c.drawPath(p, fill=1, stroke=0)
    c.saveState()
    c.translate(X(1566), Y(150))
    c.rotate(-90)                                             # 위에서 아래로 읽히는 세로 글자
    t = c.beginText(0, 0)
    t.setFont("Helvetica-Bold", 14.5 * K)
    t.setCharSpace(6.5 * K)
    t.setFillColor(colors.white)
    t.textOut("KYOBO LIFE")
    c.drawText(t)
    c.restoreState()
    c.setFillColor(TALL_GREEN)
    c.circle(X(1572), Y(405), 7 * K, fill=1, stroke=0)
    c.restoreState()


class CoverPage(Flowable):
    """첫 쪽(표지): 16:9 쪽 전체(여백 없이)를 채워 직접 그린다. 로고·펭귄은 내장 이미지.
    좌표는 가로 1600 × 세로 900 의 '설계 좌표'(왼쪽 위가 0,0)이며, 쪽 크기에 맞춰 비율 그대로 확대된다.
    왼쪽: 제목·담당 FP / 오른쪽: 로고·펭귄 가족 / 맨 오른쪽: 남색 세로 띠 / 맨 아래: 안내 문구·출력일"""
    DW, DH = 1600, 900
    GREEN = colors.HexColor("#52AE30")

    def __init__(self, cv, basis, width, height):
        super().__init__()
        self.cv, self.basis, self.width, self.height = cv, basis, width, height
        self.K = WIDE_W / self.DW                    # 설계 좌표 1 = K pt (쪽 가로 전체를 1600 으로 본다)

    def wrap(self, aw, ah):
        return self.width, self.height

    def X(self, x):
        return x * self.K

    def Y(self, y):
        return WIDE_H - y * self.K

    def _text(self, x, y, text, size, color, bold=False, align="L", track=0.0):
        """(x, y)=설계 좌표의 글자 기준선. 글자를 그리고 끝 x(설계 좌표)를 돌려준다. track=글자 사이 간격."""
        c, K = self.canv, self.K
        bold = bold or BOLD_ALL
        miss = bool(GLYPHS) and any(ord(ch) >= 128 and ord(ch) not in GLYPHS for ch in text)
        font = CID_FALLBACK if miss else (FONT_B if bold else FONT)
        fake_bold = bold and (miss or FONT_B == FONT or BOLD_FAKE)             # 굵은 글꼴이 없으면 테두리를 살짝 그려 굵게
        sz = size * K
        w = pdfmetrics.stringWidth(text, font, sz) / K + track * len(text)
        x0 = x - w if align == "R" else x
        t = c.beginText(self.X(x0), self.Y(y))
        t.setFont(font, sz)
        t.setFillColor(color)
        if track:
            t.setCharSpace(track * K)
        t.setTextRenderMode(2 if fake_bold else 0)          # 글자 그리기 방식은 다음 글자에도 이어지므로 매번 정한다
        if fake_bold:
            c.setStrokeColor(color)
            c.setLineWidth(sz * 0.022)
        t.textOut(text)
        c.drawText(t)
        return x0 + w

    def _image(self, name, x, y_top, w=None, h=None):
        """내장 이미지를 설계 좌표 (x, y_top)=왼쪽 위 에 놓는다. w 또는 h 중 하나만 주면 비율대로. -> (w, h)"""
        iw, ih = embedded_pil(name).size
        if w is None:
            w = h * iw / ih
        else:
            h = w * ih / iw
        self.canv.drawImage(ImageReader(io.BytesIO(embedded_png(name))), self.X(x), self.Y(y_top + h),
                            w * self.K, h * self.K, mask="auto")
        return w, h

    def draw(self):
        c, K, cv, X, Y = self.canv, self.K, self.cv, self.X, self.Y
        c.saveState()
        c.translate(-0.5, -0.5)                                   # 쪽 왼쪽 아래 모서리를 원점으로 (여백 없이 전체 사용)
        name = cv.get("name", "")
        ink, mute = colors.HexColor("#1B2433"), colors.HexColor("#6B7A90")
        # 0) 바탕: 흰색 + 쪽 밖으로 나가는 부분은 잘라냄
        c.setFillColor(colors.white)
        c.rect(-2, -2, WIDE_W + 4, WIDE_H + 4, fill=1, stroke=0)
        clip = c.beginPath()
        clip.rect(0, 0, WIDE_W, WIDE_H)
        c.clipPath(clip, stroke=0, fill=0)
        # 1) 오른쪽 큰 원(연한 하늘색 2겹) — 펭귄 뒤 배경
        for r, col in ((520, "#EFF4FA"), (385, "#E4ECF6")):
            c.setFillColor(colors.HexColor(col))
            c.circle(X(1148), Y(640), r * K, fill=1, stroke=0)
        c.setFillColor(self.GREEN)                                # 초록 점 장식(교보 새싹 색)
        c.circle(X(846), Y(432), 9 * K, fill=1, stroke=0)
        # 2) 제목
        x = self._text(150, 300, f"{name} 고객님", 36, ink, bold=True)
        self._text(x + 4, 300, "을 위한", 36, ink)
        x = self._text(146, 412, "보장분석", 92, COVER_NAVY, bold=True)
        self._text(x + 14, 412, "보고서", 92, COVER_NAVY)
        # 제목 밑줄: 남색 + 초록 + 회색
        for x0, x1, col in ((150, 400, COVER_NAVY), (400, 462, self.GREEN), (462, 760, colors.HexColor("#CDD4DD"))):
            c.setFillColor(col)
            c.rect(X(x0), Y(458), (x1 - x0) * K, 9 * K, fill=1, stroke=0)
        # 3) 담당 FP — 원본처럼 작게: 'Financial Planner 이름' 한 줄 + '소속: / H.P: / Email:' 줄
        c.setStrokeColor(colors.HexColor("#D5DBE3"))
        c.setLineWidth(1.2 * K)
        c.line(X(150), Y(570), X(480), Y(570))
        if cv.get("fp"):
            x = self._text(150, 616, "Financial Planner", 14, COVER_BLUE, bold=True, track=0.4)
            self._text(x + 10, 616, cv["fp"], 22, ink)
        y = 656
        for lab, key in (("소속: ", "branch"), ("H.P: ", "phone"), ("Email: ", "email")):
            if cv.get(key):
                self._text(150, y, lab + cv[key], 15.5, colors.HexColor("#2B3340"))
                y += 31
        # 4) 오른쪽 위 로고
        self._image("brand_logo", 1270, 64, w=235)
        # 5) 오른쪽 남색 세로 띠 'tall' (모든 쪽 공통 — draw_tall)
        draw_tall(c)
        # 6) 펭귄 가족 (아래쪽, 바닥에 부드러운 그림자)
        pw, ph = embedded_pil("penguin").size
        h = 585
        w = h * pw / ph
        cx, bottom = 1148, 838
        c.saveState()
        for i in range(9):                                        # 번지는 타원 그림자
            f = 1 - i / 9
            c.setFillColor(colors.Color(0.1, 0.18, 0.35, alpha=0.045))
            c.ellipse(X(cx - (w * 0.50) * f - 20), Y(bottom + 6 + 20 * f), X(cx + (w * 0.50) * f + 20), Y(bottom + 6 - 20 * f),
                      fill=1, stroke=0)
        c.restoreState()
        self._image("penguin", cx - w / 2, bottom - h, h=h)
        # 7) 아래 안내 문구 · 출력일
        c.setStrokeColor(colors.HexColor("#D5DBE3"))
        c.setLineWidth(1 * K)
        c.line(X(150), Y(856), X(1450), Y(856))
        self._text(150, 880, COVER_NOTE, 12, colors.HexColor("#4B5563"))
        pdate = cv.get("print_date") or self.basis
        if pdate:
            self._text(1450, 880, f"출력 | {pdate}", 12, colors.HexColor("#4B5563"), align="R")
        c.restoreState()


