def story_cover(cv, basis, entries):
    """로고·펭귄 이미지는 build_pdf 가 표지 위에 따로 넣는다 (축소 대상에서 제외)."""
    st = [Spacer(1, 6 * mm), P(f"{esc(cv['name'])} 고객님을 위한", "cover_sub"), P("보장분석 요약 보고서", "cover_title"),
          HRFlowable(width=70 * mm, thickness=3, color=NAVY, hAlign="LEFT"), Spacer(1, 8 * mm)]
    info = [[cell(f"<b>{lab}</b>", 9, 0, color=GRAY), cell(esc(cv[key]), 9)]
            for lab, key in (("Financial Planner", "fp"), ("소속", "branch"), ("H.P", "phone"), ("Email", "email"))
            if cv.get(key)]
    if info:
        t = Table(info, colWidths=[42 * mm, 90 * mm], hAlign="LEFT")
        t.setStyle(TableStyle([("LINEBELOW", (0, 0), (-1, -1), 0.3, LINE), ("TOPPADDING", (0, 0), (-1, -1), 3),
                               ("BOTTOMPADDING", (0, 0), (-1, -1), 3), ("LEFTPADDING", (0, 0), (-1, -1), 0)]))
        st += [t, Spacer(1, 8 * mm)]
    st += [Spacer(1, 5 * mm), P(f"분석 기준일 {basis or cv.get('print_date', '')} · 출력일 {cv.get('print_date', '')}", "sub")]
    return st


# ---- 보험 가입 현황 양식 (항상 이 양식으로 만든다) ------------------------------------------
ENROLL_SHOW_EXCLUDED_NOTE = True      # 목록에서 뺀 계약이 있을 때 '○건 제외' 한 줄 안내를 붙인다 (False 면 흔적 없이 삭제)
ENROLL_DONE_COLOR = "#2E7D5B"         # 완납 글자색
ENROLL_ING_COLOR = "#1F2937"          # 납입 중 글자색
ENROLL_CARD_BORDER = colors.HexColor("#D5DAE2")
COUNT_RE = re.compile(r"(\d+)\s*/\s*(\d+)\s*\(\s*(\d+)\s*\)")


def _int(text):
    digits = re.sub(r"[^\d]", "", text or "")
    return int(digits) if digits else 0


def parse_count(text):
    """'240/240(0)' → ('240', '240', '0')  (납입, 전체, 잔여 — 문자열 그대로). 형식이 다르면 None."""
    m = COUNT_RE.search(text or "")
    return m.groups() if m else None


def is_zero_zero(c):
    """월보험료가 0이고 납입횟수가 0인 계약인가. (이 쪽 목록에서 삭제하는 대상)"""
    pc = parse_count(c["count"])
    paid_zero = (_int(pc[0]) == 0) if pc else bool(re.match(r"\s*0\s*(/|$)", c["count"] or ""))
    return _int(c["premium"]) == 0 and paid_zero and _int(c.get("paid")) == 0      # 1.43: 기납입보험료가 있으면 내용이 있는 계약(일시납 등)


def short_product(name):
    """상품명을 짧게: (多) 같은 한자 괄호·無 제거 → 첫 '(' '[' '_' 앞까지."""
    t = re.sub(r"\([^)]*[\u4e00-\u9fff][^)]*\)", "", name or "")
    t = t.replace("無", "")
    return re.split(r"[(\[_]", t)[0].strip()


def kind_label(c):
    """'계약 현황' 칸에 쓰는 계약 종류. 종신 → 종신보험, 연금 → 개인연금보험/연금보험, 그 밖은 상품명(보험사 이름 머리글자 제외)."""
    short = short_product(c["name"])
    if "종신" in short:
        return "종신보험"
    if "연금" in short:
        return "개인연금보험" if "개인" in c["name"] else "연금보험"
    brand = (c["company"] or "")[:2]
    if brand and short.startswith(brand):
        short = short[len(brand):].strip()
    return short or c["name"]


# 완납 표시 앞에 붙이는 '보험 종류' 낱말 — (상품명에 들어 있는 말, 표시할 말). 위에서부터 먼저 맞는 것을 쓴다.
TYPE_KEYWORDS = (("건강", "건강"), ("암보험", "암"), ("어린이", "어린이"), ("운전자", "운전자"), ("실손", "실손"),
                 ("정기", "정기"), ("저축", "저축"), ("변액", "변액"), ("상해", "상해"), ("치아", "치아"),
                 ("간병", "간병"), ("치매", "치매"))


def type_label(c):
    """완납 표시 앞에 붙는 말: 종신 / 연금 / 건강 같은 짧은 종류 낱말. 종류를 알 수 없으면 빈 글자('' → 앞말 없이 표시).
    (1.24) 예전에는 상품명 전체에서 '보험'만 지워 썼기 때문에 '무배당 삼성화재 건강 누구나건강하게'처럼 길고 이름이 깨진 글이 나왔다."""
    short = short_product(c["name"])
    if "종신" in short:
        return "종신"
    if "연금" in short:
        return "연금"
    for needle, label in TYPE_KEYWORDS:
        if needle in short:
            return label
    kind = kind_label(c).replace("보험", "").strip()
    return kind if 0 < len(kind) <= 6 and " " not in kind else ""


def enrollment_model(d):
    """보험 가입 현황 쪽에 들어갈 글·숫자를 한곳에서 만든다. (숫자는 모두 원본 문자열 그대로)"""
    info, cs = d["info"], d["contracts"]
    n = info.get("n_contracts") or str(len(cs))
    monthly = info.get("monthly") or "0"
    paid_total = info.get("paid_total") or "0"
    shown = [c for c in cs if not is_zero_zero(c)]
    excluded = [c for c in cs if is_zero_zero(c)]
    items = []
    for c in shown:
        pc = parse_count(c["count"])
        done = bool(pc) and _int(pc[2]) == 0 and _int(pc[1]) > 0
        if done:
            status = f"{type_label(c)} {pc[0]}/{pc[1]}회 완납".strip()
        elif _int(c["premium"]) == 0 and _int(c.get("paid")) > 0:
            status = f"기납입 {c['paid']}원 완납"                 # 1.43: 월 0원·0회지만 일시납으로 이미 낸 계약
            done = True
        elif _int(c["premium"]) > 0:
            status = f"월 {c['premium']}원 납입 중"
        else:
            status = "납입 중"
        items.append(dict(c=c, kind=kind_label(c), status=status, done=done, rem=pc[2] if pc else ""))
    types = []
    for it in items:
        if it["done"] and type_label(it["c"]) and type_label(it["c"]) not in types:
            types.append(type_label(it["c"]))
    if types:
        subtitle = f"현재 총 {n}건의 보험 계약 유지, 주요 {', '.join(types)} 계약 완납"
    elif any(it["done"] for it in items):
        subtitle = f"현재 총 {n}건의 보험 계약 유지, 완납 계약 포함"
    elif _int(monthly) > 0:
        subtitle = f"현재 총 {n}건의 보험 계약 유지, 월 {monthly}원 납입 중"
    else:
        subtitle = f"현재 총 {n}건의 보험 계약 유지"
    ing = [it for it in items if not it["done"] and _int(it["c"]["premium"]) > 0]
    card1_sub = ", ".join(short_product(it["c"]["name"]) + (f" (잔여 {it['rem']}회)" if it["rem"] else "") for it in ing) \
        or "납입 중인 계약 없음"
    groups = []                                        # 보험사별로 묶기 (처음 나온 순서)
    for it in items:
        comp = it["c"]["company"]
        for g in groups:
            if g["company"] == comp:
                g["items"].append(it)
                break
        else:
            groups.append(dict(company=comp, items=[it]))
    return dict(n=n, monthly=monthly, paid_total=paid_total, title=f"유지 계약 {n}건, 월 보험료는 {monthly}원",
                subtitle=subtitle, card1_sub=card1_sub, card2_sub=f"총 {n}건 계약의 총 납입 완료액",
                groups=groups, items=items, excluded=excluded)


ENROLL_BODY_RATIO = 2 / 3               # 보험 가입 현황 쪽: 본문(제목·카드·목록)이 차지하는 가로 비율 (왼쪽)
ENROLL_GAP = 8 * mm                     # 본문과 오른쪽 장식 사이 간격
ENROLL_PANEL_MIN_H = 95 * mm            # 오른쪽 장식 최소 높이 (본문이 짧을 때)
PANEL_NAVY = colors.Color(18 / 255, 28 / 255, 114 / 255)   # logo_square 바탕색 (#121C72) — 장식 선 색
PANEL_GREEN = colors.HexColor("#4CBB4C")                    # logo_square 새싹 초록 — 장식 선 색

# ---- 스퀘어 엠블럼 (Square Emblem) ------------------------------------------------------------------
# 보험 가입 현황 쪽 오른쪽 1/3 장식의 이름. (v1.16~ 현재 디자인)
#   배경 : 체크리스트 그림('checklist', 내장)을 채도·대비를 낮추고 연한 하늘색 톤으로 섞어 강하지 않게 깔았다.
#   중심 : 교보 logo_square 를 '종이 한 장'처럼 눕혔다 — 흰 종이 테두리 + 살짝 기울임 + 부드러운 그림자, 뒤에 연한 종이 한 장 더.
#          logo_square 그림은 크기만 바꾸고 자르기·색·비율은 그대로다.
#   틀   : 둥근 모서리 + 가는 남색 테두리 선.  글자·숫자는 넣지 않는다.
# 아래 값을 바꾸면 모양이 바뀌며, 값이 같으면 언제 만들어도 똑같은 그림이 나온다.
EMBLEM_NAME = "스퀘어 엠블럼"
EMBLEM_PX_W = 900                       # 그림을 만드는 가로 픽셀 (세로는 쪽에 놓일 비율대로)
EMBLEM_BG_CROP = 12                     # 체크리스트 원본 가장자리 여백(px) 제거
EMBLEM_BG_SATURATION = 0.62             # 채도 (1 = 원본)
EMBLEM_BG_CONTRAST = 0.90               # 대비
EMBLEM_BG_TONE = (232, 240, 250)        # 섞는 연한 하늘색
EMBLEM_BG_TONE_MIX = 0.34               # 위 색을 섞는 비율
EMBLEM_BG_BLUR = 1.2                    # 배경 부드럽게(px)
EMBLEM_EDGE_FADE = 60                   # 위·아래 가장자리를 옅게 만드는 세기(0~255)
EMBLEM_LOGO_RATIO = 0.42                # 로고 한 변 ÷ 패널 가로
EMBLEM_LOGO_CY = 0.44                   # 로고 중심의 세로 위치(0=위, 1=아래)
EMBLEM_LOGO_ANGLE = -6                  # 로고 종이 기울기(도)
EMBLEM_BACK_ANGLE = 6                   # 뒤 종이 기울기(도)
EMBLEM_BACK_DX, EMBLEM_BACK_DY = 34, 20 # 뒤 종이 위치 어긋남(px, 가로 900 기준)
EMBLEM_BORDER = (18, 28, 114, 70)       # 패널 테두리 선 색(남색, 투명도)
_EMBLEM_CACHE = {}


def make_emblem_png(w_pt, h_pt):
    """스퀘어 엠블럼 그림(PNG 바이트)을 만든다. w_pt:h_pt 비율대로 만들며, 같은 크기는 한 번만 만든다."""
    from PIL import Image as PI, ImageDraw, ImageFilter, ImageEnhance
    W = EMBLEM_PX_W
    H = max(int(round(W * h_pt / w_pt)), 200)
    key = (W, H)
    if key in _EMBLEM_CACHE:
        return _EMBLEM_CACHE[key]
    k = W / 900.0                                                   # 900 기준으로 정한 길이를 실제 가로에 맞춤
    tone = EMBLEM_BG_TONE
    # 1) 배경: 체크리스트 — 여백 제거 → 패널에 꽉 차게 → 채도·대비 낮춤 → 연한 톤 섞기 → 부드럽게
    src = embedded_pil("checklist").convert("RGB")
    c = EMBLEM_BG_CROP
    src = src.crop((c, c, src.size[0] - c, src.size[1] - c))
    sw, sh = src.size
    sc = max(W / sw, H / sh)
    bg = src.resize((int(sw * sc) + 1, int(sh * sc) + 1), PI.LANCZOS)
    ox, oy = (bg.width - W) // 2, (bg.height - H) // 2
    bg = bg.crop((ox, oy, ox + W, oy + H))
    bg = ImageEnhance.Color(bg).enhance(EMBLEM_BG_SATURATION)
    bg = ImageEnhance.Contrast(bg).enhance(EMBLEM_BG_CONTRAST)
    bg = PI.blend(bg, PI.new("RGB", (W, H), tone), EMBLEM_BG_TONE_MIX)
    bg = bg.filter(ImageFilter.GaussianBlur(EMBLEM_BG_BLUR * k))
    panel = bg.convert("RGBA")
    fade = PI.new("L", (W, H), 0)                                   # 위·아래 가장자리를 더 옅게
    dr = ImageDraw.Draw(fade)
    for y in range(H):
        t = abs(y - H * 0.5) / (H * 0.5)
        dr.line([(0, y), (W, y)], fill=int(EMBLEM_EDGE_FADE * t ** 2))
    panel = PI.composite(PI.new("RGBA", (W, H), tone + (255,)), panel, fade)

    # 2) 로고 종이 (logo_square 는 크기만 조절)
    logo = embedded_pil("logo_square").convert("RGBA")
    lpx = int(W * EMBLEM_LOGO_RATIO)

    def sheet(pad, fill):
        sz = lpx + 2 * pad
        paper = PI.new("RGBA", (sz, sz), (0, 0, 0, 0))
        ImageDraw.Draw(paper).rounded_rectangle((0, 0, sz - 1, sz - 1), radius=int(26 * k), fill=fill)
        paper.alpha_composite(logo.resize((lpx, lpx), PI.LANCZOS), (pad, pad))
        return paper

    def shadow(img, blur, alpha):
        a = img.split()[3].point(lambda v: int(v * alpha))
        sh = PI.new("RGBA", img.size, (30, 45, 90, 0))
        sh.putalpha(a)
        pad = blur * 3
        big = PI.new("RGBA", (img.width + 2 * pad, img.height + 2 * pad), (0, 0, 0, 0))
        big.alpha_composite(sh, (pad, pad))
        return big.filter(ImageFilter.GaussianBlur(blur)), pad

    back = sheet(int(22 * k), (255, 255, 255, 235)).rotate(EMBLEM_BACK_ANGLE, resample=PI.BICUBIC, expand=True)
    main = sheet(int(26 * k), (255, 255, 255, 255)).rotate(EMBLEM_LOGO_ANGLE, resample=PI.BICUBIC, expand=True)
    tint = PI.new("RGBA", back.size, (226, 233, 244, 255))          # 뒤 종이는 연한 톤으로 눌러 강하지 않게
    tint.putalpha(back.split()[3])
    back = PI.composite(tint, back, PI.new("L", back.size, 120))
    back.putalpha(tint.split()[3])
    cx, cy = W // 2, int(H * EMBLEM_LOGO_CY)
    bx, by = int(EMBLEM_BACK_DX * k), int(EMBLEM_BACK_DY * k)
    sh, pad = shadow(back, int(22 * k), 0.35)
    panel.alpha_composite(sh, (cx - back.width // 2 - pad + bx, cy - back.height // 2 - pad + by + int(30 * k)))
    panel.alpha_composite(back, (cx - back.width // 2 + bx, cy - back.height // 2 + by))
    sh, pad = shadow(main, int(26 * k), 0.45)
    panel.alpha_composite(sh, (cx - main.width // 2 - pad, cy - main.height // 2 - pad + int(34 * k)))
    panel.alpha_composite(main, (cx - main.width // 2, cy - main.height // 2))

    # 3) 둥근 모서리 + 가는 테두리 선
    rad = int(34 * k)
    mask = PI.new("L", (W, H), 0)
    ImageDraw.Draw(mask).rounded_rectangle((0, 0, W - 1, H - 1), radius=rad, fill=255)
    out = PI.new("RGBA", (W, H), (0, 0, 0, 0))
    out.paste(panel, (0, 0), mask)
    ImageDraw.Draw(out).rounded_rectangle((1, 1, W - 2, H - 2), radius=rad, outline=EMBLEM_BORDER, width=max(int(3 * k), 1))
    buf = io.BytesIO()
    out.save(buf, "PNG")
    _EMBLEM_CACHE[key] = buf.getvalue()
    return _EMBLEM_CACHE[key]


# ---- 진단 엠블럼 (Gauge Emblem) -----------------------------------------------------------------------
# 종합 진단 쪽 오른쪽 1/3 그림의 이름. (v1.50) 스퀘어 엠블럼과 다른 새 디자인이다.
#   배경 : 아주 옅은 하늘색에서 흰색으로 이어지는 세로 바탕.
#   장식 : 로고를 둘러싼 동심원 3겹. 가운데 굵은 호는 보장 적정(초록 청록), 부족(주황), 미보장(빨강)을 뜻하는 색 순서,
#          바깥은 가는 남색 호, 안쪽은 점선 고리. 숫자·글자는 넣지 않으며 고객이 달라도 같은 그림이다.
#   중심 : 교보 logo_square 를 흰 종이 테두리 + 살짝 기울임 + 부드러운 그림자로 올렸다. 로고 그림은 크기만 바꾸고 자르기·색·비율은 그대로다.
#   틀   : 둥근 모서리 + 가는 남색 테두리 선.
GAUGE_NAME = "진단 엠블럼"
GAUGE_PX_W = 900
GAUGE_BG_TOP = (232, 239, 249)          # 바탕 위쪽 색
GAUGE_BG_BOTTOM = (252, 253, 255)       # 바탕 아래쪽 색
GAUGE_CY = 0.43                         # 고리 중심의 세로 위치(0=위, 1=아래)
GAUGE_LOGO_RATIO = 0.36                 # 로고 한 변 ÷ 패널 가로
GAUGE_LOGO_ANGLE = -6                   # 로고 종이 기울기(도)
GAUGE_RADII = (0.275, 0.385, 0.495)     # 안쪽 점선 고리, 가운데 굵은 호, 바깥 가는 호의 반지름 ÷ 패널 가로
GAUGE_ARCS = (("#1B8A80", 196), ("#E28F3C", 84), ("#C4474A", 66))   # 굵은 호의 (색, 각도)
GAUGE_ARC_GAP = 7                       # 호 사이 틈(도)
GAUGE_ARC_START = -90                   # 첫 호 시작 각도(위쪽)
GAUGE_ARC_W = 20                        # 굵은 호 두께(px, 가로 900 기준)
GAUGE_BORDER = (18, 28, 114, 70)
_GAUGE_CACHE = {}


def make_gauge_png(w_pt, h_pt):
    """진단 엠블럼 그림(PNG 바이트). w_pt:h_pt 비율대로 만들며 같은 크기는 한 번만 만든다."""
    from PIL import Image as PI, ImageDraw, ImageFilter
    W = GAUGE_PX_W
    H = max(int(round(W * h_pt / w_pt)), 200)
    key = (W, H)
    if key in _GAUGE_CACHE:
        return _GAUGE_CACHE[key]
    k = W / 900.0
    SS = 2                                                           # 2배로 그린 뒤 줄여 선을 부드럽게
    w2, h2 = W * SS, H * SS
    top, bot = GAUGE_BG_TOP, GAUGE_BG_BOTTOM
    bg = PI.new("RGBA", (1, h2))
    for y in range(h2):
        t = y / max(h2 - 1, 1)
        bg.putpixel((0, y), tuple(int(top[i] + (bot[i] - top[i]) * t) for i in range(3)) + (255,))
    panel = bg.resize((w2, h2))
    cx, cy = w2 // 2, int(h2 * GAUGE_CY)
    ov = PI.new("RGBA", (w2, h2), (0, 0, 0, 0))
    d = ImageDraw.Draw(ov)
    r_in, r_mid, r_out = [int(r * w2) for r in GAUGE_RADII]
    # 바깥: 가는 남색 호 (위쪽이 끊기지 않게 거의 한 바퀴, 한 군데만 비움)
    d.arc((cx - r_out, cy - r_out, cx + r_out, cy + r_out), start=-70, end=215, fill=(18, 28, 114, 70), width=int(3 * k * SS))
    d.arc((cx - r_out, cy - r_out, cx + r_out, cy + r_out), start=235, end=250, fill=(18, 28, 114, 70), width=int(3 * k * SS))
    # 가운데: 굵은 세 호
    ang = GAUGE_ARC_START
    aw = int(GAUGE_ARC_W * k * SS)
    for col, deg in GAUGE_ARCS:
        rgb = tuple(int(col[i:i + 2], 16) for i in (1, 3, 5))
        d.arc((cx - r_mid, cy - r_mid, cx + r_mid, cy + r_mid), start=ang, end=ang + deg, fill=rgb + (235,), width=aw)
        ang += deg + GAUGE_ARC_GAP
    # 안쪽: 점선 고리 (작은 점 60개)
    import math
    for i in range(60):
        a = math.radians(i * 6)
        px, py = cx + r_in * math.cos(a), cy + r_in * math.sin(a)
        rr = int(3.2 * k * SS)
        d.ellipse((px - rr, py - rr, px + rr, py + rr), fill=(18, 28, 114, 90))
    # 초록 새싹 점 3개 (로고 새싹 색)
    for ang_d, rad_, rr in ((-40, r_out, 11), (150, r_out, 8), (35, r_in, 9)):
        a = math.radians(ang_d)
        px, py, rr = cx + rad_ * math.cos(a), cy + rad_ * math.sin(a), int(rr * k * SS)
        d.ellipse((px - rr, py - rr, px + rr, py + rr), fill=(76, 187, 76, 255))
    panel = PI.alpha_composite(panel, ov).resize((W, H), PI.LANCZOS)
    cx, cy = W // 2, int(H * GAUGE_CY)
    # 로고 뒤 흰 원 (고리 안을 차분하게)
    glow = PI.new("RGBA", (W, H), (0, 0, 0, 0))
    rg = int(GAUGE_RADII[0] * W) - int(12 * k)
    ImageDraw.Draw(glow).ellipse((cx - rg, cy - rg, cx + rg, cy + rg), fill=(255, 255, 255, 235))
    panel.alpha_composite(glow)
    # 중심: logo_square 종이 (크기만 조절)
    logo = embedded_pil("logo_square").convert("RGBA")
    lpx = int(W * GAUGE_LOGO_RATIO)
    pad = int(20 * k)
    sz = lpx + 2 * pad
    paper = PI.new("RGBA", (sz, sz), (0, 0, 0, 0))
    ImageDraw.Draw(paper).rounded_rectangle((0, 0, sz - 1, sz - 1), radius=int(24 * k), fill=(255, 255, 255, 255))
    paper.alpha_composite(logo.resize((lpx, lpx), PI.LANCZOS), (pad, pad))
    paper = paper.rotate(GAUGE_LOGO_ANGLE, resample=PI.BICUBIC, expand=True)
    sh = PI.new("RGBA", paper.size, (30, 45, 90, 0))
    sh.putalpha(paper.split()[3].point(lambda v: int(v * 0.42)))
    blur = int(24 * k)
    big = PI.new("RGBA", (paper.width + 6 * blur, paper.height + 6 * blur), (0, 0, 0, 0))
    big.alpha_composite(sh, (3 * blur, 3 * blur))
    big = big.filter(ImageFilter.GaussianBlur(blur))
    panel.alpha_composite(big, (cx - big.width // 2, cy - big.height // 2 + int(30 * k)))
    panel.alpha_composite(paper, (cx - paper.width // 2, cy - paper.height // 2))
    # 틀: 둥근 모서리 + 가는 테두리 선
    rad = int(34 * k)
    mask = PI.new("L", (W, H), 0)
    ImageDraw.Draw(mask).rounded_rectangle((0, 0, W - 1, H - 1), radius=rad, fill=255)
    out = PI.new("RGBA", (W, H), (0, 0, 0, 0))
    out.paste(panel, (0, 0), mask)
    ImageDraw.Draw(out).rounded_rectangle((1, 1, W - 2, H - 2), radius=rad, outline=GAUGE_BORDER, width=max(int(3 * k), 1))
    buf = io.BytesIO()
    out.save(buf, "PNG")
    _GAUGE_CACHE[key] = buf.getvalue()
    return _GAUGE_CACHE[key]


class SquareEmblem(Flowable):
    """스퀘어 엠블럼 — 보험 가입 현황 쪽 오른쪽 1/3. 그림은 make_emblem_png 가 만든다. 글자·숫자는 넣지 않는다."""

    def __init__(self, width, height):
        super().__init__()
        self.width, self.height = width, height

    def wrap(self, aw, ah):
        return self.width, self.height

    def draw(self):
        png = make_emblem_png(self.width, self.height)
        self.canv.drawImage(ImageReader(io.BytesIO(png)), 0, 0, width=self.width, height=self.height, mask="auto")


class InfoCard(Flowable):
    """둥근 테두리 카드: 작은 이름 / 큰 숫자+단위 / 보조 설명."""
    PAD = 5 * mm

    def __init__(self, label, value, unit, sub, width):
        super().__init__()
        self.width = width
        self.parts = [Paragraph(esc(label), S["en_card_l"]),
                      Paragraph(f'<font size="27"><b>{esc(value)}</b></font><font size="14">{esc(unit)}</font>', S["en_card_v"]),
                      Paragraph(esc(sub), S["en_card_s"])]
        self.fixed_h = None

    def natural(self):
        iw = self.width - 2 * self.PAD
        return sum(p.wrap(iw, 1000)[1] for p in self.parts) + 2 * self.PAD + 2 * mm

    def wrap(self, aw, ah):
        self.height = self.fixed_h or self.natural()
        return self.width, self.height

    def draw(self):
        c = self.canv
        c.saveState()
        c.setFillColor(colors.white)
        c.setStrokeColor(ENROLL_CARD_BORDER)
        c.setLineWidth(0.9)
        c.roundRect(0.5, 0.5, self.width - 1, self.height - 1, 3.2 * mm, stroke=1, fill=1)
        c.restoreState()
        y = self.height - self.PAD
        for i, p in enumerate(self.parts):
            w, h = p.wrap(self.width - 2 * self.PAD, 1000)
            p.drawOn(c, self.PAD, y - h)
            y -= h + (1 * mm if i == 0 else 1 * mm)


def story_enrollment(d, src, name):
    m = enrollment_model(d)
    LW = CW * ENROLL_BODY_RATIO - ENROLL_GAP                 # 왼쪽 본문 폭 (전체의 2/3 에서 간격 뺀 값)
    tag = (f"{name} 고객님 · " if name else "") + f"원본 p.{src}"
    top = Table([[Paragraph("계약 및 납입 현황", S["en_small"]), Paragraph(esc(tag), S["en_tag"])]],
                colWidths=[LW - 60 * mm, 60 * mm])
    top.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                             ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
                             ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    st = [top, Spacer(1, 3 * mm), Paragraph(esc(m["title"]), S["en_title"]), Spacer(1, 2 * mm),
          Paragraph(esc(m["subtitle"]), S["en_sub"]), Spacer(1, 6 * mm)]
    gap = 6 * mm
    cw = (LW - gap) / 2
    c1 = InfoCard("현재 월 납입보험료", m["monthly"], "원", m["card1_sub"], cw)
    c2 = InfoCard("누적 기납입보험료", m["paid_total"], "원", m["card2_sub"], cw)
    c1.fixed_h = c2.fixed_h = max(c1.natural(), c2.natural())
    cards = Table([[c1, "", c2]], colWidths=[cw, gap, cw])
    cards.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                               ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0)]))
    st += [cards, Spacer(1, 7 * mm)]

    def line(it, text, status=False):
        if not status:
            return esc(text)
        color = ENROLL_DONE_COLOR if it["done"] else ENROLL_ING_COLOR
        return f'<font color="{color}"><b>{esc(text)}</b></font>'

    rows = [[Paragraph("보험사", S["en_th"]), Paragraph("계약 현황", S["en_th"]), Paragraph("납입 상태", S["en_th"])]]
    # (1.24) 계약 한 건 = 표 한 줄. 예전에는 칸마다 <br/> 로 이어 붙여서, 상품명이 두 줄로 접히면 납입 상태가
    # 다른 계약 옆으로 밀렸다. 보험사 칸은 그 보험사의 줄들을 하나로 합쳐(SPAN) 보여 준다.
    cmds = [("LINEBELOW", (0, 0), (-1, 0), 1.0, colors.HexColor("#BFC5CF")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"), ("LEFTPADDING", (0, 0), (-1, -1), 5),
            ("RIGHTPADDING", (0, 0), (-1, -1), 5), ("TOPPADDING", (0, 0), (-1, -1), 1.5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 1.5), ("TOPPADDING", (0, 0), (-1, 0), 6),
            ("BOTTOMPADDING", (0, 0), (-1, 0), 6)]
    for g in m["groups"]:
        r0 = len(rows)
        for k, it in enumerate(g["items"]):
            rows.append([Paragraph(esc(f"{g['company']} ({len(g['items'])}건)"), S["en_td"]) if k == 0 else "",
                         Paragraph(line(it, it["kind"]), S["en_td"]),
                         Paragraph(line(it, it["status"], True), S["en_td"])])
        r1 = len(rows) - 1
        if r1 > r0:
            cmds.append(("SPAN", (0, r0), (0, r1)))
        cmds += [("TOPPADDING", (0, r0), (-1, r0), 6), ("BOTTOMPADDING", (0, r1), (-1, r1), 6),
                 ("LINEBELOW", (0, r1), (-1, r1), 0.6, colors.HexColor("#E1E5EB"))]
    if len(rows) == 1:
        rows.append([Paragraph("표시할 계약 없음", S["en_td"]), "", ""])
    tb = Table(rows, colWidths=[LW * 0.24, LW * 0.36, LW * 0.40])
    tb.setStyle(TableStyle(cmds))
    st.append(tb)
    if m["excluded"] and ENROLL_SHOW_EXCLUDED_NOTE:
        st += [Spacer(1, 3 * mm),
               Paragraph(f"※ 월 보험료 0원 · 납입 0회인 계약 {len(m['excluded'])}건은 목록에서 제외.", S["en_note"])]
    body_h = natural_height(st, LW)
    panel = SquareEmblem(CW * (1 - ENROLL_BODY_RATIO), max(body_h, ENROLL_PANEL_MIN_H))
    outer = Table([[st, panel]], colWidths=[CW * ENROLL_BODY_RATIO, CW * (1 - ENROLL_BODY_RATIO)])
    outer.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (0, 0), ENROLL_GAP),
                               ("RIGHTPADDING", (1, 0), (1, 0), 0), ("TOPPADDING", (0, 0), (-1, -1), 0),
                               ("BOTTOMPADDING", (0, 0), (-1, -1), 0), ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    return [outer]                                           # 왼쪽 2/3 본문 + 오른쪽 1/3 스퀘어 엠블럼




# ----------------------------------------------------------------------------
# 5-B. 표 쪽 공통 양식 — 표로 표현할 수 있는 데이터는 항상 '보험 가입 현황'과 같은 형식으로 만든다.
#   작은 제목(+고객명·원본 쪽) → 큰 제목 문장 → 한 줄 설명 → 카드 2~3개 → 목록 표
#   목록 표 모양(머리줄 아래 굵은 회색 선·행 사이 옅은 선·숫자 오른쪽 정렬)은 보험 가입 현황의 목록과 같다.
#   표 열이 적으면(TP_EMBLEM_MAX_COLS 이하) 본문 2/3 + 오른쪽 1/3 스퀘어 엠블럼, 넓으면 쪽 전체 폭.
# ----------------------------------------------------------------------------
TP_NAME = "표 쪽 공통 양식"
TP_TITLE_PT = 18                 # 큰 제목 글자 크기 (보험 가입 현황은 25pt — 표 쪽은 표 공간 때문에 줄였다)
TP_SUB_PT = 10                   # 한 줄 설명 글자 크기
TP_CARD_VALUE_PT = 18            # 카드 큰 숫자 크기
TP_TH_PT = 8.5                   # 목록 표 머리글 크기
TP_TD_PT = 7.6                     # 목록 표 본문 크기
TP_ROW_PAD = 1.2                 # 목록 표 행 위·아래 여백(pt)
TP_EMBLEM_MAX_COLS = 6           # 표 열이 이 값 이하면 본문 2/3 + 스퀘어 엠블럼
TP_HEAD_LINE = colors.HexColor("#BFC5CF")      # 머리줄 아래·구분 시작 선 (보험 가입 현황 목록과 같은 색)
TP_ROW_LINE = colors.HexColor("#E1E5EB")       # 행 사이 선 (보험 가입 현황 목록과 같은 색)


def wfit(weights, width):
    tot = float(sum(weights))
    return [width * w / tot for w in weights]


def list_table_style():
    """보험 가입 현황 목록과 같은 표 모양: 머리줄 아래 굵은 선, 행 사이 옅은 선, 배경색·바깥 테두리 없음."""
    return [("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("LEFTPADDING", (0, 0), (-1, -1), 4), ("RIGHTPADDING", (0, 0), (-1, -1), 4),
            ("TOPPADDING", (0, 0), (-1, -1), TP_ROW_PAD), ("BOTTOMPADDING", (0, 0), (-1, -1), TP_ROW_PAD),
            ("LINEBELOW", (0, 0), (-1, 0), 1.0, TP_HEAD_LINE), ("LINEBELOW", (0, 1), (-1, -1), 0.5, TP_ROW_LINE)]


def list_table(head, rows, widths, aligns=None, size=None, spans=None):
    """보험 가입 현황 목록 모양의 표. spans = [(시작행, 끝행)] 이면 첫 열(구분)을 그 행들에 걸쳐 병합한다."""
    size = size or TP_TD_PT
    n = len(head)
    aligns = aligns or [0] * n
    data = [[cell(h, max(size, TP_TH_PT) if size >= TP_TD_PT else size, aligns[j], True, INK) for j, h in enumerate(head)]]
    for r in rows:
        data.append([cell(v, size, aligns[j], bold=(bool(spans) and j == 0)) for j, v in enumerate(r)])
    t = Table(data, colWidths=widths, repeatRows=1, hAlign="LEFT")
    st = list_table_style()
    for a, b in (spans or []):
        if b > a:
            st.append(("SPAN", (0, a + 1), (0, b + 1)))
        st.append(("VALIGN", (0, a + 1), (0, b + 1), "TOP"))
        if a > 0:
            st.append(("LINEABOVE", (0, a + 1), (-1, a + 1), 0.9, TP_HEAD_LINE))
    t.setStyle(TableStyle(st))
    return t


class CompactCard(InfoCard):
    """표 쪽용 카드 — 보험 가입 현황 카드와 같은 모양(둥근 테두리: 이름 / 큰 숫자+단위 / 보조 설명)을 작게."""
    PAD = 2.6 * mm

    def natural(self):
        iw = self.width - 2 * self.PAD
        return sum(p.wrap(iw, 1000)[1] for p in self.parts) + 2 * self.PAD

    def __init__(self, label, value, unit, sub, width):
        Flowable.__init__(self)
        self.width = width
        self.parts = [Paragraph(esc(label), S["tp_card_l"]),
                      Paragraph(f'<font size="{TP_CARD_VALUE_PT}"><b>{esc(value)}</b></font><font size="11">{esc(unit)}</font>',
                                S["tp_card_v"])]
        if sub:
            self.parts.append(Paragraph(esc(sub), S["tp_card_s"]))
        self.fixed_h = None


def tp_cards(cards, width, gap=5 * mm):
    """cards = [(이름, 값, 단위, 보조 설명)] 2~3개를 같은 높이로 나란히."""
    n = len(cards)
    cw = (width - gap * (n - 1)) / n
    cs = [CompactCard(l, v, u, sb, cw) for (l, v, u, sb) in cards]
    h = max(c.natural() for c in cs)
    row, widths = [], []
    for i, c in enumerate(cs):
        c.fixed_h = h
        if i:
            row.append("")
            widths.append(gap)
        row.append(c)
        widths.append(cw)
    t = Table([row], colWidths=widths, hAlign="LEFT")
    t.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                           ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0)]))
    return t


def side_by_side(left, right, width, gap=6 * mm):
    hw = (width - gap) / 2
    t = Table([[left, "", right]], colWidths=[hw, gap, hw], hAlign="LEFT")
    t.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                           ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
                           ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    return t


def table_page(src, small, title, subtitle, cards, body_fn, emblem=False, notes=()):
    """표 쪽 공통 양식. body_fn(W) → 본문 폭 W 에 맞춘 표 등 flowable 목록.
    emblem=True 이면 보험 가입 현황과 같이 본문 2/3 + 오른쪽 1/3 스퀘어 엠블럼, False 이면 쪽 전체 폭."""
    W = (CW * ENROLL_BODY_RATIO - ENROLL_GAP) if emblem else CW
    tag = (f"{CUSTOMER_NAME} 고객님 · " if CUSTOMER_NAME else "") + f"원본 p.{src}"
    top = Table([[Paragraph(esc(small), S["en_small"]), Paragraph(esc(tag), S["en_tag"])]], colWidths=[W - 60 * mm, 60 * mm], hAlign="LEFT")
    top.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                             ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
                             ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    st = [top, Spacer(1, 1.5 * mm), Paragraph(esc(title), S["tp_title"]), Spacer(1, 0.5 * mm),
          Paragraph(esc(subtitle), S["tp_sub"]), Spacer(1, 2.5 * mm)]
    if cards:
        st += [tp_cards(cards, W), Spacer(1, 3 * mm)]
    st += list(body_fn(W))
    for n_ in notes:
        st += [Spacer(1, 2 * mm), Paragraph(esc(n_), S["en_note"])]
    if not emblem:
        return st
    body_h = natural_height(st, W)
    panel = SquareEmblem(CW * (1 - ENROLL_BODY_RATIO), max(body_h, ENROLL_PANEL_MIN_H))
    outer = Table([[st, panel]], colWidths=[CW * ENROLL_BODY_RATIO, CW * (1 - ENROLL_BODY_RATIO)], hAlign="LEFT")
    outer.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (0, 0), ENROLL_GAP),
                               ("RIGHTPADDING", (1, 0), (1, 0), 0), ("TOPPADDING", (0, 0), (-1, -1), 0),
                               ("BOTTOMPADDING", (0, 0), (-1, -1), 0), ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    return [outer]


def story_generation(d, src):
    cnt, members = d["counts"], d["members"]
    n = len(members)
    names = ", ".join(m["name"] for m in members)
    head = ["구분", "항목"] + [f"{esc(m['name'])}<br/>({m['age']}세)" for m in members]
    ra, sa = grouped_rows(GROUPS_A, lambda i, l: [esc(m["a"][i]) for m in members])
    rb, sb = grouped_rows(GROUPS_B, lambda i, l: [esc(m["b"][i]) for m in members])

    def body(W):                                             # 긴 표라서 같은 높이의 좌우 두 표로 나눈다 (사망·진단 | 그 밖)
        wd = wfit([17, 25] + [58.0 / n] * n, (W - 6 * mm) / 2)
        al = [0, 0] + [2] * n
        return [side_by_side(list_table(head, ra, wd, al, spans=sa), list_table(head, rb, wd, al, spans=sb), W)]
    cards = []
    if cnt:
        sub = " · ".join(f"{lab} {cnt[k]}건" for lab, k in (("교보생명", "kyobo"), ("생명보험", "life"),
                                                           ("손해보험", "nonlife"), ("공제/우체국", "mutual")))
        cards.append(("유지 계약", cnt["total"], "건", sub))
    cards.append(("분석 구성원", str(n), "명", ", ".join(f"{m['name']} ({m['age']}세)" for m in members)))
    title = (f"유지 계약 {cnt['total']}건, " if cnt else "") + f"{names} 고객님의 보장 준비 금액"
    return table_page(src, "세대 분석", title, "가족 구성원별 보장항목 준비 금액 (단위: 만원)",
                      cards, body, emblem=False)


def story_products(d, src, title, labels, groups):
    n = len(labels)
    need, prep, short = d["need"], d["prep"], d["short"]
    stat = [status_of(prep[i], short[i]) for i in range(n)]
    cnt = {k: stat.count(k) for k in ("적정", "부족", "미보장")}
    h = d["head"]
    if h:
        scope, total, ok, low, none = "전체", h["total"], h["ok"], h["low"], h["none"]
    else:
        scope, total, ok, low, none = "이 쪽", str(n), str(cnt["적정"]), str(cnt["부족"]), str(cnt["미보장"])
    shown = [(k, p) for k, p in enumerate(d["products"], 1) if any(v != "-" for v in p["vals"])]
    m = len(shown)

    def body(W):
        fixed = [26, 38, 18, 18, 18, 16]
        pw = max(min((269 - sum(fixed)) / m, 22), 8) if m else 0
        size = TP_TD_PT if m <= 6 else 7
        head = ["구분", "항목", "필요", "준비", "부족", "상태"] + [str(k) for k, _ in shown]
        rows, spans = grouped_rows(groups, lambda i, l: [esc(need[i]), esc(prep[i]), esc(short[i])])
        for i, r in enumerate(rows):
            r.insert(5, status_cell(stat[i]))
            r.extend(esc(p["vals"][i]) for _, p in shown)
        if not shown:
            return [list_table(head, rows, wfit(fixed, W), [0, 0, 2, 2, 2, 1], size, spans)]
        gap = 6 * mm
        wl = (W - gap) * 0.62                                  # 왼쪽: 항목별 표, 오른쪽: 번호별 상품 목록 (나란히)
        left = list_table(head, rows, wfit(fixed + [min(pw, 14)] * m, wl), [0, 0, 2, 2, 2, 1] + [2] * m, size, spans)
        prow = [[str(k), esc(p["company"]), esc(p["name"]), p["premium"],
                 esc("종신" if p["expiry"] == "종신" else p["expiry"])] for k, p in shown]
        right = list_table(["번호", "보험사", "상품명", "월보험료", "만기"], prow, wfit([8, 18, 40, 20, 12], W - gap - wl),
                           [1, 0, 0, 2, 1], 7)
        t = Table([[left, "", right]], colWidths=[wl, gap, W - gap - wl], hAlign="LEFT")
        t.setStyle(TableStyle([("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                               ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
                               ("VALIGN", (0, 0), (-1, -1), "TOP")]))
        return [t]
    cards = [(f"분석 항목({scope})", total, "개", f"적정 {ok}개 · 부족 {low}개 · 미보장 {none}개"),
             ("준비된 상품", str(m), "건", " · ".join(short_product(p["name"]) or p["name"] for _, p in shown) or "없음")]
    return table_page(src, title, f"{scope} {total}개 항목 중 적정 {ok}개, 부족 {low}개, 미보장 {none}개",
                      "필요 금액과 준비 금액을 항목별로 비교하고, 상품별 준비 금액을 함께 보여 줘요. (단위: 만원)",
                      cards, body, emblem=False)


def story_body(d, src):
    body = d["body"]
    if all(lab in body for lab in BODY_BASE):                # 원본 모양 그대로 (내장 그림)
        try:
            hdr = page_header("신체부위별 보장현황", src)
            avail_h = FH - natural_height(hdr, CW) - 4 * mm           # 16:9 쪽 높이에 맞춰 그림 크기를 정한다
            bm = BodyMap(body, min(CW, avail_h * BODY_PIC_W / BODY_PIC_H))
            bm.hAlign = "CENTER"
            return hdr + [bm]
        except Exception as ex:                              # 그림을 읽지 못하면 표(표 쪽 공통 양식)로 대체
            print(f"[주의] 내장 그림을 불러오지 못해 표로 대체합니다: {ex}")
    cnt = {"충분": 0, "부족": 0, "미보장": 0}
    for _, s_ in body.values():
        cnt[s_] += 1

    def body_fn(W):
        rows, spans = grouped_rows(BODY_GROUPS, lambda i, l: [esc(body[l][0]), status_cell(body[l][1])])
        return [list_table(["구분", "항목", "금액", "상태"], rows, wfit([30, 62, 42, 30], W), [0, 0, 2, 1], 8.5, spans)]
    cards = [(lab, str(cnt[lab]), "개", "") for lab in ("충분", "부족", "미보장")]
    return table_page(src, "신체부위별 보장현황", f"{len(body)}개 항목 중 충분 {cnt['충분']}개, 부족 {cnt['부족']}개, 미보장 {cnt['미보장']}개",
                      "신체 부위별 준비 보장 금액 (단위: 만원)", cards, body_fn, emblem=True)


def age_groups(rows):
    groups = []
    for age, vals in rows:
        if groups and groups[-1][1] == vals:
            groups[-1][0].append(age)
        else:
            groups.append(([age], vals))
    return groups


def story_ages(title, src, rows, labels, groups):
    ag = age_groups(rows)
    g = len(ag)
    emblem = (2 + g) <= TP_EMBLEM_MAX_COLS                    # 열이 적으면 본문 2/3 + 스퀘어 엠블럼, 많으면 전체 폭
    head = ["구분", "항목"] + [esc(a[0]) if len(a) == 1 else f"{esc(a[0])}~<br/>{esc(a[-1])}" for a, _ in ag]

    def body(W):
        pw = max(min((220 - 52) / g, 28), 8)
        table_rows, spans = grouped_rows(groups, lambda i, l: [esc(v[i]) for _, v in ag])
        return [list_table(head, table_rows, wfit([20, 32] + [pw] * g, W), [0, 0] + [2] * g, spans=spans)]
    first, last = rows[0][0], rows[-1][0]
    cards = [("조회 연령", f"{first} ~ {last}", "", f"{len(rows)}개 연령 조회"),
             ("보장 금액 구간", str(g), "개", " / ".join(f"{a[0]}" if len(a) == 1 else f"{a[0]}~{a[-1]}" for a, _ in ag))]
    ttl = "연령이 바뀌어도 보장 금액 동일" if g == 1 else f"연령에 따라 보장 금액 {g}개 구간으로 변화"
    return table_page(src, title, ttl, "연령별 보장 금액 변화 (단위: 만원)", cards, body, emblem=emblem)


def _expected_table_numbers(e):
    """표 쪽 검사용: 결과 쪽에 그대로 나와야 하는 원본 값(숫자가 들어간 문자열)."""
    k, d = e["kind"], e["data"]
    out = []
    if k == "generation":
        for m in d["members"]:
            out += m["a"] + m["b"]
    elif k == "products":
        dd = d["d"]
        out += dd["need"] + dd["prep"] + dd["short"]
        for p in dd["products"]:
            if any(v != "-" for v in p["vals"]):
                out += p["vals"]
    elif k == "ages":
        for _, vals in age_groups(d["rows"]):
            out += vals
    return [v for v in out if re.search(r"\d", v)]


def verify_table_values(pdf_path, entries):
    """표 쪽 검사: 원본에서 읽은 모든 값이 결과 쪽에 같은 횟수 이상 그대로 나오는지 확인한다. 하나라도 없으면 오류로 멈춘다."""
    from collections import Counter
    targets = [e for e in entries if e["kind"] in ("generation", "products", "ages") and e["mode"] == "전용"]
    if not targets:
        return
    with pdfplumber.open(str(pdf_path)) as pdf:
        for e in targets:
            want = Counter(_expected_table_numbers(e))
            have = Counter((_opage(pdf, e).extract_text() or "").split())
            miss = {k: v - have.get(k, 0) for k, v in want.items() if have.get(k, 0) < v}
            if miss:
                raise RuntimeError(f"원본 p.{e['n']} {e['title']} 표 검사 실패: 빠진 값 {miss}")
            print(f"[검사] 원본 p.{e['n']} {e['title']} 표 숫자 {sum(want.values())}개 대조 일치")


# ----------------------------------------------------------------------------
# 6. PDF 조립
# ----------------------------------------------------------------------------
FOOTER_TEXT_SHOW = False                       # 1.45: 쪽 아래 안내 문구를 쓰지 않는다(선·쪽 번호는 유지)


def draw_footer(canvas, doc):
    pw, ph = canvas._pagesize
    mx, ly = (W_MARGIN_X, 12 * mm) if pw > ph else (MARGIN_X, 14 * mm)
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor("#D1D5DB"))
    canvas.line(mx, ly, pw - mx, ly)
    canvas.setFont(FONT_B if BOLD_ALL else FONT, 7.5)
    canvas.setFillColor(GRAY)
    if FOOTER_TEXT_SHOW:
        canvas.drawString(mx, ly - 4 * mm, doc.footer_left)
    canvas.drawRightString(pw - mx, ly - 4 * mm, f"{canvas.getPageNumber()} / {doc.total_pages}")
    canvas.restoreState()
    pn = canvas.getPageNumber()
    if TALL_SHOW_ON_PAGES and pn not in getattr(doc, "tall_skip_pages", ()):
        draw_tall(canvas)                                      # 모든 쪽 오른쪽에 tall (표지는 표지가 직접 그리므로 건너뜀)


def story_original_page(e):
    """원본 쪽을 그림으로 떠서 비율 그대로 16:9 쪽 본문에 맞춰 넣는다. 실패하면 None."""
    try:
        from PIL import Image as PILImage, ImageChops
        pil = e["page"].to_image(resolution=250).original.convert("RGB")
        diff = ImageChops.difference(pil, PILImage.new("RGB", pil.size, (255, 255, 255)))
        box = diff.point(lambda v: 255 if v > 12 else 0).getbbox()       # 흰 여백을 뺀 실제 내용 범위
        if box:
            pad = int(max(pil.size) * 0.01)
            box = (max(box[0] - pad, 0), max(box[1] - pad, 0), min(box[2] + pad, pil.size[0]), min(box[3] + pad, pil.size[1]))
            pil = pil.crop(box)
        buf = io.BytesIO()
        pil.save(buf, "PNG")
        w, h = pil.size
        k = min(COVER_W / w, (COVER_H - 2) / h)
        img = Image(io.BytesIO(buf.getvalue()), width=w * k, height=h * k)
        img.hAlign = "CENTER"
        e["orig_img"] = True
        return [img]
    except Exception as ex:
        print(f"[주의] 원본 1쪽을 그림으로 만들지 못해 요약 표지로 대체합니다: {ex}")
        return None


def make_story(e, ctx):
    k, n, d = e["kind"], e["n"], e["data"]
    if n == 1:                                                  # 첫 쪽은 내장 이미지로 직접 구성
        if k == "cover" and e["mode"] == "전용" and d and d.get("name"):
            e["cover_full"] = True                               # 쪽 전체를 쓰는 표지(cover_full 양식)라는 표시
            return [CoverPage(d, ctx["basis"], WIDE_W - 1, WIDE_H - 1)]
        st = story_original_page(e)                             # 표지를 못 읽었으면 원본 1쪽을 그림으로
        if st:
            return st
    if e["mode"] != "전용":
        return story_generic(e)
    if k == "cover":
        return story_cover(d, ctx["basis"], ctx["entries"])
    if k == "enrollment":
        return story_enrollment(d, n, ctx["name"])
    if k == "generation":
        return story_generation(d, n)
    if k == "products":
        return story_products(d["d"], n, e["title"], d["labels"], d["groups"])
    if k == "body":
        return story_body(d, n)
    if k == "ages":
        return story_ages(e["title"], n, d["rows"], d["labels"], d["groups"])
    return story_generic(e)


def natural_height(flowables, width=None):
    h = 0
    for f in flowables:
        h += f.wrap(width or CW, 10 ** 6)[1] + f.getSpaceBefore() + f.getSpaceAfter()
    return h


def is_wide(e):
    """모든 쪽(전용·범용)을 16:9 가로 쪽으로 만든다."""
    return True                                   # 결과물은 항상 16:9


def verify_16x9(pdf_path, tol=0.004):
    """완성한 PDF 의 모든 쪽이 16:9 인지 검사한다. 하나라도 다르면 오류를 낸다. (추가 설치 없이 pdfplumber 사용)"""
    bad = []
    with pdfplumber.open(str(pdf_path)) as pdf:
        for i, pg in enumerate(pdf.pages, 1):
            w, h = float(pg.width), float(pg.height)
            if abs(w / h - 16 / 9) > 16 / 9 * tol:
                bad.append(f"p.{i}({w:.0f}x{h:.0f})")
    if bad:
        raise RuntimeError("16:9 가 아닌 쪽이 있습니다: " + ", ".join(bad))
    print("[검사] 모든 쪽 16:9 확인")


def pair_body_words(pg):
    """완성한 PDF 의 신체부위별 보장현황 쪽에서 항목명 ↔ 금액을 위치로 다시 짝짓는다. -> ({항목: 금액}, 오류 목록)"""
    words = pg.extract_words()
    nums = [w for w in words if re.fullmatch(r"[\d,]+", w["text"])]
    mid = float(pg.width) / 2
    res, used, errs = {}, {}, []
    for lab in BODY_BASE:
        lws = [w for w in words if w["text"] in (lab, BODY_ALT.get(lab, lab))]
        if not lws:
            errs.append(f"{lab}: 항목명을 찾지 못함")
            continue
        lw = lws[0]
        left = lw["x0"] < mid
        cands = [n for n in nums if abs(n["top"] - lw["top"]) < 3 and n["x0"] > lw["x1"] and (n["x0"] < mid) == left]
        if not cands:
            errs.append(f"{lab}: 금액을 찾지 못함")
            continue
        n = min(cands, key=lambda w: w["x0"] - lw["x1"])
        key = (round(n["x0"], 1), round(n["top"], 1))
        if key in used:
            errs.append(f"{lab}: 금액이 '{used[key]}'와 겹침")
        used[key] = lab
        res[lab] = n["text"]
    return res, errs


def _status_in_text(want, text):
    """want(공백 없이 비교)가 text 에 있는가. 납입 상태 칸이 두 줄로 접히면 이웃 칸의 글이 줄 사이에 끼어 들어
    한 덩어리로는 찾지 못하므로, 한 덩어리로 없으면 '앞말'과 '숫자·완납' 조각이 각각 있는지로 대조한다. (1.24)
    숫자 조각(120/120회완납 등)은 반드시 한 덩어리로 있어야 한다."""
    flat = re.sub(r"\s+", "", want)
    if flat in text:
        return True
    m = re.search(r"(\d[\d,]*/\d[\d,]*회\s*완납)", want)
    if not m:
        return False
    head = re.sub(r"\s+", "", want[:m.start()])
    return re.sub(r"\s+", "", m.group(1)) in text and (not head or head in text)


def verify_enrollment_values(pdf_path, entries):
    """보험 가입 현황 쪽 검사: ① 쪽에 나와야 할 숫자(건수·월보험료·기납입·납입 상태)가 모두 있는가
    ② 결과 쪽의 모든 큰 숫자(쉼표 포함 또는 3자리 이상)가 원본 쪽에도 있는가 ③ 삭제한 계약이 목록에 남지 않았는가."""
    targets = [e for e in entries if e["kind"] == "enrollment" and e["mode"] == "전용"]
    if not targets:
        return
    num = re.compile(r"\d[\d,.]*\d|\d")
    with pdfplumber.open(str(pdf_path)) as pdf:
        for e in targets:
            m = enrollment_model(e["data"])
            text = re.sub(r"\s+", "", _opage(pdf, e).extract_text() or "")
            need = [f"{m['n']}건", f"{m['monthly']}원", f"{m['paid_total']}원"] + [it["status"] for it in m["items"]]
            miss = [t for t in need if not _status_in_text(t, text)]
            src_nums = {x.strip(".,") for x in num.findall(e["page"].extract_text() or "")}
            out_nums = {x.strip(".,") for x in num.findall(_opage(pdf, e).extract_text() or "")}
            extra = sorted(x for x in out_nums - src_nums if ("," in x or len(x) >= 3) and x != "127")
            gone = [short_product(c["name"]) for c in m["excluded"]
                    if short_product(c["name"]) and re.sub(r"\s+", "", short_product(c["name"])) in text]
            errs = ([f"빠진 값: {miss}"] if miss else []) + ([f"원본에 없는 숫자: {extra}"] if extra else []) \
                + ([f"삭제 대상이 남음: {gone}"] if gone else [])
            if errs:
                raise RuntimeError(f"원본 p.{e['n']} 보험 가입 현황 검사 실패: " + " / ".join(errs))
            print(f"[검사] 원본 p.{e['n']} 보험 가입 현황 숫자 {len(need)}개 대조 일치, 제외한 계약 {len(m['excluded'])}건")


def verify_body_values(pdf_path, entries):
    """수치 개별 적용 검사: 결과 PDF 의 신체부위별 보장현황에서 항목별 금액을 다시 읽어 원본 값과 하나씩 대조한다."""
    targets = [e for e in entries if e["kind"] == "body" and e["mode"] == "전용"
               and all(lab in e["data"]["body"] for lab in BODY_BASE)]
    if not targets:
        return
    with pdfplumber.open(str(pdf_path)) as pdf:
        for e in targets:
            res, errs = pair_body_words(_opage(pdf, e))
            for lab, (val, _) in e["data"]["body"].items():
                if lab in res and res[lab] != val:
                    errs.append(f"{lab}: 원본 {val} ≠ 결과 {res[lab]}")
            if errs:
                raise RuntimeError(f"원본 p.{e['n']} 신체부위별 보장현황 수치 불일치: " + " / ".join(errs))
            print(f"[검사] 원본 p.{e['n']} 신체부위별 보장현황 {len(res)}개 항목 금액을 하나씩 대조 — 모두 일치")


HISTORY_MD = "내장이미지_설명서.md"


def check_history_md():
    """수정 규칙: 현재 버전의 대화·수정 이력이 md 에 있는지 확인하고, 없으면 알린다."""
    md = _app_dir() / HISTORY_MD
    if not md.exists():                    # md 가 없는 폴더(배포·다른 컴퓨터)에서는 개발용 안내를 생략한다
        return
    try:
        ok = f"v{APP_VERSION}" in md.read_text(encoding="utf-8")
    except Exception:
        ok = False
    if not ok:
        print(f"[주의] {HISTORY_MD} 에 v{APP_VERSION} 대화·수정 이력이 없습니다. 이 파일을 고쳤다면 이력을 추가하세요.")


ANALYSIS_REPLACES = ("products", "ages", "generation")      # 분석 쪽이 대신하는 요약 쪽 종류 (항목별 표 = 상품별 분석, 연령 표 = 연령별 분석, 구성원별 준비 금액 = 세대 분석)


def _generation_covered(g_entry, entries):
    """세대 분석 쪽의 값이 모두 상품별 분석의 '준비' 값과 같고 구성원이 1명이면 True (이때만 분석 쪽이 대신할 수 있다)."""
    members = g_entry["data"]["members"]
    if len(members) != 1:
        return False
    prep = {}
    for e in entries:
        if e["kind"] == "products" and e["mode"] == "전용":
            for lab, v in zip(e["data"]["labels"], e["data"]["d"]["prep"]):
                prep[lab] = v
    m = members[0]
    return all(prep.get(lab) == v for lab, v in list(zip(LABELS_A, m["a"])) + list(zip(LABELS_B, m["b"])))


def replaced_by_analysis(entries, ana_slides):
    """분석 쪽이 내용을 대신하는 원본 쪽 번호 집합. 분석 쪽이 실제로 만들어진 경우에만 대체한다.
    상품별 분석 = 분석 슬라이드가 있으면 대체, 연령별 분석 = '연령별 보장 변화' 슬라이드가 있을 때만 대체(없으면 요약 쪽을 남겨 내용을 잃지 않는다)."""
    if not ana_slides:
        return set()
    kinds = {sl["kind"] for sl in ana_slides}
    drop = set()
    for e in entries:
        if e["mode"] != "전용" or e["kind"] not in ANALYSIS_REPLACES:
            continue
        if e["kind"] == "ages" and "ages" not in kinds:
            continue
        if e["kind"] == "generation" and not ("area" in kinds and _generation_covered(e, entries)):
            continue
        drop.add(e["n"])
    return drop


def _opage(pdf, e):
    """결과 PDF 에서 원본 쪽 e 에 해당하는 쪽(대체한 쪽이 빠졌으므로 out_n 으로 찾는다)."""
    return pdf.pages[(e.get("out_n") or e["n"]) - 1]


def draw_analysis_page(canvas, doc):
    """요약 PDF 끝에 붙는 분석 쪽을 그린다(쪽 바탕·글·그림 모두 Deck 으로). 쪽 번호는 요약+분석 전체 기준이다."""
    j = canvas.getPageNumber() - doc.ana_offset - 1
    if 0 <= j < len(doc.ana_slides):
        D_ = Deck(canvas)
        _draw_slide(D_, doc.ana_slides[j], doc.ana_offset + j + 1, doc.total_pages, doc.ana_ctx)
        if D_.over:
            print(f"[주의] 분석 {doc.ana_offset + j + 1}쪽({doc.ana_slides[j].get('label', '')}): 쪽 바닥을 넘는 글 {len(D_.over)}줄 — 내용을 다음 쪽으로 나눠야 합니다: {D_.over[0][:30]}")


def _prepare(entries, ctx):
    """요약·분석 PDF 를 만들기 전에 공통으로 필요한 준비(문단 양식, 고객명, 쪽 목록)."""
    global CUSTOMER_NAME
    build_styles()
    CUSTOMER_NAME = ctx.get("name", "")
    ctx["entries"] = entries


def build_pdf(entries, ctx, out_path, analysis=True, only=None):
    """요약 PDF 를 만든다. (1.25~ convert 는 analysis=False 로 부른다 — 분석은 별도 분석 PDF.)
    analysis=True 이면 분석 슬라이드를 맨 끝에 이어 붙이고 그 쪽 수를 돌려준다.
    only: 함수(e)->bool. 주어지면 요약 쪽은 그 조건에 맞는 원본 쪽만 만든다(분석 PDF 의 맨 앞 1·2쪽용). 분석에는 모든 원본 쪽 데이터를 쓴다."""
    _prepare(entries, ctx)
    ana_slides = []
    if analysis:                                      # 분석 쪽을 못 만들어도 요약 쪽은 정상으로 만든다
        try:
            ana_slides = analysis_slides(entries, ctx)
            if not ana_slides:
                print("[분석] 분석할 상품별 분석 데이터가 없어 분석 쪽을 넣지 않았습니다.")
        except Exception as ex:
            ana_slides = []
            print(f"[주의] 분석 쪽을 만들지 못했습니다(요약 쪽은 정상): {ex}")
    all_entries = entries                              # 분석에는 모든 원본 쪽 데이터를 쓰고, 요약 쪽은 대체한 쪽을 뺀다
    drop = replaced_by_analysis(all_entries, ana_slides)
    entries = [e for e in all_entries if e["n"] not in drop and (only is None or only(e))]
    for e in all_entries:
        e["out_n"] = None
    for k_, e in enumerate(entries, 1):
        e["out_n"] = k_                                # 결과 PDF 안의 쪽 번호(검사용)
    for e in all_entries:
        if e["n"] in drop and only is None:
            print(f"[대체] 원본 p.{e['n']} {e['title']} → 요약 쪽을 만들지 않고 분석 쪽으로 대체")
    cv = ctx["cover"]
    stories = [make_story(e, ctx) for e in entries]
    wides = [True for _ in entries]                   # 결과물은 항상 16:9 — 모든 쪽이 가로 쪽 양식
    for e, st, wd in zip(entries, stories, wides):
        h = natural_height(st, WCW if wd else CW)
        fh = WFH if wd else FH
        if h > fh * 1.5:
            print(f"[주의] 원본 p.{e['n']}: 내용이 많아 약 {int(fh / h * 100)}% 크기로 축소됩니다.")
    name = ctx["name"]
    doc = BaseDocTemplate(str(out_path), pagesize=(WIDE_W, WIDE_H), title=f"{name} 보장분석 " + ("보고서" if only else "요약 보고서"),
                          author=cv.get("fp", ""), leftMargin=MARGIN_X, rightMargin=MARGIN_X)
    doc.total_pages = len(entries) + len(ana_slides)
    doc.ana_slides, doc.ana_offset, doc.ana_ctx = ana_slides, len(entries), ctx
    doc.tall_skip_pages = {1} if entries[0].get("cover_full") else set()      # 표지(cover_full)는 tall 을 직접 그린다
    doc.footer_left = (f"{name} 고객님 보장분석 요약 · {ctx['basis'] or cv.get('print_date', '')} 기준 · "
                       "보험금 지급 근거 아님, 약관·증권 우선")
    main_t = PageTemplate(id="main", pagesize=(WIDE_W, WIDE_H), onPage=draw_footer,
                          frames=[Frame(MARGIN_X, FRAME_BOTTOM, CW, FH, leftPadding=0, rightPadding=0,
                                        topPadding=0, bottomPadding=0)])
    wide_t = PageTemplate(id="wide", pagesize=(WIDE_W, WIDE_H), onPage=draw_footer,
                          frames=[Frame(W_MARGIN_X, W_BOTTOM, WCW, WFH, leftPadding=0, rightPadding=0,
                                        topPadding=0, bottomPadding=0)])
    cover_t = PageTemplate(id="cover", pagesize=(WIDE_W, WIDE_H), onPage=draw_footer,
                           frames=[Frame(COVER_X, COVER_Y, COVER_W, COVER_H, leftPadding=0, rightPadding=0,
                                         topPadding=0, bottomPadding=0)])
    full_t = PageTemplate(id="cover_full", pagesize=(WIDE_W, WIDE_H),            # 첫 쪽 전체를 쓰는 표지(여백·꼬리말 없음)
                          frames=[Frame(0.5, 0.5, WIDE_W - 1, WIDE_H - 1, leftPadding=0, rightPadding=0,
                                        topPadding=0, bottomPadding=0)])
    if entries[0].get("cover_full"):
        doc.addPageTemplates([full_t, wide_t, main_t])                   # 첫 쪽은 쪽 전체를 채우는 표지
    elif entries[0].get("orig_img"):
        doc.addPageTemplates([cover_t, wide_t, main_t])                  # 첫 쪽은 원본 그림 전용 큰 영역
    else:
        doc.addPageTemplates([wide_t, main_t] if wides and wides[0] else [main_t, wide_t])   # 첫 쪽 양식이 먼저
    if ana_slides:                                                       # 분석 쪽 양식: 쪽 전체를 Deck 으로 그리므로 꼬리말·tall 은 쓰지 않는다
        doc.addPageTemplates([PageTemplate(id="analysis", pagesize=(WIDE_W, WIDE_H), onPage=draw_analysis_page,
                                           frames=[Frame(0, 0, 10, 10, leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)])])
    story = []
    for i, st in enumerate(stories):
        cw, fh = (WCW, WFH) if wides[i] else (CW, FH)
        if i == 0 and entries[0].get("cover_full"):
            story.extend(st)                                                     # 표지는 쪽 전체에 그대로 (축소 없음)
        elif i == 0 and entries[0].get("orig_img"):
            story.append(KeepInFrame(COVER_W, COVER_H, st, mode="shrink"))       # 원본 그림은 큰 영역에 그대로
        elif i == 0:
            brand = brand_header(cw)                       # 첫 쪽에는 항상 로고·펭귄을 넣고, 이 부분은 축소하지 않는다
            brand_h = natural_height(brand, cw) if brand else 0
            story.extend(brand)
            story.append(KeepInFrame(cw, fh - brand_h - 2, st, mode="shrink"))   # 이미지 아래 내용만 축소
        else:
            story.append(KeepInFrame(cw, fh, st, mode="shrink"))                 # 넘치면 축소해서 한 쪽에 맞춤
        if i < len(stories) - 1:
            story.append(NextPageTemplate("wide" if wides[i + 1] else "main"))
            story.append(PageBreak())
    if ana_slides:                                                       # 요약 쪽 뒤에 분석 쪽을 이어 붙인다
        story.append(NextPageTemplate("analysis"))
        story.append(PageBreak())
        for j in range(len(ana_slides)):
            story.append(Spacer(1, 1))
            if j < len(ana_slides) - 1:
                story.append(PageBreak())
    doc.build(story)
    verify_16x9(out_path)
    verify_body_values(out_path, entries)
    verify_enrollment_values(out_path, entries)
    verify_table_values(out_path, entries)
    if ana_slides:
        verify_analysis(out_path, ana_slides, offset=len(entries))
    return len(ana_slides), len(drop)


def _front_pages(e):
    """분석 PDF 맨 앞에 수정 전 그대로 넣는 쪽: 원본 1쪽(표지)과 보험 가입 현황(계약 및 납입현황)."""
    return e["n"] == 1 and e["kind"] != "prodcov"


TOC_STANDARD = ("표지", "Pride of KYOBO", "유의사항", "보험 가입 현황", "세대 보장요약", "종합요약", "세대 분석", "상품별 분석",
                "신체부위별 보장현황", "보장밸런스(그래프)", "연령별 분석", "보장항목별 분석", "타사 상품별 가입 현황", "보장 제안",
                "보장 제안 전/후 비교", "상품별 분석 전/후 비교", "연령별 분석 전/후 비교", "신체부위별 보장현황 전/후 비교",
                "보장밸런스(그래프) 전/후 비교", "컨설팅 종합의견")   # 1.53: 기준 목차 1~20번 (앞으로 고르는 모든 문서는 이 안에 있다)
TOC_ALIAS = {"가입상품 보장내역": "타사 상품별 가입 현황", "아무것도 하지 않으면 아무일도 일어나지 않는다.": "Pride of KYOBO", "보장밸런스": "보장밸런스(그래프)",
             "보장밸런스 전/후 비교": "보장밸런스(그래프) 전/후 비교", "보장밸런스 전/후비교": "보장밸런스(그래프) 전/후 비교",
             "전/후 비교": "보장 제안", "세대 보장 제안 전/후 비교": "보장 제안 전/후 비교",
             "신체부위별 보장현황 전/후비교": "신체부위별 보장현황 전/후 비교"}
_TOC_PERSON = re.compile(r"^[^\s]{1,8}\s?(?:고객님|님)(?:의|을 위한|을 위해|께)\s*")


def toc_name(title):
    """1.51: 쪽 이름에서 `(1/6)` · `1/6` 같은 쪽 순서 표시와 뒤따르는 부제를 떼고 목차 이름만 돌려준다.
    예) `상품별 분석 (4/6) 항암·수술` → `상품별 분석`, `보장 제안 전/후 비교 3/6` → `보장 제안 전/후 비교`."""
    t = re.sub(r"\s*\(\s*\d+\s*/\s*\d+\s*\).*$", "", title or "")
    t = re.sub(r"\s+\d+\s*/\s*\d+\s*$", "", t)
    t = _TOC_PERSON.sub("", t.strip())                         # 1.52: `우성래님의 `, `우성래 고객님을 위한 ` 같은 고객 이름 앞말은 사람마다 달라서 뗀다
    t = t.strip() or (title or "").strip()
    return TOC_ALIAS.get(t, t)


def toc_lines(entries):
    """1.51: 이름이 같은 쪽(1/6, 2/6 …)은 한 줄로 합친 목차. 이어진 쪽만 합치고 쪽 번호는 `p.6~7`(연속) 또는 `p.6, 9`(떨어진 쪽)로 쓴다.
    쪽 수는 사람마다 달라지므로 같은 이름은 중복 없이 한 번만 나온다. 반환: [(쪽 표기, 이름, 방식, 메모)]"""
    groups = []
    for e in entries:
        name = toc_name(e["title"])
        if groups and groups[-1]["name"] == name and e["n"] == groups[-1]["pages"][-1] + 1:
            g = groups[-1]
        else:
            g = dict(name=name, pages=[], modes=[], notes=[])
            groups.append(g)
        g["pages"].append(e["n"])
        if e["mode"] not in g["modes"]:
            g["modes"].append(e["mode"])
        if e.get("note") and e["note"] not in g["notes"]:
            g["notes"].append(e["note"])
    out = []
    for g in groups:
        p = g["pages"]
        label = f"p.{p[0]}" if len(p) == 1 else f"p.{p[0]}~{p[-1]}"
        out.append((label, g["name"], "/".join(g["modes"]), " / ".join(g["notes"])))
    return out


def toc_extra(entries):
    """1.52: 기준 목차(TOC_STANDARD 14항목)에 없는 항목의 (목차 이름, 쪽 표기) 목록."""
    return [(name, label) for label, name, _m, _n in toc_lines(entries) if name not in TOC_STANDARD]


def toc_no(name):
    """1.53: 기준 목차 번호(1~20). 기준에 없으면 None."""
    return TOC_STANDARD.index(name) + 1 if name in TOC_STANDARD else None


def convert(src, out):
    """PDF 한 개를 분석 PDF(주 결과)와 요약 PDF 로 변환한다. out = 분석 PDF 경로. 진행 내용은 print 로 알린다.
    -> dict(main=주 결과 경로, analysis=분석 PDF 경로 또는 None, summary=요약 PDF 경로 또는 None, n_ana, n_sum, n_src)"""
    register_fonts()
    print(f"[버전] {APP_VERSION}  (출력: 16:9, 분석 PDF 우선)")
    check_history_md()
    ap, sp = analysis_path(out), summary_path(out)
    res = dict(main=None, analysis=None, summary=None, report=None, n_ana=0, n_sum=None, n_src=0)
    with pdfplumber.open(str(src)) as pdf:
        n_src = len(pdf.pages)
        res["n_src"] = n_src
        entries, ctx = analyze_pdf(pdf)
        print(f"[원본] {n_src}쪽 — 쪽별 처리")
        for label, name, mode, note in toc_lines(entries):      # 1.51: 이름이 같은 쪽은 한 줄, 1.53: 기준 목차 번호(1~20)
            no = toc_no(name)
            print(f"  {(str(no) + '.') if no else '기준 외':>5} {name}  (원본 {label})  [{mode}]" + (f"  ※ {note}" if note else ""))
        extra = toc_extra(entries)
        if extra:
            print(f"[목차] 기준 {len(TOC_STANDARD)}항목에 없는 항목: " + ", ".join(f"{n}(원본 {lb})" for n, lb in extra))
        _prepare(entries, ctx)
        # 1) 분석 PDF — 제일 우선. 만들지 못하면 오류로 멈춘다.
        # 맨 앞 1·2쪽(표지, 계약 및 납입현황)은 수정 전과 똑같은 요약 쪽, 그 뒤에 분석 쪽
        if any(_front_pages(e) for e in entries):
            n_ana, _ = build_pdf(entries, ctx, ap, analysis=True, only=_front_pages)
        else:                                                      # 1.72: 맨 앞 표지 쪽이 없는 문서(가입상품 보장내역만) — 분석 쪽만으로 PDF 를 만든다
            _sl = build_analysis_pdf(entries, ctx, ap)
            n_ana = len(_sl) if _sl else 0
        if n_ana:
            with pdfplumber.open(str(ap)) as pa:
                n_all = len(pa.pages)
            res["analysis"], res["main"], res["n_ana"] = ap, ap, n_ana
            print(f"[완료] 분석 PDF(우선)  {ap}  (앞 {n_all - n_ana}쪽 + 분석 {n_ana}쪽 = 전체 {n_all}쪽)")
        else:                                              # 분석할 데이터가 없으면 분석 PDF 는 만들지 않는다
            try:
                ap.unlink()
            except OSError:
                pass
            print("[분석] 분석 PDF 를 만들지 못했습니다(분석할 데이터 없음). 요약 PDF 가 주 결과물입니다.")
        # 1-2) 요약 리포트 PDF(1.64) — 분석 PDF 의 숫자를 6하 원칙 서술형·구어체 500자로 정리한 1쪽. 실패해도 분석 PDF 는 그대로 둔다.
        if MAKE_REPORT_PDF and res["analysis"] and ctx.get("name"):          # 1.72: 고객 이름이 없는 문서(가입상품 보장내역만)는 요약 리포트를 만들지 않는다
            try:
                rp, nchar = make_report_pdf(ap, report_path(out))
                res["report"] = rp
                print(f"[완료] 요약 리포트  {rp}  ({nchar}자)" + ("" if nchar == REPORT_CHARS else f"  ※ {REPORT_CHARS}자에 맞추지 못했습니다"))
            except Exception as ex:
                print(f"[주의] 요약 리포트를 만들지 못했습니다(분석 PDF 는 정상): {ex}")
        # 2) 요약 PDF — 분석 쪽 없이 원본과 1:1. 실패해도 분석 PDF 는 그대로 둔다. (1.63: 기본은 만들지 않음)
        if not MAKE_SUMMARY_PDF and res["analysis"]:
            print("[안내] 요약 PDF 는 만들지 않습니다(분석 PDF 만 저장).")
        else:
          try:
              build_pdf(entries, ctx, sp, analysis=False)
              with pdfplumber.open(str(sp)) as po:
                  res["n_sum"] = len(po.pages)
              res["summary"] = sp
              if not res["main"]:
                  res["main"] = sp
              print(f"[완료] 요약 PDF  {sp}  (요약 {res['n_sum']}쪽 / 원본 {n_src}쪽)")
              if res["n_sum"] != n_src:
                  print("[경고] 요약 쪽수가 원본과 다릅니다. 내용이 한 쪽을 넘쳤는지 확인하세요.")
          except Exception as ex:
              if not res["analysis"]:
                  raise                                     # 분석 PDF 도 없으면 결과가 없으므로 오류로 알린다
              print(f"[주의] 요약 PDF 를 만들지 못했습니다(분석 PDF 는 정상): {ex}")
    return res


# ----------------------------------------------------------------------------
# 6-B. 분석 PDF — 원본 3~8쪽(세대·상품별·신체부위·연령별)의 숫자를 분석·정리해 16:9 슬라이드 9장으로 만든다.
#   항상 별도 파일 '<이름>_분석.pdf' 로 만들고 이것이 주 결과물이다(1.25~). 요약 PDF(<이름>_요약.pdf)는 분석 쪽 없이 원본과 1:1 로 함께 저장한다.
#   기법: ① 항목 36개를 필요·준비·부족으로 읽어 적정/부족/미보장으로 분류 → ② 영역별 개수·준비율·순위를 계산
#         → ③ 슬라이드마다 '한 문장 결론(큰 제목) + 근거 설명 + 카드/표/그림'으로 정리 → ④ 원본 값은 문자열 그대로 인용하고
#         계산한 값(비율·합계·순위)은 고정한 식으로만 만든다 → ⑤ 인용한 원본 값이 결과 PDF 에 있는지 다시 대조한다.
#   자세한 규칙은 md 「3-6」, 고정값은 md 5장·AN_* 상수.
# ----------------------------------------------------------------------------
AN_NAME = "분석 PDF"
AN_BG = "#FFFFFF"                # 슬라이드 바탕
AN_LABEL = "#374151"             # 작은 제목(남색)
AN_INK = "#111827"               # 큰 제목·본문 글자
AN_SUB = "#4B5563"               # 한 줄 설명 글자
AN_GRAY = "#6B7280"              # 보조 글자
AN_CARD = "#FFFFFF"              # 카드 바탕
AN_CARD_LINE = "#D5DAE2"         # 카드 테두리
AN_BOX = "#F3F5F9"               # 인사이트 상자 바탕
AN_C_OK, AN_C_LOW, AN_C_NONE = "#1B8A80", "#E28E3A", "#C54648"      # 막대 색: 적정 / 부족 / 미보장
AN_T_OK, AN_T_LOW, AN_T_NONE = "#1B8A80", "#C97614", "#C54648"      # 글자 색: 적정 / 부족 / 미보장
AN_C_NEED, AN_C_PREP = "#17306B", "#1B8A80"                          # 막대 색: 필요 / 준비
AN_TOP_N = 5                     # 핵심 진단비 슬라이드에 올리는 항목 수 (부족 금액 큰 순)
AN_AREA_ROWS = 8                  # 영역별 슬라이드 오른쪽 표에 올리는 부족 항목 수 (준비율 낮은 순)
AN_RED_BELOW = 30                # 준비율(%)이 이 값 미만이면 빨간 글자, 이상이면 갈색 글자
AN_DROP_BIG = 50                 # 연령에 따라 줄어든 비율(%)이 이 값 이상이면 '크게/급감'
AN_DISP = {"LTC": "LTC (장기요양)", "CI": "CI (중대질병)", "GI": "GI (일반중대질병)"}    # 그림 라벨용 이름
AN_CARE = ("LTC", "중증치매", "중등도치매", "경도치매")                                    # 간병 관련 항목
AN_TOPIC = {"진단": "진단비", "사망": "사망 보장", "항암": "항암 치료비", "입원": "입원비", "통원": "통원비",
            "수술": "수술비", "실손": "실손의료비"}                                       # 영역 이름 → 문장용 이름


def _num(s):
    s = (s or "").replace(",", "").strip()
    return float(s) if re.fullmatch(r"\d+(\.\d+)?", s) else None


def _rhu(x):                      # 반올림: 0.5 는 올림 (고정)
    return int(x + 0.5)


def _disp_group(g):               # 영역 이름 정리: '진단(재해골절)'→'진단', '의료비 실손'→'실손'
    return "실손" if "실손" in g else g.split("(")[0]


def _josa(word, with_final, no_final):
    ch = word[-1]
    if "가" <= ch <= "힣":
        return with_final if (ord(ch) - 0xAC00) % 28 else no_final
    return no_final


def _fmt_k(v):
    if v >= 1000:
        return f"{float(f'{v / 1000:.3g}'):g}k"
    return f"{int(v)}"


def _nice_max(v):
    import math
    e = 10 ** math.floor(math.log10(v))
    for m_ in (1, 1.5, 2, 2.5, 3, 3.5, 4, 5, 6, 8, 10):
        if m_ * e >= v:
            return m_ * e
    return v


def analysis_data(entries, ctx):
    """원본에서 읽은 값을 분석용으로 모은다. 항목(items)·연령(ages)·계약 정보."""
    items, head = [], None
    for e in entries:
        if e["kind"] == "products" and e["mode"] == "전용":
            d = e["data"]["d"]
            gmap = {lab: g for g, labs in e["data"]["groups"] for lab in labs}
            if d.get("head"):
                head = d["head"]
            for i, lab in enumerate(e["data"]["labels"]):
                st = status_of(d["prep"][i], d["short"][i])
                items.append(dict(group=gmap.get(lab, ""), g=_disp_group(gmap.get(lab, "")), label=lab, need=d["need"][i],
                                  prep=d["prep"][i], short=d["short"][i], status=st,
                                  nn=_num(d["need"][i]), np=_num(d["prep"][i]) or 0.0, ns=_num(d["short"][i]) or 0.0))
    ages, age_order = {}, []
    for e in entries:
        if e["kind"] == "ages" and e["mode"] == "전용":
            for age, vals in e["data"]["rows"]:
                if age not in age_order:
                    age_order.append(age)
            for j, lab in enumerate(e["data"]["labels"]):
                ages[lab] = {age: vals[j] for age, vals in e["data"]["rows"]}
    paid_whole_life = any(c.get("expiry") == "종신" and str(c.get("count", "")).endswith("(0)") and c.get("premium") not in ("0", "")
                          for c in ctx.get("contracts", []))
    foot50 = any("50%가 감액" in (e.get("text") or "") for e in entries)
    return dict(items=items, head=head, ages=ages, age_order=age_order, paid_whole_life=paid_whole_life, foot50=foot50)


def analysis_slides(entries, ctx):
    """분석 슬라이드 목록(dict)을 만든다. 필요한 데이터가 없으면 그 슬라이드는 건너뛴다. quotes = 원본에서 그대로 인용한 값."""
    A = analysis_data(entries, ctx)
    items = A["items"]
    slides = []
    if not items:                                                 # 1.72: 보장분석 보고서가 아니라 `가입상품 보장내역`만 있는 PDF 는 상품별 가입 현황 쪽만 만든다
        return prodcov_main_slides(entries) + prodcov_slides(entries) + prodcov_detail_slides(entries, True)
    total = len(items)
    cnt = {k: sum(1 for it in items if it["status"] == k) for k in ("적정", "부족", "미보장")}
    ok, low, none = cnt["적정"], cnt["부족"], cnt["미보장"]
    h = A["head"]
    if h and (str(total), str(ok), str(low), str(none)) != (h["total"], h["ok"], h["low"], h["none"]):
        print(f"[주의] 분석: 항목 분류 결과({total}/{ok}/{low}/{none})가 원본 합계({h['total']}/{h['ok']}/{h['low']}/{h['none']})와 다릅니다.")
    order = []
    for it in items:
        if it["g"] not in order:
            order.append(it["g"])

    def by_group(pred):
        return {g: sum(1 for it in items if it["g"] == g and pred(it)) for g in order}
    size = {g: sum(1 for it in items if it["g"] == g) for g in order}
    okg, lowg, nong = by_group(lambda i: i["status"] == "적정"), by_group(lambda i: i["status"] == "부족"), by_group(lambda i: i["status"] == "미보장")
    strong = [g for g in sorted(order, key=lambda g: -okg[g]) if okg[g] * 2 >= size[g] and okg[g] > 0]
    weak_all = sorted([g for g in order if lowg[g] + nong[g] > 0], key=lambda g: -(lowg[g] + nong[g]))
    uncovered = sorted([it for it in items if it["status"] == "미보장"], key=lambda it: -it["nn"])
    name = ctx.get("name", "")
    basis = ctx.get("basis", "")

    # 1 종합 진단
    if total:
        pct = (low + none) / total * 100
        weak3 = weak_all[:3]
        lowtop = sorted([g for g in order if lowg[g] > 0], key=lambda g: -lowg[g])[:2]
        slides.append(dict(kind="summary", label=f"전체 {total}개 항목 종합 진단",
                           headline=f"{total}개 항목 중 적정 {ok}개, 보완 필요 {low + none}개",
                           sub=(f"{', '.join(strong)} 보장은 탄탄, {', '.join(weak3)} 등 {low + none}개 항목 추가 대비 권장"
                                if strong else f"{', '.join(weak3)} 등 {low + none}개 항목 추가 대비 권장"),
                           cards=[("보장 적정", ok, AN_T_OK, AN_C_OK, f"{', '.join(strong) or '-'} 등 현재 충분히 갖춰진 영역"),
                                  ("보장 부족", low, AN_T_LOW, AN_C_LOW, f"{', '.join(lowtop) or '-'} 등 증액 필요"),
                                  ("미보장", none, AN_T_NONE, AN_C_NONE,
                                   (", ".join(it["label"] for it in uncovered[:3]) + " 등 보장 공백 상태인 항목") if uncovered else "해당 없음")],
                           bars=[("적정", ok, AN_C_OK, "#FFFFFF"), ("부족", low, AN_C_LOW, "#111111"), ("미보장", none, AN_C_NONE, "#FFFFFF")],
                           insight=[("전체 ", False), (f"{total}개", True), (" 분석 항목 중 부족(", False), (f"{low}개", True), (")과 미보장(", False),
                                    (f"{none}개", True), (")이 도합 ", False), (f"{pct:.1f}%", True), ("를 차지. ", False),
                                    ("우선순위 중심 재설계 필요." if pct >= 50 else "부족한 영역만 선별 보완.", False)],
                           quotes=[]))

    # 2 핵심 진단비
    diag = [it for it in items if it["group"] == "진단" and it["status"] == "부족"]
    top = sorted(diag, key=lambda it: -it["ns"])[:AN_TOP_N]
    if len(top) >= 2:
        sel = [it for it in items if it in top]                          # 그림은 원본 순서
        r_all = sum(i["np"] for i in sel) / sum(i["nn"] for i in sel) * 100
        rs = [i["np"] / i["nn"] * 100 for i in sel]
        slides.append(dict(kind="diag", label="핵심 진단비 분석", headline=f"진단비는 필요액의 약 {_rhu(r_all)}%만 준비",
                           sub=f"{', '.join(i['label'] for i in sel)} 진단비가 필요 금액 대비 크게 부족, 집중 보완 시급",
                           chart=dict(cats=[i["label"] for i in sel], need=[i["nn"] for i in sel], prep=[i["np"] for i in sel], xlabel="진단비 항목"),
                           table=[(i["label"], f"{i['short']}만원 부족") for i in top],
                           note=f"단위: 만원 · 필요액 대비 준비액 비율은 {_rhu(min(rs))}~{_rhu(max(rs))}% 수준",
                           quotes=[i["short"] for i in top]))
    # 3 항암 치료비
    chemo = [it for it in items if it["g"] == "항암"]
    if chemo:
        mx = max(i["nn"] for i in chemo)
        rep = [i for i in chemo if i["nn"] == mx]
        rep_r = _rhu(min(i["np"] / i["nn"] * 100 for i in rep))
        cards = []
        for i in sorted(chemo, key=lambda i: -i["nn"]):
            r = _rhu(i["np"] / i["nn"] * 100)
            cards.append((i["label"] + (" 치료" if not i["label"].endswith("치료") and not i["label"].endswith("약물치료") else ""),
                          f"필요 {i['need']} / 준비 {i['prep']}만원",
                          (f"{i['short']}만원 부족 (준비율 {r}%)" if i["ns"] else "필요액 충족"),
                          AN_T_NONE if r < AN_RED_BELOW else AN_T_LOW))
        names = ", ".join(i["label"] for i in rep)
        slides.append(dict(kind="chemo", label="암 치료 기술별 보장 현황", headline=f"항암 치료비는 필요액의 {rep_r}%만 준비",
                           sub=f"최신 {names} 등 비급여 치료비 필요액 {rep[0]['need']}만원 중 현재 {rep[0]['prep']}만원만 보장",
                           chart=dict(cats=[i["label"] for i in chemo], need=[i["nn"] for i in chemo], prep=[i["np"] for i in chemo], xlabel="항암 치료 항목"),
                           cards=cards, quotes=[c for i in chemo for c in (i["need"], i["prep"], i["short"]) if c != "-"], rep=rep, rep_r=rep_r))
    # 4 미보장
    if uncovered:
        names3, seen = [], set()
        for it in uncovered:
            nm = "치매" if "치매" in it["label"] else it["label"]
            if nm not in seen:
                seen.add(nm)
                names3.append(nm)
        cand = [it for it in uncovered if it["label"] in AN_CARE]          # 간병 관련 항목이 있으면 그 중 필요액 큰 2개, 없으면 전체 상위 2개
        pick = cand[:2] if cand else uncovered[:2]
        a, b = pick[0], (pick[1] if len(pick) > 1 else None)
        care = bool(cand)
        ins = [(a["label"], True), (f"({a['need']}만원)", True)]
        if b:
            ins += [("와 ", False), (b["label"], True), (f"({b['need']}만원)", True), (_josa(b["label"], "은", "는") + " ", False)]
        else:
            ins += [(_josa(a["label"], "은", "는") + " ", False)]
        ins += [("장기 간병 비용 부담이 가장 큰 항목." if care else "필요액이 가장 큰 항목.", False)]
        slides.append(dict(kind="uncovered", label=f"미보장 {len(uncovered)}개 영역",
                           headline=f"{', '.join(names3[:3])} 등 {len(uncovered)}개 항목 보장 없음",
                           sub=f"{', '.join(it['label'] for it in uncovered[:4])} 등 필요 보장의 준비액 0원",
                           bars=[(AN_DISP.get(it["label"], it["label"]), it["nn"]) for it in uncovered],
                           insight1=ins, insight2=[("현재 가입 계약에는 해당 담보가 전혀 포함되어 있지 않으므로 " +
                                                    ("노후 간병 대비책" if care else "대비책") + " 검토 필수.", False)],
                           quotes=[a["need"]] + ([b["need"]] if b else []), top2=(a, b), care=care))
    # 5 사망 보장
    death = [it for it in items if it["g"] == "사망"]
    if len(death) >= 2:
        rs = [i["np"] / i["nn"] * 100 for i in death]
        dg = [it for it in items if it["group"] == "진단" and it["np"] > 0]
        d_r = sum(i["np"] for i in dg) / sum(i["nn"] for i in dg) * 100 if dg else None
        d_all = sum(i["np"] for i in death) / sum(i["nn"] for i in death) * 100
        lead = "기납입 완료된 종신보험 덕분에 " if A["paid_whole_life"] else ""
        cmp_ = ("사망 보장은 진단비에 비해 양호" if (d_r is None or d_all > d_r) else "사망 보장도 진단비처럼 보완 필요")
        drop_age = None
        s = A["ages"].get(death[0]["label"], {})
        prev = None
        for ag in A["age_order"]:
            v = _num(s.get(ag))
            if prev is not None and v is not None and v < prev:
                drop_age = ag
                break
            prev = v if v is not None else prev
        note = (f"진단비(약 {_rhu(d_r)}%)에 비하면 상대적으로 충실히 준비되어 있으나" if d_r is not None and d_all > d_r else "") + \
               (f", {drop_age} 이후 감액 구조 확인 필요" if drop_age else ".")
        slides.append(dict(kind="death", label="사망 보장 점검", headline=f"사망 보장은 필요액의 {_rhu(min(rs))}~{_rhu(max(rs))}% 수준",
                           sub=lead + cmp_,
                           chart=dict(cats=[i["label"] for i in death], need=[i["nn"] for i in death], prep=[i["np"] for i in death], xlabel="사망 보장 구분"),
                           table=[(i["label"], f"{i['prep']} / {i['need']}", f"{r:.1f}%") for i, r in zip(death, rs)],
                           note=note.lstrip(", "), quotes=[v for i in death for v in (i["prep"], i["need"])]))
    # 6 안정 영역
    okitems = [it for it in items if it["status"] == "적정"]
    if okitems:
        gs = sorted({i["g"] for i in okitems}, key=lambda g: (-okg[g], order.index(g)))[:3]
        cards = []
        for g in gs:
            its = [i for i in okitems if i["g"] == g]
            minr = min(i["np"] / i["nn"] for i in its)
            full = all(i["np"] == i["nn"] for i in its)
            lines = [(i["label"], i["prep"], i["need"]) for i in its[:4]]
            cards.append(dict(title=f"{g} 보장", badge="✓ 100% 충족" if full else "✓ 적정 보장", lines=lines, more=len(its) - 4,
                              foot=("필요액 전액 충족" if full else ("필요액 이상 준비 완료" if minr < 1.1 else f"필요 대비 {int(minr * 10) / 10:.1f}배 이상 준비 완료"))))
        w2 = weak_all[:2]
        wn = [AN_TOPIC.get(g, g) for g in w2]
        st = ", ".join(gs)
        tail = (f"부족한 {wn[0]}{_josa(wn[0], '과', '와')} {wn[1]} 쪽으로 예산 집중이 경제적." if len(wn) == 2
                else (f"부족한 {wn[0]} 쪽으로 예산 집중이 경제적." if wn else "예산 배분 점검"))
        slides.append(dict(kind="stable", label=f"안정 영역 (적정 {len(okitems)}개 항목)", headline=f"{st} 충분, 간단 점검",
                           sub=f"{st}{_josa(st, '은', '는')} 필요 기준 이상 준비, 추가 지출을 줄여도 되는 안전 영역", cards=cards,
                           point=[("설계 포인트: ", True), (f"{st} 담보는 이미 충분하므로, 신규 가입 시 중복 투자를 피하고 " + tail, False)],
                           quotes=[v for c in cards for (_, p, n) in c["lines"] for v in (p, n)]))
    # 7 연령별 변화
    ages, ao = A["ages"], A["age_order"]

    def run(label):
        vals = [(ag, ages.get(label, {}).get(ag)) for ag in ao]
        return [(ag, v) for ag, v in vals if _num(v) is not None]
    changed = []
    for it in items:
        rr = run(it["label"])
        if len(rr) >= 2 and rr[0][1] != rr[-1][1]:
            vs = [_num(v) for _, v in rr]
            first_chg = next(k for k in range(1, len(rr)) if rr[k][1] != rr[k - 1][1])
            changed.append(dict(it=it, a_from=rr[first_chg - 1][0], a_to=rr[first_chg][0], v_from=rr[first_chg - 1][1], v_to=rr[first_chg][1],
                                rel=(_num(rr[first_chg][1]) - _num(rr[first_chg - 1][1])) / _num(rr[first_chg - 1][1]), rr=rr))
    drops = [c for c in changed if c["rel"] < 0]
    d_death = [c for c in drops if c["it"]["g"] == "사망"]          # 대표 항목 = 사망 영역에서 연령에 따라 줄어드는 첫 항목(원본 순서)
    if d_death:
        c1 = d_death[0]
        pct = _rhu(_num(c1["v_to"]) / _num(c1["v_from"]) * 100)
        big = -c1["rel"] * 100 >= AN_DROP_BIG
        rr = c1["rr"]
        cats, vals = [], []
        last_num = max([k for k, (ag, _) in enumerate(rr) if ag != "종신"] or [len(rr) - 1])
        for k, (ag, v) in enumerate(rr):                                  # 구간이 바뀌는 지점의 앞·뒤 연령과 마지막 숫자 연령만 그림에 올린다
            if k == 0 or k == last_num or rr[k - 1][1] != v or (k + 1 < len(rr) and rr[k + 1][1] != v):
                if ag != "종신":
                    cats.append(ag)
                    vals.append(_num(v))
        cards = [dict(title="사망 보장 축소", l1=f"{c1['a_from']}까지 {c1['v_from']}만원 유지", l2=f"{c1['a_to']}부터 {c1['v_to']}만원으로 {'급감' if big else '감소'}")]
        quotes = [c1["v_from"], c1["v_to"]]
        d_diag = sorted([c for c in drops if c["it"]["group"] == "진단"], key=lambda c: c["rel"] * _num(c["v_from"]))
        if d_diag:
            c2 = d_diag[0]
            cards.append(dict(title=f"{c2['it']['label']} 진단비 감액", l1=f"{c2['a_from']} {c2['v_from']}만원에서", l2=f"{c2['a_to']} 이후 {c2['v_to']}만원으로 감소"))
            quotes += [c2["v_from"], c2["v_to"]]
        ups = [c for c in changed if c["rel"] > 0 and c["it"]["g"] == "입원"]
        if ups:
            c3 = ups[0]
            nm = c3["it"]["label"].split("(")[0]
            cards.append(dict(title="입원 일당 소폭 증가", l1=f"{nm} 일당은 {c3['a_to']} 이후", l2=f"{c3['v_from']}만원 → {c3['v_to']}만원으로 증가"))
            quotes += [c3["v_from"], c3["v_to"]]
        slides.append(dict(kind="ages", label="연령별 보장 변화", headline=f"연령 증가 시 {c1['it']['g']}보장 {'크게 ' if big else ''}감소",
                           sub=f"{c1['a_from']} 이후 {c1['a_to']}에 도달하면 {c1['it']['label']} 보장금액 기존의 약 {pct}% 수준으로 축소",
                           chart=dict(cats=cats, vals=vals, title=f"{c1['it']['label']} 보장금액 (만원)", xlabel="연령 구간"), cards=cards, quotes=quotes))
    # 2 영역별 보장 준비 현황 (세대 분석 쪽을 대신함): 영역마다 Σmin(준비,필요) ÷ Σ필요, 다른 슬라이드에서 다루지 않은 부족 항목을 함께 정리
    area = []
    for g in order:
        its_ = [i for i in items if i["g"] == g and i["nn"]]
        ns_ = sum(i["nn"] for i in its_)
        if ns_ > 0:
            area.append(dict(g=g, rate=sum(min(i["np"], i["nn"]) for i in its_) / ns_ * 100, full=(lowg[g] + nong[g] == 0 and okg[g] > 0)))
    if len(area) >= 2:
        asc = sorted(area, key=lambda a_: a_["rate"])
        nfull = sum(1 for a_ in area if a_["full"])

        def _pr(r):
            return min(_rhu(r), 99) if r < 100 else _rhu(r)
        if nfull == len(area):
            head_ = f"{len(area)}개 보장 영역 모두 필요액 충족"
        elif nfull == 0:
            head_ = f"{len(area)}개 보장 영역 모두 보완 필요"
        else:
            head_ = f"{len(area)}개 보장 영역 중 필요액을 모두 채운 영역 {nfull}개"
        lows_ = [a_ for a_ in asc if a_["rate"] < 100][:3]
        sub_ = ("준비율이 낮은 영역은 " + ", ".join(f"{AN_TOPIC.get(a_['g'], a_['g'])} {_pr(a_['rate'])}%" for a_ in lows_) + " 순"
                if lows_ else "모든 영역의 준비율 100% 이상")
        bars_ = []
        for a_ in asc:
            col_ = AN_C_NONE if a_["rate"] < AN_RED_BELOW else (AN_C_LOW if a_["rate"] < 100 else AN_C_OK)
            bars_.append((a_["g"], min(a_["rate"], 100.0), col_, "#FFFFFF" if col_ in (AN_C_OK, AN_C_NONE) else "#111111", f"{_pr(a_['rate'])}%"))
        covered_ = {id(i) for i in top} if len(top) >= 2 else set()
        extra = [i for i in items if i["status"] == "부족" and i["nn"] and not (i["g"] == "항암" and chemo)
                 and not (i["g"] == "사망" and len(death) >= 2) and id(i) not in covered_]
        extra.sort(key=lambda i: i["np"] / i["nn"])
        rows_ = [(i["label"], f"{i['prep']} / {i['need']}", i["np"] / i["nn"] * 100) for i in extra[:AN_AREA_ROWS]]
        gen_ = next((e for e in entries if e["kind"] == "generation" and e["mode"] == "전용"), None)
        mem_ = gen_["data"]["members"] if gen_ else []
        who_ = f" · {mem_[0]['name']} ({mem_[0]['age']}세)" if len(mem_) == 1 else ""
        more_ = len(extra) - len(rows_)
        slides.insert(1, dict(kind="area", label="영역별 보장 준비 현황" + who_, headline=head_, sub=sub_, bars=bars_, rows=rows_, more=more_,
                              note="※ 다른 슬라이드에서 다루지 않은 부족 항목. 준비율 낮은 순, 단위 만원." + (f" 외 {more_}개 항목." if more_ > 0 else ""),
                              quotes=[v for r_ in rows_ for v in r_[1].split(" / ")] + ([mem_[0]["age"]] if len(mem_) == 1 else [])))
    # 8 보완 순서
    steps = []
    # 1.44: 순서 = 암 진단비 → 항암 치료비 → 뇌·심장 진단비 → 미보장. 암이 발생·사망이 가장 많고 치료비 부담도 커서 먼저 둔다(정리자 제안).
    def _two(lst):
        t_ = sorted(lst, key=lambda i: -i["ns"])[:2]
        return (f"{t_[0]['label']}, {t_[1]['label']}" if len(t_) == 2 else t_[0]["label"],
                ", ".join(f"{i['label']} {i['short']}만원" for i in t_), [i["short"] for i in t_])
    cancer_d = [it for it in diag if "암" in it["label"]]
    if cancer_d:
        nm_, ds_, q_ = _two(cancer_d)
        steps.append((f"{nm_} 진단비 먼저", f"부족액: {ds_}", q_))
    for sl in slides:
        if sl["kind"] == "chemo":
            nm = ", ".join(i["label"].replace("항암", "") for i in sl["rep"])
            steps.append(("항암 치료비 보완", f"{nm} 치료비 준비율 {sl['rep_r']}%", []))
    bh_d = [it for it in diag if "암" not in it["label"] and ("뇌" in it["label"] or "심" in it["label"])]
    if bh_d:
        nm_, ds_, q_ = _two(bh_d)
        steps.append((f"{nm_} 진단비 보완", f"부족액: {ds_}", q_))
    elif not cancer_d and len(top) >= 2:
        nm_, ds_, q_ = _two(top)
        steps.append((f"{nm_} 진단비 먼저", f"부족액: {ds_}", q_))
    unc = next((sl for sl in slides if sl["kind"] == "uncovered"), None)
    if unc:
        a, b = unc["top2"]
        nm = f"{a['label']}, {b['label']}" if b else a["label"]
        steps.append((f"미보장 {len(uncovered)}개 중 {nm} 검토", "필요액: " + f"{a['label']} {a['need']}만원" + (f", {b['label']} {b['need']}만원" if b else ""),
                      [a["need"]] + ([b["need"]] if b else [])))
    if steps:
        ymd = re.match(r"(\d{4})-(\d{1,2})-(\d{1,2})", basis or "")
        when = f"{int(ymd.group(1))}년 {int(ymd.group(2))}월 {int(ymd.group(3))}일" if ymd else (basis or "")
        caution = [("확인할 점: ", True), ((f"수치는 {when} 기준이며 " if when else "수치는 ") + "약관, 증권과 다를 수 있음." +
                                          (" 1년 이내 가입 상품은 50% 감액 가능." if A["foot50"] else ""), False)]
        slides.append(dict(kind="plan", label="보완 순서 제안 & 유의사항", headline="보완 순서 제안과 확인할 점",
                           sub=("암은 발생과 사망이 가장 많고 치료비 부담이 커 우선 배치. 순서는 정리자 제안." if cancer_d or any(s_[0].startswith("항암") for s_ in steps) else "보완 순서는 정리자 제안."),
                           steps=steps, caution=caution, quotes=[q for s_ in steps for q in s_[2]]))
    for s_ in slides:                                            # 1.29: 안정 영역도 그래프+표 형식으로
        if s_["kind"] == "stable":
            ok_ = sorted([it for it in items if it["status"] == "적정" and it["nn"]], key=lambda it: -it["nn"])[:6]
            if ok_:
                s_.update(kind="stablechart", chart=dict(cats=[i["label"] for i in ok_], need=[i["nn"] for i in ok_], prep=[i["np"] for i in ok_], xlabel="적정 항목"),
                          table=[(i["label"], f"{i['prep']} / {i['need']}", f"{i['np'] / i['nn'] * 100:.1f}%") for i in ok_],
                          note="단위 만원. 필요액 이상 준비, 추가 지출을 줄여도 되는 항목.",
                          quotes=[v for i in ok_ for v in (i["prep"], i["need"])])
    plan_ = slides.pop() if slides and slides[-1]["kind"] == "plan" else None
    slides += extra_slides(entries, ctx, A)                      # 1.27: 원본 나머지 쪽(3, 4~7, 8, 9~10, 11~24, 25쪽)
    if plan_:
        slides.append(plan_)
    # 1.28: 원본 쪽 순서대로 정렬(같은 구간 안에서는 만든 순서 유지). 3쪽 → 4~7쪽 → 8쪽 → 9~10쪽 → 11~24쪽 → 25쪽 → 정리자 제안
    # 1.53: 기준 목차 순서 — 5 세대 보장요약(summary) → 6 종합요약(score) → 7 세대 분석(area) → 8 상품별 분석(diag … contracts)
    src_order = {"enroll": -1, "summary": 0, "score": 1, "area": 2, "diag": 2, "death": 2, "chemo": 2, "uncovered": 2, "stable": 2,
                 "stablechart": 2, "contracts": 3, "bodyfig": 4, "bodymap": 4, "ages": 5, "agetable": 5, "other": 6, "pcdetail": 6, "pcgraph": 6, "proposal": 7, "plan": 8, "pcnoamt": 9}
    slides.sort(key=lambda s_: src_order.get(s_["kind"], 1))
    return slides


BASE_FS = 19      # 1.47: 기본 글꼴 크기(디자인 좌표). 2쪽 표의 "보험사/계약 현황" 글꼴이 기준이다
NOTE_FS = 18      # 1.47: 주석(※)·보조 설명 — 기본보다 한 단계 작게, 굵게 없이
NOTE_SRC = 14     # 1.47: 예전에 주석·보조 설명으로 쓰던 크기
BASE_SRC = (15, 16, 16.5, 17, 18)   # 1.47: 예전에 본문·표·축 글로 쓰던 작은 크기들 → 기본 크기로 올린다


def _fs(size, bold=False):
    """1.47: 글꼴 크기 규칙. (크기, 굵게) 를 돌려준다. 이미 규칙을 거친 값은 다시 넣지 않는다."""
    if size == NOTE_SRC:
        return NOTE_FS, bold or BOLD_ALL
    if size in BASE_SRC:
        return BASE_FS, bold
    return size, bold


class Deck:
    """분석 슬라이드 그리기 도구. 좌표는 1456×819 가상 화면(왼쪽 위 기준, px)이며 16:9 쪽 크기에 비율 그대로 맞춘다."""
    K = WIDE_W / 1456.0

    def __init__(self, c):
        self.c = c
        self.armed = False                                   # 1.40: 틀(꼬리말)을 그린 뒤부터 본문 글이 쪽 바닥(꼬리말 선)을 넘는지 검사
        self.limit = (WIDE_H - 12 * mm) / self.K - 6
        self.over = []

    def X(self, v):
        return v * self.K

    def Y(self, v):
        return WIDE_H - v * self.K

    def box(self, x, y, w, h, fill=None, stroke=None, r=0, lw=1, dash=None):
        c = self.c
        c.saveState()
        if fill:
            c.setFillColor(colors.HexColor(fill))
        if stroke:
            c.setStrokeColor(colors.HexColor(stroke))
            c.setLineWidth(lw * self.K)
        if dash:
            c.setDash(*[d * self.K for d in dash])
        c.roundRect(self.X(x), self.Y(y + h), w * self.K, h * self.K, r * self.K, fill=1 if fill else 0, stroke=1 if stroke else 0)
        c.restoreState()

    def line(self, x1, y1, x2, y2, color, lw=1, dash=None):
        c = self.c
        c.saveState()
        c.setStrokeColor(colors.HexColor(color))
        c.setLineWidth(lw * self.K)
        if dash:
            c.setDash(*[d * self.K for d in dash])
        c.line(self.X(x1), self.Y(y1), self.X(x2), self.Y(y2))
        c.restoreState()

    def _font(self, s, bold):
        bold = bold or BOLD_ALL
        miss = bool(GLYPHS) and any(ord(ch) >= 128 and ord(ch) not in GLYPHS for ch in s)
        font = CID_FALLBACK if miss else (FONT_B if bold else FONT)
        return font, bold and (miss or FONT_B == FONT or BOLD_FAKE)

    def width(self, s, size, bold=False, _raw=True):
        if _raw:
            size, bold = _fs(size, bold)
        font, _ = self._font(s, bold)
        return pdfmetrics.stringWidth(s, font, size * self.K) / self.K

    def text(self, x, y, s, size, color, bold=False, align="L", _raw=True):
        if _raw:
            size, bold = _fs(size, bold)
        w = self.width(s, size, bold, False)
        if self.armed and y > self.limit:
            self.over.append(s)
        x0 = x - w if align == "R" else (x - w / 2 if align == "C" else x)
        font, fake = self._font(s, bold)
        col = colors.HexColor(color) if isinstance(color, str) else color
        t = self.c.beginText(self.X(x0), self.Y(y))
        t.setFont(font, size * self.K)
        t.setFillColor(col)
        t.setTextRenderMode(2 if fake else 0)               # 글자 그리기 방식은 다음 글자에도 이어지므로 매번 정한다
        if not fake:
            t._code.append("0 Tr")                          # 1.32: reportlab 은 0 을 내보내지 않아 앞 글자의 굵게(2 Tr)가 이어졌다 — 직접 넣는다
        if fake:
            self.c.setStrokeColor(col)
            self.c.setLineWidth(size * self.K * 0.025)
        t.textOut(s)
        self.c.drawText(t)
        return x0 + w

    def para(self, x, y, w, spans, size, color, lead=1.42):
        """여러 줄 글. spans = [(글, 굵게)]. 단어 단위로 줄을 나눈다. 마지막 줄 아래 y 를 돌려준다."""
        toks = []
        if size == NOTE_SRC and not BOLD_ALL:                # 1.47: 주석·보조 설명은 굵게 없이 (1.49: 모두 굵게일 때는 제외)
            spans = [(t, False) for t, b in spans]
        size = _fs(size)[0]
        for t, b in spans:
            for p in re.split(r"(\s+)", t):
                if p:
                    toks.append((p, b, self.width(p, size, b, False)))
        lines, cur = [[]], 0.0
        for p, b, pw in toks:
            if p.isspace():
                if lines[-1]:
                    lines[-1].append((p, b, pw))
                    cur += pw
                continue
            if cur + pw > w and lines[-1]:
                lines.append([])
                cur = 0.0
            lines[-1].append((p, b, pw))
            cur += pw
        yy = y
        for ln in lines:
            xx = x
            for p, b, pw in ln:
                if not p.isspace():
                    self.text(xx, yy, p, size, color, b, "L", False)
                xx += pw
            yy += size * lead
        return yy

    def chip(self, x, y, color, label):
        w = self.width(label, 14) + 56
        self.box(x, y, w, 30, fill="#FFFFFF", stroke="#D9DEE6", r=15)
        self.box(x + 14, y + 9, 12, 12, fill=color, r=3)
        self.text(x + 34, y + 21, label, 14, "#374151")
        return x + w + 14

    def vbars(self, x, y, w, h, cats, series, ymax, xlabel=""):
        """묶음 세로 막대. series = [(이름, 색, 값들)]. 점선 틀 안에 그리고 막대 안(작으면 위)에 값을 적는다."""
        fx, fw = x + 52, w - 52
        self.box(fx, y, fw, h, stroke="#DDE2E9", r=10, dash=(4, 4))
        base, topy = y + h - 12, y + 26
        self.text(x + 44, base + 5, "0", 15, "#374151", align="R")
        self.text(x + 44, topy + 5, _fmt_k(ymax), 15, "#374151", align="R")
        self.line(fx, topy, fx + fw, topy, "#DDE2E9", 1, (4, 4))
        n, ns = len(cats), len(series)
        sw = fw / n
        bw = min(52.0, sw * 0.8 / ns)
        gap = 8
        for i, cat in enumerate(cats):
            gw = ns * bw + (ns - 1) * gap
            gx = fx + sw * i + (sw - gw) / 2
            for j, (_, col, vals) in enumerate(series):
                v = vals[i]
                bh = max(2.0, v / ymax * (base - topy))
                bx, by = gx + j * (bw + gap), base - bh
                self.box(bx, by, bw, bh, fill=col, r=6)
                lab = _fmt_k(v)
                dark = col in (AN_C_NEED, "#2E5C8F", "#1E3A5F")
                if bh >= 34:
                    self.text(bx + bw / 2, by + 24, lab, 15, "#FFFFFF" if dark else "#111111", align="C")
                else:
                    lw_ = self.width(lab, 15) + 14
                    self.box(bx + bw / 2 - lw_ / 2, by - 30, lw_, 24, fill="#E3E5E8", r=8)
                    self.text(bx + bw / 2, by - 12, lab, 15, "#111111", align="C")
            self.text(fx + sw * i + sw / 2, y + h + 32, cat, 17, "#1F2937", align="C")
        if xlabel:
            self.text(fx + fw / 2, y + h + 64, xlabel, 16, "#374151", align="C")

    def hbars(self, x, y, w, rows, vmax, step, axis_title, label_w=110, bar_h=34, gap=14, show_val=True, up=0):
        """가로 막대. rows = [(이름, 값, 색, 값글자색)]. 점선 틀 + 눈금."""
        n = len(rows)
        ph = n * bar_h + (n - 1) * gap + 40
        px0, pw = x + label_w, w - label_w
        self.box(px0, y, pw, ph, stroke="#DDE2E9", r=10, dash=(4, 4))
        k = 0
        while k * step <= vmax + 1e-9:
            gx = px0 + 10 + (pw - 20) * (k * step) / vmax
            if k:
                self.line(gx, y, gx, y + ph, "#E5E8ED", 1, (4, 4))
            self.text(gx, y + ph + 26 + up, _fmt_k(k * step) if vmax >= 1000 else f"{int(k * step)}", (BASE_FS + up - 2) if up else 15, "#374151", align="C")
            k += 1
        for i, r_ in enumerate(rows):
            nm, v, col = r_[0], r_[1], r_[2]
            by = y + 20 + i * (bar_h + gap)
            bw = max(8.0, (pw - 20) * v / vmax)
            self.box(px0 + 10, by, bw, bar_h, fill=col, r=8)
            self.text(px0 - 12, by + bar_h / 2 + 6 + up / 2, nm, (BASE_FS + up) if up else 17, "#1F2937", align="R")
            if show_val:
                self.text(px0 + 10 + bw - 12, by + bar_h / 2 + 6, f"{int(v)}", 15, r_[3] if len(r_) > 3 else "#111111", align="R")
        self.text(px0 + pw / 2, y + ph + 58 + up * 1.5, axis_title, (BASE_FS + up - 2) if up else 16, "#374151", align="C")
        return y + ph + 64


AN_HEAD_BOX = (67, 40, 1321, 94)             # 헤더 박스 x, y, 폭, 높이 (모든 분석 쪽 같음)
AN_HEAD_FILL = "#3A6FC4"                      # 헤더 박스 바탕 (밝은 파랑, 1.33: 이전 #17306B)
AN_HEAD_TEXT = "#FFFFFF"                      # 헤더 글자 (흰색)
AN_HEAD_SUB = "#E6EEFB"                       # 헤더 안 작은 글자
AN_HEAD_PT = 36                               # 헤더 결론 제목 글자 크기 (넘치면 최소 26까지 줄임)


def D_fit_head(D, txt, maxw, up=0):
    sz = float(AN_HEAD_PT + min(up, 2))                     # 제목은 헤더 박스 높이 때문에 최대 +2
    while sz > 26 and D.width(txt, sz, True) > maxw:
        sz -= 0.5
    return sz


def _slide_frame(D, s, n, N, name, basis):
    """분석 쪽 틀 — 요약 1~3쪽과 같은 분위기: 흰 바탕, 작은 제목+오른쪽 표시, 같은 꼬리말, 오른쪽 끝 tall."""
    c = D.c
    c.setFillColor(colors.HexColor(AN_BG))
    c.rect(0, 0, WIDE_W, WIDE_H, fill=1, stroke=0)
    # 1.32: 헤더 = 모든 분석 쪽 같은 위치·크기(AN_HEAD_BOX)의 파랑 박스 + 흰 글자. 작은 제목(왼쪽 위)·고객 표시(오른쪽 위)·결론 제목.
    hx, hy, hw, hh = AN_HEAD_BOX
    D.box(hx, hy, hw, hh, fill=AN_HEAD_FILL, r=12)
    up = s.get("fs_up", 0)                                          # 1.88: 가입상품 보장내역 쪽만 머리글 글자를 키운다
    lab_sz = (BASE_FS + up) if up else 15
    D.text(hx + 28, hy + 30, s["label"], lab_sz, AN_HEAD_SUB, True)
    D.text(hx + hw - 28, hy + 30, (f"{name} 고객님 / 분석" if name else "분석"), lab_sz, AN_HEAD_SUB, False, "R")
    hsz = D_fit_head(D, s["headline"], hw - 56, up)
    if s.get("head_center"):                                        # 1.81: 짧은 제목은 헤더 박스 가운데에 놓는다
        D.text(hx + hw / 2, hy + 74, s["headline"], hsz, AN_HEAD_TEXT, True, "C")
    else:
        D.text(hx + 28, hy + 74, s["headline"], hsz, AN_HEAD_TEXT, True)
    D.text(67, 172, s["sub"], 23 + up, AN_SUB)
    c.saveState()                                                   # 꼬리말: 요약 쪽(draw_footer)과 같은 선·글자 크기·위치
    c.setStrokeColor(colors.HexColor("#D1D5DB"))
    c.line(W_MARGIN_X, 12 * mm, WIDE_W - W_MARGIN_X, 12 * mm)
    c.restoreState()
    fy, fs = (WIDE_H - 8 * mm) / D.K, 7.5 / D.K
    foot = (f"{name} 고객님 " if name else "") + f"보장분석 요약 · {basis} 기준 · 보험금 지급 근거 아님, 약관·증권 우선"
    if FOOTER_TEXT_SHOW:
        D.text(W_MARGIN_X / D.K, fy, foot, fs, AN_GRAY)
    D.text((WIDE_W - W_MARGIN_X) / D.K, fy, f"{n} / {N}", fs, AN_GRAY, align="R")
    draw_tall(c)
    D.armed = True


SLIDE_SCALE = 1.0                     # 1.79: 분석 PDF 모든 쪽의 본문(머리글 아래~꼬리말 위)을 이 비율로 줄여 좌우·아래 여백을 넓힌다(1.0 = 줄이지 않음)
SLIDE_ANCHOR = (723.5, 190.0)         # 줄일 때 고정하는 점(본문 가로 가운데, 머리글 아래 위쪽)


def _draw_slide(D, s, n, N, ctx):
    """틀(머리글·꼬리말·tall)은 그대로 두고, 본문만 SLIDE_SCALE 로 줄여 모든 쪽에 같은 여백을 준다."""
    _slide_frame(D, s, n, N, ctx.get("name", ""), ctx.get("basis", ""))
    c = D.c
    c.saveState()
    if SLIDE_SCALE != 1.0:
        ax, ay = D.X(SLIDE_ANCHOR[0]), D.Y(SLIDE_ANCHOR[1])
        c.translate(ax, ay)
        c.scale(SLIDE_SCALE, SLIDE_SCALE)
        c.translate(-ax, -ay)
    try:
        _draw_slide_body(D, s, n, N, ctx)
    finally:
        c.restoreState()


def _draw_slide_body(D, s, n, N, ctx):
    k = s["kind"]
    if k == "summary":
        # 1.50: 2쪽과 같은 배치 — 본문은 왼쪽 2/3, 오른쪽 1/3 에 진단 엠블럼(새 로고 디자인)
        pw, ph = 470.0, 540.0
        png = make_gauge_png(pw * D.K, ph * D.K)
        D.c.drawImage(ImageReader(io.BytesIO(png)), D.X(918), D.Y(196 + ph), width=pw * D.K, height=ph * D.K, mask="auto")
        cw_, gp_ = 262, 19
        for i, (lab, val, tc, bc, desc) in enumerate(s["cards"]):
            x = 67 + i * (cw_ + gp_)
            D.box(x, 196, cw_, 230, fill=AN_CARD, stroke=AN_CARD_LINE, r=10, lw=2)
            D.box(x + 22, 228, 14, 14, fill=bc, r=7)
            D.text(x + 44, 243, lab, 17, "#374151")
            wv = D.width(str(val), 66, True) + 4 + D.width("개", 30, True)      # 1.34: 카드 숫자는 오른쪽 정렬
            xe = D.text(x + cw_ - 22 - wv, 318, str(val), 66, tc, True)
            D.text(xe + 4, 318, "개", 30, tc, True)
            D.para(x + 22, 356, cw_ - 44, [(desc, False)], 14, "#374151", 1.3)
        D.text(67, 468, "보장 상태", 16, "#1F2937", True)
        vmax = max(20, _nice_max(max(b[1] for b in s["bars"])))
        D.hbars(67, 486, 470, [(a, b_, c_, t_) for a, b_, c_, t_ in s["bars"]], vmax, 5, "항목 수 (개)", 80, 40, 18)
        D.box(565, 454, 324, 290, fill=AN_BOX, r=12)
        D.text(590, 504, "분석 인사이트", 24, AN_INK, True)
        D.para(590, 546, 276, s["insight"], 19, AN_INK, 1.5)
    elif k in ("diag", "death"):
        ch = s["chart"]
        x = D.chip(67, 200, AN_C_NEED, "필요액 (만원)")
        D.chip(x, 200, AN_C_PREP, "준비액 (만원)")
        ymax = _nice_max(max(ch["need"] + ch["prep"]))
        D.vbars(67, 262, 790, 230, ch["cats"], [("필요", AN_C_NEED, ch["need"]), ("준비", AN_C_PREP, ch["prep"])], ymax, ch["xlabel"])
        if k == "diag":
            D.text(932, 235, "진단 항목", 19, AN_INK, True)
            D.text(1300, 235, "부족 금액", 19, AN_INK, True, "R")
            D.text(1316, 235, "상태", 19, AN_INK, True)
            D.line(918, 252, 1388, 252, "#BFC5CF", 2)
            for i, (a, b_) in enumerate(s["table"]):
                yy = 290 + i * 42
                D.text(932, yy, a, 19, AN_INK, True)
                m_ = re.fullmatch(r"(.+원)\s+(부족)", b_)                       # 1.35: 금액 칸(오른쪽) + 상태 칸(왼쪽) 가상 셀
                D.text(1300, yy, m_.group(1) if m_ else b_, 19, AN_T_NONE if i < 2 else AN_T_LOW, i < 2, "R")
                if m_:
                    D.text(1316, yy, m_.group(2), 19, AN_T_NONE if i < 2 else AN_T_LOW, i < 2)
                D.line(918, yy + 14, 1388, yy + 14, "#E1E5EB", 1.5)
