# ----------------------------------------------------------------------------
# 6-C. 누락 쪽 보충 분석 슬라이드 (1.27, 1.29 에서 4~9·15·31쪽 형식으로 통일)
#   형식: 결론 제목 + 한 줄 설명 + 왼쪽 그래프(Deck.hbars/vbars) + 오른쪽 분석 인사이트(상자 또는 카드). 표만 늘어놓지 않는다.
#     원본 3쪽  종합요약          → score        영역별 점수 막대 + 가장 낮은 영역·부족액 큰 항목
#     원본 4~7쪽 상품별 분석 표    → contracts    계약별 보장 항목 수 막대 + 가장 넓은 계약·보장 없는 계약
#     원본 8쪽  신체부위별 보장    → bodymap      보장 있는 항목 금액 막대 + 0원 항목
#     원본 9~10쪽 연령별 분석 표   → agetable     연령별 보장 중인 항목 수 막대 + 줄어드는 시점 카드
#     원본 11~24쪽 타사 가입 현황  → other        계약 1건당 1장: 보장금액 큰 항목 막대 + 특약 수·종료일·보험료 카드
#     원본 25쪽 보장 제안(전/후)   → proposal     충분/부족/미보장 전후 막대 + 변경 건수 인사이트
#     (안정 영역)                  → stablechart  적정 항목 필요/준비 막대 + 준비율 표
#   고정값: 원 ÷ 10,000 = 만원(나누어떨어질 때만), 막대 수 8개 이하 34px·10개 이하 30px·초과 26px, X_OTHER_MAX_ROWS=16.
# ----------------------------------------------------------------------------
X_KINDS = ("enroll", "score", "bodyfig", "bodymap", "contracts", "agetable", "other", "proposal", "stablechart")
X_INSIGHT_MAX_LINES = 10           # 1.61: 인사이트 상자에 한 줄씩 적는 계약 수(넘으면 마지막 줄을 `외 N건`)
X_CONTRACTS_PER_SLIDE = 3         # 계약별 보장 슬라이드 한 장에 올리는 계약 수
X_OTHER_MAX_ROWS = 16             # 타사 가입 현황 슬라이드 표에 올리는 보장항목 수 (금액 큰 순, 좌우 2열)
X_AGE_NOTE = "직전 연령 대비: 초록 = 늘어난 값, 주황 = 줄어든 값, 빨강 = 사라진 보장"


def _short_name(s):
    s = re.sub(r"^\(?무배당\)?\s*", "", (s or "").strip())
    s = re.sub(r"\s*\([^()]*\)\s*$", "", s)
    return s.strip() or (s or "")


def _won_man(v):
    v = int(v)
    return f"{v // 10000:,}만원" if v % 10000 == 0 else f"{v:,}원"


def _status_color(st):
    return {"충분": AN_T_OK, "적정": AN_T_OK, "부족": AN_T_LOW, "미보장": AN_T_NONE}.get(st, AN_INK)


def parse_score_page(page):
    """원본 3쪽 종합요약: 종합점수, 결론 문장, 영역별 점수와 항목(보장/필요/부족)."""
    ws = page.extract_words(extra_attrs=["size"])
    w3 = float(page.width) / 3.0

    def sz(w, s):
        return abs(w["size"] - s) < 0.35

    def col(w):
        return min(2, int(w["x0"] // w3))
    total = next((w["text"] for w in ws if sz(w, 16) and w["text"].endswith("점")), "")
    cw = [w for w in ws if 100 < w["top"] < 150 and w["x0"] < 470 and (sz(w, 14) or sz(w, 15))]
    cw.sort(key=lambda w: (round(w["top"] / 6), w["x0"]))
    concl = " ".join(w["text"] for w in cw)
    names = [w for w in ws if sz(w, 14) and w["top"] > 200 and not w["text"].endswith("점")]
    scores = [w for w in ws if sz(w, 14) and w["top"] > 200 and w["text"].endswith("점")]
    if len(names) < 2:
        raise ParseError("종합요약에서 영역 이름을 찾지 못했습니다.")
    cut = max(w["top"] for w in names) - 40

    def rowof(t):
        return 1 if t > cut else 0
    areas = {}
    for w in names:
        areas[(rowof(w["top"]), col(w))] = dict(name=w["text"], score="", items=[], x0=w["x0"], top=w["top"])
    for sc in scores:
        k = (rowof(sc["top"]), col(sc))
        if k in areas and not areas[k]["score"]:
            areas[k]["score"] = sc["text"]
    for lw in sorted([w for w in ws if sz(w, 8) and w["top"] > 150], key=lambda w: (w["top"], w["x0"])):
        k = (rowof(lw["top"]), col(lw))
        if k not in areas:
            continue
        st_words = sorted([w for w in ws if sz(w, 7) and abs(w["top"] - lw["top"]) < 3 and w["x0"] > lw["x1"] and col(w) == col(lw)],
                          key=lambda w: w["x0"])
        if not st_words:
            continue
        st_txt = "".join(w["text"] for w in st_words)
        nums = [w for w in ws if sz(w, 6) and 3 < w["top"] - lw["top"] < 14 and w["x0"] >= lw["x0"] - 2 and col(w) == col(lw)]
        boj = next((w["text"][2:] for w in nums if w["text"].startswith("보장")), "")
        pil = next((w["text"][2:] for w in nums if w["text"].startswith("필요")), "")
        if not boj or not pil:
            continue
        status = st_txt if st_txt in ("충분", "미보장") else "부족"
        areas[k]["items"].append(dict(label=lw["text"], status=status, short=st_txt.lstrip("-").strip() if status == "부족" else "",
                                      boj=boj, pil=pil))
    out = [areas[k] for k in sorted(areas)]
    if not total or not any(a["items"] for a in out):
        raise ParseError("종합요약 항목을 읽지 못했습니다.")
    return dict(total=total, concl=concl, areas=out)


def _wide_name(s):
    """계약 이름을 막대 이름칸에 들어가게 줄인다(앞의 무배당·보험사 이름 제거, 11자까지)."""
    s = re.sub(r"^\(?무배당\)?\s*", "", (s or "").strip())
    s = re.sub(r"^(삼성화재|삼성|흥국화재해상|흥국|교보)\s*", "", s)
    s = re.sub(r"\s*\([^()]*\)\s*$", "", s).strip()
    for w_ in ("올라이프 ", "건강보험", "교보", "흥"):
        s = s.replace(w_, "", 1) if s.startswith(w_) or w_ in ("건강보험",) else s
    s = s.strip()
    return s if len(s) <= 13 else s[:12] + "…"


def _score_color(v):
    return AN_C_NONE if v < 30 else (AN_C_LOW if v < 60 else AN_C_OK)


def score_slide(entries):
    e = next((x for x in entries if x["kind"] == "generic" and "종합요약" in x["text"][:60]), None)
    if not e:
        return None
    try:
        d = parse_score_page(e["page"])
    except Exception as ex:
        print(f"[주의] 분석: 종합요약(원본 p.{e['n']})을 읽지 못해 점수 슬라이드를 넣지 않았습니다. ({ex})")
        return None
    n_items = sum(len(a["items"]) for a in d["areas"])
    print(f"[분석] 종합요약 점수 슬라이드: 영역 {len(d['areas'])}개 / 항목 {n_items}개 읽음")
    concl = d["concl"]                                   # 1.46: 원본 문장 그대로 쓴다(구어체로 바꾸지 않음)
    areas = [a for a in d["areas"] if _num(a["score"].replace("점", "")) is not None]
    if not areas:
        return None
    by = sorted(areas, key=lambda a: _num(a["score"].replace("점", "")))
    w1, w2 = by[0], (by[1] if len(by) > 1 else None)
    allit = [dict(it, area=a["name"]) for a in d["areas"] for it in a["items"]]
    none_n = sum(1 for it in allit if it["status"] == "미보장")
    low = [it for it in allit if it["status"] == "부족" and _num(it["short"]) is not None]
    top = max(low, key=lambda it: _num(it["short"])) if low else None
    ins1 = [(w1["name"], True), (f"({w1['score']})", True), (" 영역이 가장 낮음. ", False)]
    if w2:
        ins1 += [(w2["name"], True), (f"({w2['score']})", True), (_josa(w2["score"], "이", "가") + " 그다음.", False)]
    ins2 = [(f"종합요약에 나온 {len(allit)}개 항목 중 미보장 {none_n}개, 준비액 0원. ", False)]
    q = [d["total"]] + [a["score"] for a in areas]
    if top:
        ins2 += [("부족액이 가장 큰 항목: ", False), (top["label"], True), (f"({top['short']}만원)", True), (".", False)]
        q.append(top["short"])
    return dict(kind="score", label="종합요약 / 영역별 점수", headline=f"종합점수 {d['total']}", sub=concl,
                bars=[(a["name"], _num(a["score"].replace("점", "")), _score_color(_num(a["score"].replace("점", ""))), a["score"]) for a in areas],
                insight1=ins1, insight2=ins2, quotes=q)


BODY_TITLE = {"뇌": "뇌", "암": "암", "당뇨": "당뇨", "치매": "치매", "심장": "심장", "말기 장기질환": "말기 장기질환"}


def bodymap_slide(entries):
    e = next((x for x in entries if x["kind"] == "body" and x["mode"] == "전용"), None)
    if not e:
        return None
    body = e["data"]["body"]
    have, zero_g, tot, zero = [], [], 0, 0
    for g, labs in BODY_GROUPS:
        zl = []
        for lab in labs:
            amt, st = body[lab]
            tot += 1
            if st == "미보장" or _num(amt) in (None, 0.0):
                zero += 1
                zl.append(lab)
            else:
                have.append((lab, _num(amt), amt, st))
        if zl:
            zero_g.append((g, zl))
    if not have:
        return None
    have.sort(key=lambda r: -r[1])
    bars = [(lab, v, {"충분": AN_C_OK, "부족": AN_C_LOW}.get(st, AN_C_LOW), amt) for lab, v, amt, st in have]
    ins1 = [(f"{tot}개 항목 중 ", False), (f"{zero}개", True), (" 항목 보장 0원.", False)]
    ins2 = []
    for g, zl in zero_g[:4]:
        ins2 += [(g + ": ", True), (", ".join(zl) + (" / " if (g, zl) != zero_g[:4][-1] else ""), False)]
    return dict(kind="bodymap", label="신체부위별 보장현황", headline=f"신체부위 {tot}개 항목 중 보장 없음 {zero}개",
                sub=f"보장 있는 항목 {tot - zero}개, 금액 단위 만원", bars=bars, insight1=ins1, insight2=ins2,
                insight2_lines=[f"{g}: {lab}" for g, zl in zero_g for lab in zl][:X_INSIGHT_MAX_LINES],     # 1.62: 보장 없는 항목 한 줄에 하나
                quotes=[amt for _, _, amt, _ in have])


def bodyfig_slide(entries):
    """1.55: 원본 신체부위별 보장현황(사람 그림 + 연결선 + 18개 항목 금액) 쪽. 그림·항목·금액은 요약 PDF와 같은 BodyMap 을 쓴다."""
    e = next((x for x in entries if x["kind"] == "body" and x["mode"] == "전용"), None)
    if not e:
        return None
    body = e["data"]["body"]
    cnt = {"충분": 0, "부족": 0, "미보장": 0}
    for g, labs in BODY_GROUPS:
        for lab in labs:
            cnt[body[lab][1]] += 1
    return dict(kind="bodyfig", label="신체부위별 보장현황", headline="신체부위별 보장현황",
                sub=f"충분 {cnt['충분']}개, 부족 {cnt['부족']}개, 미보장 {cnt['미보장']}개 (단위 만원)", body=body,
                quotes=[body[lab][0] for _, labs in BODY_GROUPS for lab in labs])


# ---- 1.57: 신체부위별 보장현황 쪽 새 디자인 (그림·글꼴·색 모두 코드로 새로 그린다) -----------------------
BF_INK = "#0A0A0A"                                   # 항목명 글자색 (거의 검정)
BF_TEXT = {"충분": "#00574B", "부족": "#374151", "미보장": "#A80F0F"}      # 금액 글자색(진하게)
BF_PILL = {"충분": "#00897B", "부족": "#6B7280", "미보장": "#D32F2F"}      # 상태 알약 바탕색
BF_ROWBG = {"충분": "#DDF3EF", "부족": "#E5E7EB", "미보장": "#FBDADA"}    # 항목 줄 바탕색
BF_HEAD = "#1F3F7A"                                  # 영역 머리글 바탕
BF_ROW_H, BF_HEAD_H, BF_GAP = 42, 36, 12
BF_COL_W = 403
BF_LEFT_X, BF_RIGHT_X = 67, 918
BF_TOP = 196
BF_CX = 694                                          # 인체 그림 가운데 x
BF_LEFT = [("뇌", ["뇌출혈", "뇌경색", "뇌혈관질환", "산정특례(뇌)"]), ("암", ["일반암", "고액암", "소액암", "표적항암"]), ("당뇨", ["당뇨"])]
BF_RIGHT = [("치매", ["LTC(치매)", "중등도치매", "경도치매"]), ("심장", ["급성심근경색", "허혈성심장질환", "산정특례(심장)"]),
            ("말기 장기질환", ["말기폐질환", "말기간질환", "말기신부전증"])]
# 연결선이 닿는 몸의 점(디자인 좌표). 키: 영역 이름 또는 항목 이름
BF_TARGET = {"뇌": (BF_CX, 236), "암": (BF_CX - 6, 560), "당뇨": (BF_CX - 83, 590), "치매": (BF_CX + 30, 214), "심장": (BF_CX + 14, 400),
             "말기폐질환": (BF_CX + 52, 372), "말기간질환": (BF_CX - 34, 468), "말기신부전증": (BF_CX + 34, 508)}


def _bf_shape(D, kind, a, b, c_, d_, fill, stroke=None, lw=2):
    cv = D.c
    cv.saveState()
    cv.setFillColor(colors.HexColor(fill))
    if stroke:
        cv.setStrokeColor(colors.HexColor(stroke))
        cv.setLineWidth(lw * D.K)
    x, y, w, h = D.X(a), D.Y(b + d_), c_ * D.K, d_ * D.K
    if kind == "ell":
        cv.ellipse(x, y, x + w, y + h, fill=1, stroke=1 if stroke else 0)
    else:
        cv.roundRect(x, y, w, h, min(w, h) / 2 * 0.9 if kind == "pill" else 14 * D.K, fill=1, stroke=1 if stroke else 0)
    cv.restoreState()


def _bf_figure(D):
    cx = BF_CX
    body, edge = "#D5DDEA", "#9FB0C8"
    for a, b, w, h in ((cx - 100, 318, 34, 290), (cx + 66, 318, 34, 290)):                  # 팔
        _bf_shape(D, "pill", a, b, w, h, body, edge)
    for a in (cx - 66, cx + 4):                                                              # 다리
        _bf_shape(D, "pill", a, 540, 62, 214, body, edge)
    _bf_shape(D, "rr", cx - 78, 296, 156, 290, body, edge)                                  # 몸통
    _bf_shape(D, "rr", cx - 16, 262, 32, 50, body, edge)                                    # 목
    _bf_shape(D, "ell", cx - 46, 192, 92, 96, body, edge)                                   # 머리
    # 장기 (진한 색으로 또렷하게)
    _bf_shape(D, "ell", cx - 30, 208, 60, 42, "#4FA3D9", "#2B6FA3", 1.5)                    # 뇌
    _bf_shape(D, "ell", cx + 10, 330, 56, 92, "#7CC6D2", "#3D8E9C", 1.5)                    # 오른 폐
    _bf_shape(D, "ell", cx - 14, 384, 38, 40, "#D9363E", "#8F1A20", 1.5)                    # 심장
    _bf_shape(D, "ell", cx - 62, 446, 70, 38, "#C98A2B", "#8A5A12", 1.5)                    # 간
    _bf_shape(D, "ell", cx - 40, 494, 24, 38, "#7E57C2", "#4A2F8A", 1.5)                    # 왼 신장
    _bf_shape(D, "ell", cx + 18, 494, 24, 38, "#7E57C2", "#4A2F8A", 1.5)                    # 오른 신장
    _bf_shape(D, "rr", cx - 40, 536, 80, 46, "#F2A65A", "#B86A1B", 1.5)                     # 장(대장)


def _draw_bodyfig(D, s):
    body = s["body"]
    _bf_figure(D)
    for side, groups in (("L", BF_LEFT), ("R", BF_RIGHT)):
        x0 = BF_LEFT_X if side == "L" else BF_RIGHT_X
        y = BF_TOP
        for gname, labs in groups:
            gh = BF_HEAD_H + BF_ROW_H * len(labs)
            D.box(x0, y, BF_COL_W, gh, fill="#FFFFFF", stroke=BF_HEAD, r=10, lw=2.5)
            D.box(x0, y, BF_COL_W, BF_HEAD_H, fill=BF_HEAD, r=10)
            D.box(x0, y + 18, BF_COL_W, BF_HEAD_H - 18, fill=BF_HEAD)
            D.text(x0 + 16, y + 26, gname, 22, "#FFFFFF", True)
            rows_y = []
            for i, lab in enumerate(labs):
                val, st = body[lab]
                ry = y + BF_HEAD_H + i * BF_ROW_H
                rows_y.append(ry + BF_ROW_H / 2)
                D.box(x0 + 5, ry + 3, BF_COL_W - 10, BF_ROW_H - 6, fill=BF_ROWBG[st], r=6)
                D.box(x0 + 5, ry + 3, 7, BF_ROW_H - 6, fill=BF_PILL[st], r=3)
                D.text(x0 + 24, ry + 28, lab, 22, BF_INK, True)
                D.box(x0 + 222, ry + 8, 74, BF_ROW_H - 16, fill=BF_PILL[st], r=13)
                D.text(x0 + 259, ry + 27, st, 19, "#FFFFFF", True, "C")
                D.text(x0 + BF_COL_W - 16, ry + 29, val, 24, BF_TEXT[st], True, "R")
            # 연결선: 영역 전체 또는 줄마다
            ex = x0 + BF_COL_W if side == "L" else x0
            if gname == "말기 장기질환":
                targets = [(rows_y[i], BF_TARGET[lab]) for i, lab in enumerate(labs)]
            else:
                targets = [(y + gh / 2, BF_TARGET[gname])]
            for sy, (tx, ty) in targets:
                D.line(ex, sy, tx, ty, "#1F2937", 2.4)
                D.box(ex - 5, sy - 5, 10, 10, fill="#1F2937", r=5)
                D.box(tx - 6, ty - 6, 12, 12, fill="#1F2937", stroke="#FFFFFF", r=6, lw=2)
            y += gh + BF_GAP
    cn = {"충분": 0, "부족": 0, "미보장": 0}
    for _g, labs_ in BODY_GROUPS:
        for lab_ in labs_:
            cn[body[lab_][1]] += 1
    xx = 880
    for st_ in ("충분", "부족", "미보장"):
        xx = D.chip(xx, 135, BF_PILL[st_], f"{st_} {cn[st_]}개")


def contract_slides(entries, ctx):
    sets = {}
    seen = {}
    for e in entries:
        if e["kind"] != "products":
            continue
        try:
            labels, _g, _s = _pick_labels(e["text"])
        except ParseError:
            continue
        key = "A" if labels is LABELS_A else "B"
        n = len(labels)
        for tb in e["page"].extract_tables():
            for row in tb:
                if len(row) < 3:
                    continue
                cell = (row[0] or "").strip()
                if not cell or "\n" not in cell or cell.startswith("보장 합계") or cell.startswith("회 사"):
                    continue
                vals = [clean(c) for c in row[1:] if c is not None and clean(c) != ""]
                lines = [l.strip() for l in cell.split("\n") if l.strip()]
                if len(vals) != n or len(lines) < 3:
                    continue
                tail = re.match(r"([\d,]+)원\s*\((.+)\)$", lines[-1])
                item = dict(company=lines[0], name="".join(lines[1:-1]),
                            premium=(tail.group(1) + "원") if tail else lines[-1],
                            expiry=tail.group(2) if tail else "", vals=vals, labels=labels)
                if _drop_product(item["name"]):
                    continue
                dk = (item["company"], re.sub(r"\s+", "", item["name"]), item["premium"], tuple(vals))
                if dk in seen.setdefault(key, set()):
                    continue  # 원본이 같은 상품표를 두 번 싣는 경우(9~14쪽, 15~20쪽) 한 번만 센다
                seen[key].add(dk)
                sets.setdefault(key, []).append(item)
    if not sets:
        return []
    for lst in sets.values():
        canonical_names(lst, ctx.get("contracts", []))

    def kk(p):
        return (p["company"], re.sub(r"\s+", "", p["name"]))
    base_key = "A" if "A" in sets else "B"
    other = {kk(p): p for p in sets.get("B" if base_key == "A" else "A", [])}
    cons = []
    for p in sets[base_key]:
        ben = [(lab, v) for lab, v in zip(p["labels"], p["vals"]) if v != "-"]
        o = other.get(kk(p))
        if o:
            ben += [(lab, v) for lab, v in zip(o["labels"], o["vals"]) if v != "-"]
        cons.append(dict(company=p["company"], name=p["name"], premium=p["premium"], expiry=p["expiry"], ben=ben))
    if len(cons) < 1:
        return []
    cons.sort(key=lambda c: -len(c["ben"]))
    best = cons[0]
    none_c = [c for c in cons if not c["ben"]]
    vmax = max(len(c["ben"]) for c in cons)
    bars = [(_wide_name(c["name"]), len(c["ben"]), (AN_C_NEED if len(c["ben"]) else AN_C_NONE), f"{len(c['ben'])}개") for c in cons]
    ins1 = [(_short_name(best["name"]), True), (f"({len(best['ben'])}개 항목)", True), (" 보장이 가장 넓음.", False)]
    ins2 = ([(f"분석 항목 보장이 없는 계약 {len(none_c)}건", False)]
            if none_c else [("모든 계약이 분석 항목을 하나 이상 보장.", False)])
    def _line_name(n):                                               # 1.61: 한 줄에 들어가게 (…)·[…] 꼬리표(중첩 포함)를 뗀다
        n = n or ""
        while True:
            m = re.sub(r"[\(\[][^\(\)\[\]]*[\)\]]", "", n)
            if m == n:
                break
            n = m
        n = re.sub(r"[\(\)\[\]]", "", n)
        n = re.sub(r"\s*,\s*", " ", n.replace("무배당", ""))
        return re.sub(r"\s+", " ", n).strip() or "(이름 없음)"
    none_lines = [_line_name(c["name"]) for c in none_c]             # 1.61: 계약 하나를 한 줄에 (그래도 길면 … 로 줄임)
    if len(none_lines) > X_INSIGHT_MAX_LINES:
        none_lines = none_lines[:X_INSIGHT_MAX_LINES - 1] + [f"외 {len(none_lines) - X_INSIGHT_MAX_LINES + 1}건"]
    chunks = [bars[i:i + X_BARS_PER_PAGE] for i in range(0, len(bars), X_BARS_PER_PAGE)][:X_MAX_PAGES]   # 1.37: 막대 10개씩 1~5쪽
    return [dict(kind="contracts", label="계약별 보장 현황" + (f" ({i + 1}/{len(chunks)})" if len(chunks) > 1 else ""),
                 headline=f"계약 {len(cons)}건 중 {len(cons) - len(none_c)}건이 분석 항목 보장",
                 sub=f"{_short_name(best['name'])}의 보장 {len(best['ben'])}개 항목으로 가장 넓음", bars=ch, vmax=vmax,
                 insight1=ins1, insight2=ins2, insight2_lines=none_lines, quotes=[]) for i, ch in enumerate(chunks)]


def age_table_slides(A):
    ages_d, order = A["ages"], A["age_order"]
    if not ages_d or not order:
        return []
    labs = [l for l in LABELS_A + LABELS_B if l in ages_d]
    vals = {l: [(_num(ages_d[l].get(a, "-")) or 0.0) for a in order] for l in labs}
    labs = [l for l in labs if any(v > 0 for v in vals[l])]
    if not labs:
        return []
    cnt = [sum(1 for l in labs if vals[l][j] > 0) for j in range(len(order))]
    dec = [0] + [sum(1 for l in labs if vals[l][j] < vals[l][j - 1]) for j in range(1, len(order))]
    first = next((order[j] for j in range(1, len(order)) if dec[j] > 0), None)
    nums = [j for j, a in enumerate(order) if a != "종신"]
    jl = nums[-1] if nums else len(order) - 1
    pick = []
    for j in ([order.index(first)] if first else []) + ([jl - 1] if jl - 1 > 0 else []) + [jl]:
        if j not in pick:
            pick.append(j)
    cards = [(f"{order[j]}", f"보장 중인 항목 {cnt[j]}개 / 전체 {len(labs)}개", f"직전보다 {dec[j]}개 항목 금액 감소") for j in pick]
    head = f"{first}부터 보장금액 감소 시작" if first else "연령이 높아져도 보장금액 동일"
    return [dict(kind="agetable", label="연령별 보장 항목 수", headline=head,
                 sub=f"{order[jl]}에는 {len(labs)}개 항목 중 {cnt[jl]}개만 유지", cats=order, vals=cnt, vmax=len(labs), cards=cards, quotes=[])]


# ---- 1.73: 가입상품 보장내역 — 빠짐없는 요약(표) ----
_PC_HANGUL = re.compile(r"[가-힣]")


def _pc_join(parts, corpus=""):
    """줄바꿈으로 갈라진 글을 잇는다. parts = [(글, 줄 끝 x, 다음 글자 폭)] 또는 글.
    원본은 글자 단위로 줄을 바꾸고 줄 끝의 띄어쓰기는 지워 버린다. 그래서 앞 줄이 칸을 꽉 채웠을 때만 판단한다:
    이어 붙인 글자(앞 줄 끝 2자+뒷 줄 첫 2자)가 같은 문서의 다른 곳에 한 줄로 나오거나, 뒷 줄 첫 말이 2자 이하(글자 한두 개가 넘친 것)이면
    글자 중간에서 바뀐 것으로 보고 붙이고, 그 밖에는 한 칸 띄운다."""
    out, prev_x1 = "", None
    for p in parts:
        t, x1, cw = (p, None, None) if isinstance(p, str) else p
        t = t.strip()
        if not t:
            continue
        if not out:
            out = t
        else:
            glue = False
            if _PC_HANGUL.fullmatch(out[-1]) and _PC_HANGUL.match(t[0]) and prev_x1 is not None and x1 is not None and (PC_COL_RIGHT - prev_x1) < 2.2 * cw:
                lastw = re.split(r"[^가-힣0-9A-Za-z]", out.split()[-1])
                lastw = next((x for x in reversed(lastw) if x), "")           # 앞 줄 마지막 말(기호 뒤 덩어리)
                a = lastw[-2:]
                w0 = re.match(r"[가-힣0-9A-Za-z]+", t.split()[0])
                w0 = w0.group(0) if w0 else ""
                b = w0[:2]
                glue = len(w0) <= 2 or len(lastw) <= 1 or (len(a + b) >= 3 and (a + b) in corpus)
            out += t if glue else " " + t
        prev_x1 = x1 if x1 is not None else prev_x1
    return out


def _pc_merge_amount_rows(items):
    """보장내역 칸이 위아래로 합쳐진 경우(조건 글 하나에 금액 줄이 여러 개)를 다시 묶는다.
    조건 글이 없는 금액만의 행은 가장 가까운 조건 행에 붙인다(같은 거리면 자기 금액이 있는 쪽, 그다음 위쪽)."""
    idx = [i for i, it in enumerate(items) if it[0] == "행"]
    anchors = [i for i in idx if items[i][1]]
    if not anchors:
        return items
    amt = {i: ([(i, items[i][2])] if items[i][2] else []) for i in idx}
    drop = set()
    for i in idx:
        if items[i][1] or not items[i][2]:
            continue
        j = min(anchors, key=lambda a: (abs(a - i), 0 if items[a][2] else 1, a))
        amt[j] = sorted(amt[j] + amt[i], key=lambda x: x[0])
        drop.add(i)
    out = []
    for i, it in enumerate(items):
        if i in drop:
            continue
        out.append((it[0], it[1], "\n".join(a for _, a in amt[i])) if it[0] == "행" and i in amt else it)
    return out


PC_COL_RIGHT = 471.0              # 보장내역 칸 오른쪽 끝(글자가 이보다 더 갈 수 없는 위치)
_PC_AMT_SPLIT = re.compile(r"\s+(?=(?:재해\d급|\d+세\s|주피보험자\s|종피보험자\s|매년\s|일시금\s|전년도))")


def _pc_amt_lines(a):
    """보장금액 칸 글을 항목별 줄로 나눈다(재해2급 …, 60세 …, 주피보험자 … 등)."""
    return [x.strip() for x in _PC_AMT_SPLIT.split(a) if x.strip()]


def parse_prodcov_page(pg):
    """가입상품 보장내역 한 쪽 → dict(name, insured, issued, by, specs[(특약명, 가입금액, 보기, 납기, 보험료)],
    groups[dict(spec, insured, name, items[(종류, 보장내역, 보장금액)])], benefits(막대용), chars_in, chars_out)
    칸 나누기는 글자 위치(x)로 한다: 보장대상 <90, 특약명 90~160, 급부명 160~238, 보장내역 238~474, 보장금액 474~."""
    text = pg.extract_text() or ""
    g = lambda p: (re.search(p, text) or [None, ""])[1]
    d = dict(name=g(r"\[상품명\]\s*(.+)").strip(), issued=g(r"\[발급일자\]\s*:\s*([\d.]+)"), by=g(r"\[발급자\]\s*:\s*(\S+)"),
             insured="", specs=[], groups=[], benefits=[], chars_in=0, chars_out=0)
    on = False
    for ln in text.splitlines():
        s = ln.strip()
        if s.startswith("특약명") and "가입금액" in s:
            on = True
            continue
        if on and s.startswith("보장대상"):
            break
        m = re.fullmatch(r"(\S+)\s+([\d,]+)\s+(\S+)\s+(\S+)\s+([\d,]+)", s) if on else None
        if m:
            d["specs"].append(m.groups())
    words = pg.extract_words()
    hdr = next((w for w in words if w["text"] == "보장대상" and w["x0"] < 99), None)
    if hdr is None:
        return d
    cut = min([w["top"] for w in words if w["text"].startswith("[발급일자]")] or [pg.height]) - 4
    body = [w for w in words if w["top"] > hdr["top"] + 8 and w["top"] < cut]
    d["chars_in"] = sum(len(w["text"]) for w in body)
    lines = []
    for w in sorted(body, key=lambda w: (w["top"], w["x0"])):
        if lines and abs(w["top"] - lines[-1]["top"]) <= 2.5:
            lines[-1]["ws"].append(w)
        else:
            lines.append(dict(top=w["top"], ws=[w]))
    corpus = "\n".join(" ".join(w["text"] for w in sorted(ln["ws"], key=lambda w: w["x0"]) if 238 <= w["x0"] < 474) for ln in lines)
    colA, colB, colC, cells, notes = [], [], [], [], []
    note_on = False
    for ln in lines:
        ws = sorted(ln["ws"], key=lambda w: w["x0"])
        if ws[0]["text"].startswith("※"):
            note_on = True
            notes.append(dict(top=ln["top"], parts=[]))
        elif note_on and any(w["x0"] < 90 for w in ws):
            note_on = False
        if note_on:
            notes[-1]["parts"].append(" ".join(w["text"] for w in ws))
            continue
        for lo, hi, store in ((0, 90, colA), (90, 160, colB), (160, 238, colC)):
            t = " ".join(w["text"] for w in ws if lo <= w["x0"] < hi)
            if t:
                store.append((ln["top"], t))
        dws = [w for w in ws if w["x0"] >= 238]
        dl = [w for w in dws if w["x0"] < 474]
        dt = " ".join(w["text"] for w in dl)
        et = " ".join(w["text"] for w in dws if w["x0"] >= 474)
        if dt or et:
            fw = dws[0]
            cells.append((min(w["top"] for w in dws), dt, et, max([w["x1"] for w in dl] or [0]),
                          ((dl[0]["x1"] - dl[0]["x0"]) / max(len(dl[0]["text"]), 1)) if dl else 0))

    def anchors(col, gap=16):
        out = []
        for top, t in col:
            if out and top - out[-1]["last"] <= gap:
                out[-1]["text"] += t
                out[-1]["last"] = top
            else:
                out.append(dict(text=t, top=top, last=top))
        return out
    specs_a, ben_a = anchors(colB), anchors(colC)
    rows, cur, last = [], None, None
    for top, dt, et, x1, cw in cells:                             # 위아래 15 이하로 붙은 줄은 한 칸(행)
        if cur is not None and top - last <= 15.5:
            cur["d"].append((dt, x1, cw))
            cur["e"].append(et)
        else:
            cur = dict(top=top, d=[(dt, x1, cw)], e=[et])
            rows.append(cur)
        last = top
    groups = []
    for b in ben_a:
        sp = [s for s in specs_a if s["top"] <= b["top"] + 8]
        ins = [t for top, t in colA if top <= b["top"] + 8]
        groups.append(dict(spec=sp[-1]["text"] if sp else None, insured=ins[-1] if ins else "", name=b["text"], top=b["top"], items=[]))
    if not groups and (rows or notes):
        groups.append(dict(spec=None, insured="", name="", top=-1, items=[]))
    entries_ = [(r["top"], "행", _pc_join(r["d"], corpus), "\n".join(_pc_amt_lines(re.sub(r"\(\s+", "(", " ".join(x for x in r["e"] if x))))) for r in rows] + \
               [(n["top"], "주", _pc_join(n["parts"], corpus), "") for n in notes]
    for top, kind, c_, a_ in sorted(entries_, key=lambda x: x[0]):
        tgt = next((gr for gr in reversed(groups) if gr["top"] <= top + 12), groups[0] if groups else None)
        if tgt is not None:
            tgt["items"].append((kind, c_, a_))
    for gr in groups:
        gr["items"] = _pc_merge_amount_rows(gr["items"])
    d["groups"] = groups
    d["insured"] = next((t for _, t in colA if re.fullmatch(r"[가-힣*]{2,5}", t)), "")
    d["chars_out"] = sum(len(re.sub(r"\s", "", x)) for x in [a["text"] for a in specs_a + ben_a] + [t for _, t in colA]
                         + [y for gr in groups for it in gr["items"] for y in it[1:]])
    for gr in groups:
        amts = [int(n.replace(",", "")) for it in gr["items"] for n in re.findall(r"\d{1,3}(?:,\d{3})+", it[2])]
        d["benefits"].append(dict(spec=gr["spec"], name=gr["name"], amts=amts, top=gr["top"]))
    return d


PC_X = dict(spec=67, spec_w=118, name=190, name_w=192, cond=390, cond_w=605, amt=1000, amt_w=378)   # 가입상품 보장내역 표의 칸(디자인 좌표)
PC_FONT_STEP = 6                  # 1.88: 가입상품 보장내역 쪽 글자 단계(0 = 처음 크기). 한 단계마다 본문 +2pt, 줄 간격 +3. 1.90: 1.92: 기준 단계 = 6
PC_UP = 2 * (PC_FONT_STEP - 1)    # 1.88: 머리글·"상품별 가입 현황" 쪽 등 다른 글자에 더하는 크기 (3단계 → +4)
PC_SIZE, PC_LEAD, PC_PAD = 15.5 + 2 * PC_FONT_STEP, 22 + 3 * PC_FONT_STEP, 7      # 4단계: 본문 23.5, 줄 간격 34
PC_Y_MAX = 742
PC_GRAPH = True      # 1.76: True = 가입상품 보장내역을 글자를 줄인 막대그래프 쪽으로, False = 전체 글을 옮긴 표 쪽(1.73~1.75)
_PCM = Deck(None)


def _pc_wrap(txt, maxw):
    """글을 칸 폭(maxw)에 맞춰 줄로 나눈다. 띄어쓰기에서 나누되, 한 말이 칸보다 길면 글자 단위로 나눈다."""
    out = []
    for para in str(txt).replace("\u00b7", "\u318d").split("\n"):          # 글꼴에 없는 가운뎃점(·)은 같은 모양의 ㆍ 로 바꿔 그린다
        cur = ""
        for tok in re.findall(r"\S+\s*", para) or [""]:
            while _PCM.width(tok.rstrip(), PC_SIZE, True) > maxw:         # 한 말이 너무 길면 글자 단위로 자른다
                k = len(tok)
                while k > 1 and _PCM.width(tok[:k].rstrip(), PC_SIZE, True) > maxw:
                    k -= 1
                if cur:
                    out.append(cur.rstrip())
                    cur = ""
                out.append(tok[:k].rstrip())
                tok = tok[k:]
            if cur and _PCM.width((cur + tok).rstrip(), PC_SIZE, True) > maxw:
                out.append(cur.rstrip())
                cur = tok
            else:
                cur += tok
        out.append(cur.rstrip())
    return out or [""]


def _pc_products(entries):
    """1.73: `가입상품 보장내역` 의 모든 글(특약표·급부·보장내역·보장금액·※ 안내)을 빠짐없이 표로 옮긴 요약 쪽. 쪽이 넘치면 다음 쪽으로 잇는다."""
    prods = []
    for e in entries:
        d = e.get("data")
        if e["kind"] != "prodcov" or not d or not d.get("name"):
            continue
        if prods and prods[-1]["name"] == d["name"] and e["n"] == prods[-1]["pages"][-1] + 1:
            p = prods[-1]
        else:
            p = dict(name=d["name"], issued=d["issued"], by=d["by"], specs=[], groups=[], pages=[], ins={}, last_spec=None)
            prods.append(p)
        p["pages"].append(e["n"])
        p["specs"] += d["specs"]
        if d["chars_in"] != d["chars_out"]:
            print(f"[주의] 가입상품 보장내역 원본 {e['n']}쪽: 읽은 글자 수가 다릅니다(원본 {d['chars_in']}자 / 읽음 {d['chars_out']}자) — 빠진 글이 없는지 확인하세요.")
        for gr in d["groups"]:
            spec = gr["spec"] or p["last_spec"]
            p["last_spec"] = spec
            if gr["insured"] and spec not in p["ins"]:
                p["ins"][spec] = gr["insured"]
            if p["groups"] and p["groups"][-1]["spec"] == spec and p["groups"][-1]["name"] == gr["name"]:
                p["groups"][-1]["items"] += gr["items"]                 # 쪽을 넘어 이어진 같은 급부는 하나로
            else:
                p["groups"].append(dict(spec=spec, name=gr["name"], items=list(gr["items"])))
    return prods


def prodcov_detail_slides(entries, noamt=False):
    """1.73: `가입상품 보장내역` 의 모든 글(특약표·급부·보장내역·보장금액)을 빠짐없이 표로 옮긴 요약 쪽. 쪽이 넘치면 다음 쪽으로 잇는다.
    1.74: 보장금액이 하나도 없는 급부(납입면제·안내사항 등)와 ※ 안내문은 이 표에서 빼고, noamt=True 로 부르면 그 내용만 모아 따로 요약한다(맨 마지막 쪽)."""
    prods = _pc_products(entries)
    slides = []
    for p in prods:
        if not p["groups"]:
            continue
        blocks = []                                                     # (특약명, 급부명, [(종류, 보장내역, 보장금액)])
        for gr in p["groups"]:
            has_amt = any(a_ for kind, c_, a_ in gr["items"] if kind == "행")
            if not noamt:
                its = [it for it in gr["items"] if has_amt and it[0] == "행"]
                if its:
                    blocks.append((gr["spec"], gr["name"], its))
            elif not has_amt:
                blocks.append((gr["spec"], gr["name"], [("안", c_, "") for _k, c_, _a in gr["items"]]))
            else:
                notes = [("안", c_, "") for k, c_, _a in gr["items"] if k == "주"]
                if notes:
                    blocks.append((gr["spec"], gr["name"] + " (※ 안내)", notes))
        rows, prev_spec = [], None
        for spec, bname, its in blocks:
            first = True
            ins = p["ins"].get(spec, "")
            for kind, c_, a_ in its:
                if kind in ("주", "안"):
                    cl, al = _pc_wrap(c_, PC_X["cond_w"] + PC_X["amt_w"] - 20), []
                else:
                    cl, al = _pc_wrap(c_, PC_X["cond_w"] - 20), (_pc_wrap(a_, PC_X["amt_w"] - 24) if a_ else [])
                sp_txt = (f"{spec}" + (f" ({ins})" if ins else "")) if (first and spec != prev_spec) else ""
                bn = _pc_wrap(bname, PC_X["name_w"] - 12) if first else []
                nl = max(len(cl), len(al), len(bn), len(_pc_wrap(sp_txt, PC_X["spec_w"] - 10)) if sp_txt else 0, 1)
                rows.append(dict(gname=bname, gspec=spec, kind=kind, spec=sp_txt,
                                 bname=bn, cond=cl, amt=al, h=nl * PC_LEAD + 2 * PC_PAD,
                                 gstart=first, nums=re.findall(r"\d{1,3}(?:,\d{3})+", a_)))
                first = False
            prev_spec = spec
        if not rows:
            continue
        spec_rows = [list(sp) for sp in p["specs"]] if not noamt else []
        tot = sum(int(sp[4].replace(",", "")) for sp in p["specs"])
        pages, cur = [], []
        y = (196 + 34 + 34 * len(spec_rows) + 46 + 34) if spec_rows else 230      # 첫 쪽: 특약표 아래 표 머리글 줄 다음부터
        # 1.75: 급부(항목) 단위로 쪽을 나눈다. 한 급부가 현재 쪽 남은 자리에 다 안 들어가도 '새 쪽 한 장'에는 들어가면 통째로 다음 쪽으로 넘기고,
        #       한 쪽보다 큰 급부만 쪽을 이어 쓰되 처음 두 줄은 같은 쪽에 남긴다. 작은 급부 두세 개는 한 쪽에 모아 담는다.
        full_cap = PC_Y_MAX - (196 + 34)
        groups_rows, gi = [], None
        for r in rows:
            if r["gstart"] or gi is None:
                groups_rows.append([])
            groups_rows[-1].append(r)
            gi = True
        for grp in groups_rows:
            gh = sum(r["h"] for r in grp)
            room = PC_Y_MAX - y
            if cur and gh > room:
                if gh <= full_cap or room < sum(r["h"] for r in grp[:2]):   # 새 쪽에 통째로 들어가거나, 앞 두 줄도 못 담으면 다음 쪽부터
                    pages.append(cur)
                    cur, y = [], 196 + 34
            for r in grp:                                                   # 한 쪽보다 큰 급부는 줄 단위로 이어 쓴다
                if cur and y + r["h"] > PC_Y_MAX:
                    pages.append(cur)
                    cur, y = [], 196 + 34
                cur.append(r)
                y += r["h"]
        pages.append(cur)
        for pr in pages[1:]:                                            # 쪽이 바뀌어 급부 중간에서 시작하면 급부명 뒤에 (계속) 표시
            r0 = pr[0]
            if not r0["gstart"]:
                r0["bname"] = _pc_wrap(r0["gname"] + " (계속)", PC_X["name_w"] - 12)
                r0["cont"] = True
        short = _short_name(p["name"])
        who = p["ins"].get(p["groups"][0]["spec"], "") or next(iter(p["ins"].values()), "")
        for pi, pr in enumerate(pages):
            nums = [n for r in pr for n in r["nums"]]
            quotes = list(dict.fromkeys(nums))
            if pi == 0 and not noamt:
                quotes += [sp[4] for sp in p["specs"]] + [f"{tot:,}"]
            lab = "금액 없는 항목 요약" if noamt else "가입상품 보장내역"
            head = (f"금액이 없는 항목 요약 ({len(rows)}건)" if pi == 0 else "금액이 없는 항목 요약 (계속)") if noamt else \
                   (f"{short} 보장내역 전체 요약" if pi == 0 else f"{short} 보장내역 (계속)")
            slides.append(dict(kind="pcnoamt" if noamt else "pcdetail", noamt=noamt, fs_up=PC_UP, label=f"{short} / {lab}" + (f" ({pi + 1}/{len(pages)})" if len(pages) > 1 else ""),
                               headline=head, sub=(f"{who}님 / " if who else "") + f"발급 {p['issued']}" + (f" / 발급자 {p['by']}" if p["by"] else ""),
                               rows=pr, specs=spec_rows if pi == 0 else [], total=tot, first=(pi == 0), quotes=quotes))
    return slides


def _draw_pcdetail(D, s):
    x0, x1 = PC_X["spec"], PC_X["amt"] + PC_X["amt_w"]
    y = 196
    ink, gray, line_c = "#0A0A0A", "#4B5563", "#D5DAE2"
    if s["first"] and s["specs"]:
        cols = [(x0, "특약명", "L"), (x0 + 330, "가입금액(원)", "R"), (x0 + 490, "보기", "R"), (x0 + 640, "납기", "R"), (x1 - 14, "보험료(원)", "R")]
        D.box(x0, y, x1 - x0, 34, fill=BF_HEAD, r=6)
        for cx, t, al in cols:
            D.text(cx + (12 if al == "L" else 0), y + 24, t, PC_SIZE, "#FFFFFF", True, al)
        y += 34
        for i, sp in enumerate(s["specs"]):
            D.box(x0, y, x1 - x0, 34, fill="#F3F5F9" if i % 2 == 0 else "#FFFFFF")
            vals = [sp[0], sp[1], sp[2], sp[3], sp[4]]
            for (cx, _t, al), v in zip(cols, vals):
                D.text(cx + (12 if al == "L" else 0), y + 24, v, PC_SIZE, ink, True, al)
            y += 34
        D.line(x0, y + 1, x1, y + 1, "#1F3F7A", 2)
        D.text(x0 + 12, y + 26, "월 보험료 합계", PC_SIZE, ink, True)
        D.text(x1 - 14, y + 26, f"{s['total']:,}", PC_SIZE + 2, "#A80F0F", True, "R")
        y += 46
    D.box(x0, y, x1 - x0, 34, fill=BF_HEAD, r=6)
    for cx, t in ((PC_X["spec"] + 12, "특약명"), (PC_X["name"] + 6, "급부명"), (PC_X["cond"] + 6, "보장내역")):
        D.text(cx, y + 24, t, PC_SIZE, "#FFFFFF", True)
    if not s.get("noamt"):
        D.text(PC_X["amt"] + PC_X["amt_w"] - 14, y + 24, "보장금액", PC_SIZE, "#FFFFFF", True, "R")
    y += 34
    for r in s["rows"]:
        h = r["h"]
        if r["gstart"]:
            D.line(x0, y, x1, y, "#9CA3AF", 1.4)
        else:
            D.line(PC_X["cond"], y, x1, y, line_c, 1)
        if r["kind"] == "주":
            D.box(x0, y + 1, x1 - x0, h - 1, fill="#FFF8E7")
        ty = y + PC_PAD + 16
        for i, t in enumerate(r["bname"]):
            D.text(PC_X["name"] + 6, ty + i * PC_LEAD, t, PC_SIZE, gray if r.get("cont") else ink, True)
        if r["spec"]:
            for i, t in enumerate(_pc_wrap(r["spec"], PC_X["spec_w"] - 10)):
                D.text(PC_X["spec"] + 6, ty + i * PC_LEAD, t, PC_SIZE, gray, True)
        for i, t in enumerate(r["cond"]):
            D.text(PC_X["cond"] + 6, ty + i * PC_LEAD, t, PC_SIZE, ink, True)
        for i, t in enumerate(r["amt"]):
            D.text(PC_X["amt"] + PC_X["amt_w"] - 10, ty + i * PC_LEAD, t, PC_SIZE, "#A80F0F", True, "R")
        y += h
    D.line(x0, y, x1, y, "#9CA3AF", 1.4)

_PC_MONEY = re.compile(r"(\d{1,3}(?:,\d{3})+|\d+)\s*원")


def _pc_man(n):
    """원 → 짧은 금액 글(500만, 1.5만, 1억)"""
    if n >= 100000000 and n % 100000000 == 0:
        return f"{n // 100000000:,}억"
    if n >= 10000:
        v = n / 10000
        return f"{v:,.0f}만" if v == int(v) else f"{v:,.1f}만"
    return f"{n:,}원"


def _pc_short_amt(t):
    """금액 글을 짧게: '매년 5,000,000원 × 10년지급' → '매년 500만 × 10년'"""
    t = re.sub(r"\s+", " ", t.replace("\n", " ")).strip().strip(")").strip()
    t = _PC_MONEY.sub(lambda m: _pc_man(int(m.group(1).replace(",", ""))), t)
    t = t.replace("지급", "").replace("＋", "+").replace("연금개시전까지", "").replace("  ", " ")
    return re.sub(r"\s*×\s*", " × ", t).strip()


def _pc_label(prev, c, a_line):
    """급부 안의 한 항목을 짧은 이름으로 줄인다(긴 문장 → 핵심 낱말). 규칙에 안 맞으면 앞 14자."""
    t = re.sub(r"\s+", "", " ".join(prev + [c]))
    cc = re.sub(r"\s+", "", c)
    who = "주피 " if cc.startswith("주피보험자") else ("종피 " if cc.startswith("종피보험자") else "")
    m = re.search(r"기준:(.+)$", cc)
    if m:
        return ("일반사망 " if "재해이외의원인으로사망" in t else "사망 ") + m.group(1)
    m = re.fullmatch(r"(재해)?제(\d)급의?장해상태시", cc)
    if m:
        return (("재해 " if m.group(1) else "") + f"{m.group(2)}급 장해")
    m = re.match(r"^(재해)?(\d)급", a_line.replace(" ", ""))
    if m and not a_line.startswith("매"):
        return who + (("재해 " if m.group(1) else "") + f"{m.group(2)}급 장해")
    if "2년이내" in cc and "단" in cc:
        return "2년 이내 감액"
    if "교통재해이외" in t:
        return "교통 외 재해 사망"
    if "교통재해" in t:
        return "교통재해 " + ("입원" if "입원" in t else "사망")
    if "특정암이외" in t:
        return "특정암 외 암 사망"
    if "특정암" in t:
        return "특정암 사망"
    if "제1급" in cc and "사망" in cc:
        return ("암 " if "암을" in cc else ("암 외 " if "암이외" in cc else "")) + "사망·1급 장해"
    m = re.search(r"(\d+)세이후", cc)
    if m:
        return f"{m.group(1)}세 이후 생존"
    if "2인모두생존" in cc:
        return "2인 모두 생존"
    if "1인만생존" in cc:
        return "1인만 생존"
    m = re.search(r"매(\d+)년마다", cc)
    if m:
        return f"{m.group(1)}년마다 생존"
    if "입원" in cc:
        return "입원 1일당" if "1일당" in t else "입원"
    if "생존" in cc:
        return "생존시"
    if "사망" in cc:
        return "사망시"
    cl = re.sub(r"^[\-■\s]+", "", c).strip()
    return cl[:14] + ("…" if len(cl) > 14 else "")


def _pc_graph_groups(p):
    """상품 하나의 급부별 막대 목록 → [dict(name, spec, bars[(이름, 값(원), 글, 원본숫자들)])] (금액 있는 급부만)"""
    out = []
    for gr in p["groups"]:
        bars, prev, hdr_ctx, last_amt = [], [], [], False
        for kind, c_, a_ in gr["items"]:
            if kind != "행":
                continue
            if not a_:
                if last_amt:                                  # 금액 없는 줄이 새로 시작되면 새 머리 설명 묶음
                    hdr_ctx, last_amt = [], False
                prev.append(c_)
                hdr_ctx.append(c_)
                continue
            last_amt = True
            lines, buf = [], ""
            for ln in _pc_amt_lines(a_):
                buf = (buf + " " + ln).strip()
                if not buf.endswith(("＋", "+")):
                    lines.append(buf)
                    buf = ""
            if buf:
                lines.append(buf)
            for ln in lines:
                nums = _PC_MONEY.findall(ln)
                if not nums:
                    continue
                val = int(nums[0].replace(",", ""))
                multi = len(lines) > 1
                if multi:                                    # 금액 칸에 항목이 여러 줄(재해2급 …, 60세 … 등)
                    head = re.split(r"\s*\d[\d,]*\s*원", ln)[0].strip()
                    tail = re.search(r"\(([^)]+)\)", ln)
                    lab = (head + (f" ({tail.group(1)})" if tail else "")).strip() or _pc_label(prev, c_, ln)
                    if head.startswith(("재해", "주피", "종피")) or re.match(r"\d+세$", head):
                        lab = _pc_label([], c_, ln) if re.match(r"^(재해)?\d급", head) else lab
                    if re.match(r"^재해\d급", head):
                        lab = ("주피 " if c_.startswith("주피") else "종피 " if c_.startswith("종피") else "") + re.sub(r"재해(\d)급", r"재해 \1급 장해", head)
                else:
                    lab = _pc_label(prev, c_, ln)
                lab = re.sub(r"\s+", " ", lab)
                ctx_txt = re.sub(r"\s+", "", " ".join(hdr_ctx + [c_]))                       # 1.83/1.85: 중요한 문구(연금개시전·연금개시후)는 항목 이름에 반드시 넣는다
                for ph in sorted((x for x in PC_KEY_PHRASES if x in ctx_txt and x not in lab), key=ctx_txt.find, reverse=True):
                    lab = ph + " " + lab
                if lab.startswith(("주피보험자", "종피보험자")):
                    lab = lab[:2] + lab[5:]
                bars.append((lab, val, (re.sub(r"\s*\([^)]*\)\s*$", "", _pc_short_amt(re.sub(r"^(?:재해\d급|\d+세|주피보험자|종피보험자)\s*", "", ln))) if multi and not ln.startswith("일시금") else _pc_short_amt(ln)), [n for n in nums]))
            if not re.match(r"^\s*[-→]", c_):                # 이어지는 줄(-…, →…)은 앞 설명을 이어 쓴다
                prev = []
        if bars:
            out.append(dict(name=gr["name"], spec=gr["spec"], bars=bars))
    return out


_PCS = PC_FONT_STEP - 3          # 1.90: 3단계(1.88 기준)에서 몇 단계 벗어났는지 — 막대 쪽 치수를 이 값으로 계산한다
PC_GR = dict(x0=727.5 - (1100 + 60 * _PCS) / 2, colw=1100 + 60 * _PCS, gap=31, top=196, bot=742, hdr=46 + 2 * _PCS, row=45 + 3 * _PCS, pad=14,
             hty=33 + 2 * _PCS, ty=31 + 2 * _PCS, bar_x=385 + 35 * _PCS, bar_w=300 - 20 * _PCS)


PC_KEY_PHRASES = ("연금개시전", "연금개시후")                                                              # 항목 이름에 빠지면 안 되는 문구
PC_BAR_COLORS = ["#8FB8E8", "#F0A98C", "#92D0A8", "#E8C26A", "#E59BB5", "#8ED0D0", "#B7C98A"]   # 진하지 않은 항목별 막대 색(앞에서부터 쓰고 모자라면 돌려 쓴다)
PC_HEAD_FILL, PC_HEAD_INK, PC_HEAD_SUB = "#C7B8F2", "#2F2466", "#4C3C99"                        # 급부 머리글: 밝은 보라 바탕 + 진한 보라 글자


def _pc_cat(lab, gname):
    """막대 색을 나누는 항목 이름: 교통 / 특정암 / 연령별 사망 / 주피·종피, 그 밖에는 급부 하나가 한 색."""
    lab = re.sub(r"^(?:연금개시[전후]\s*)+", "", lab)
    if "교통" in lab:
        return "교통"
    if "특정암" in lab:
        return "특정암"
    if re.match(r"^(일반사망|사망 )", lab):
        return "연령사망"
    if lab.startswith(("주피", "종피")):
        return lab[:2]
    return "G:" + gname


def prodcov_graph_slides(entries):
    """1.76: 가입상품 보장내역을 글자를 줄인 막대그래프 쪽으로 만든다. 급부 하나는 한 덩어리(머리글+막대)이고,
    덩어리가 단 끝에 걸리면 통째로 다음 단·다음 쪽으로 넘긴다(1.75 와 같은 기준). 한 쪽(2단)을 넘는 급부만 이어 쓴다."""
    slides = []
    G = PC_GR
    for p in _pc_products(entries):
        groups = _pc_graph_groups(p)
        if not groups:
            continue
        cap = G["bot"] - G["top"]
        max_rows = (cap - G["hdr"] - G["pad"]) // G["row"]
        blocks, cat_col = [], {}
        for g in groups:
            chunks = [g["bars"][i:i + max_rows] for i in range(0, len(g["bars"]), max_rows)]
            for ci, ch in enumerate(chunks):
                cols = []
                for b_ in ch:
                    cat = _pc_cat(b_[0], g["name"])
                    cat_col.setdefault(cat, PC_BAR_COLORS[len(cat_col) % len(PC_BAR_COLORS)])
                    cols.append(cat_col[cat])
                blocks.append(dict(name=g["name"] + (" (계속)" if ci else ""), spec=g["spec"] if g["spec"] != "주계약" else "", bars=ch, colors=cols,
                                   h=G["hdr"] + len(ch) * G["row"] + G["pad"]))
        pages, cur, ys = [], [], [G["top"], G["top"]]
        for b in blocks:
            c = 0 if ys[0] + b["h"] <= G["bot"] else None                          # 1.77: 한 쪽에 한 단. 안 들어가면 통째로 다음 쪽
            if c is None:
                pages.append(cur)
                cur, ys, c = [], [G["top"], G["top"]], 0
            b["col"], b["y"] = c, ys[c]
            cur.append(b)
            ys[c] += b["h"]
        pages.append(cur)
        short = _short_name(p["name"])
        who = p["ins"].get(p["groups"][0]["spec"], "") or next(iter(p["ins"].values()), "")
        for pi, pb in enumerate(pages):
            slides.append(dict(kind="pcgraph", fs_up=PC_UP, label=f"{short} / 가입상품 보장내역" + (f" ({pi + 1}/{len(pages)})" if len(pages) > 1 else ""),
                               headline="보장금액 한눈에 보기" + ("" if pi == 0 else " (계속)"), head_center=True,
                               sub=(f"{who}님 / " if who else "") + f"발급 {p['issued']}" + (f" / 발급자 {p['by']}" if p["by"] else ""),
                               blocks=pb, quotes=[]))                      # 화면 금액은 '만' 단위로 줄여 쓰므로 원문 대조 대신 아래에서 숫자 누락을 직접 확인
        want = sorted(n for gr in p["groups"] if any(k == "행" and a_ for k, _c, a_ in gr["items"]) for k, _c, a_ in gr["items"] if k == "행" for n in _PC_MONEY.findall(a_))
        have = sorted(n for g in groups for _l, _v, _t, ns in g["bars"] for n in ns)
        if want != have:
            print(f"[주의] 보장내역 그래프: 원본 금액 {len(want)}개 중 {len(have)}개만 막대에 들어갔습니다({p['name']}).")
    return slides


def prodcov_main_slides(entries):
    return prodcov_graph_slides(entries) if PC_GRAPH else prodcov_detail_slides(entries)


def _draw_pcgraph(D, s):
    G = PC_GR
    ink, gray = "#0A0A0A", "#4B5563"
    for b in s["blocks"]:
        x = G["x0"] + b["col"] * (G["colw"] + G["gap"])
        y = b["y"]
        D.box(x, y, G["colw"], G["hdr"], fill=PC_HEAD_FILL, r=6)
        D.text(x + 26, y + G["hty"], b["name"], PC_SIZE + 2, PC_HEAD_INK, True)
        if b["spec"]:
            D.text(x + G["colw"] - 26, y + G["hty"], b["spec"], PC_SIZE, PC_HEAD_SUB, True, "R")
        y += G["hdr"]
        vmax = max(v for _l, v, _t, _n in b["bars"]) or 1
        lab_w, bar_x, bar_w = 190, x + G["bar_x"], G["bar_w"]
        for i, (lab, v, txt, _n) in enumerate(b["bars"]):
            if i % 2 == 0:
                D.box(x, y, G["colw"], G["row"], fill="#F3F5F9")
            ty = y + G["ty"]
            D.text(x + 26, ty, lab, PC_SIZE, ink, True)
            bw = max(6, bar_w * v / vmax)
            bw = max(6, min(bw, x + G["colw"] - 26 - (bar_x + 10) - D.width(txt, PC_SIZE, True)))
            D.box(bar_x, y + 10, bw, G["row"] - 20, fill=b["colors"][i], r=3)
            D.text(bar_x + bw + 10, ty, txt, PC_SIZE, "#A80F0F", True)
            y += G["row"]
        D.line(x, y + 4, x + G["colw"], y + 4, "#9CA3AF", 1.2)
    D.text(G["x0"] + 26, 764, "막대는 급부 안에서 가장 큰 금액을 기준으로 한 길이. 금액 단위 원(만 = 만원).", PC_SIZE - 3, gray)   # 보조 설명 글자


def prodcov_slides(entries):
    """1.72: `가입상품 보장내역` 쪽(상품 하나가 여러 쪽에 이어질 수 있음)을 상품별 가입 현황 쪽(막대 + 카드 3개)으로 만든다.
    막대 = 급부별 가장 큰 보장금액(원 → 만원 단위 막대), 카드 = 특약 수 / 보험 기간 / 월납입보험료."""
    prods = []
    for e in entries:
        d = e.get("data")
        if e["kind"] != "prodcov" or not d or not d.get("name"):
            continue
        if prods and prods[-1]["name"] == d["name"] and e["n"] == prods[-1]["pages"][-1] + 1:
            p = prods[-1]
        else:
            p = dict(name=d["name"], insured=d["insured"], issued=d["issued"], by=d["by"], specs=[], bens=[], pages=[], last_spec=None)
            prods.append(p)
        p["pages"].append(e["n"])
        p["specs"] += d["specs"]
        for b in d["benefits"]:
            b = dict(b)
            if b["spec"] is None:
                b["spec"] = p["last_spec"]
            p["last_spec"] = b["spec"]
            p["bens"].append(b)
    slides = []
    for p in prods:
        if not p["specs"] or not any(b["amts"] for b in p["bens"]):
            print(f"[주의] 분석: 가입상품 보장내역 {p['name']} (원본 {p['pages'][0]}쪽)의 특약·보장금액을 읽지 못해 슬라이드를 넣지 않았습니다.")
            continue
        prem = sum(int(sp[4].replace(",", "")) for sp in p["specs"])
        main = next((sp for sp in p["specs"] if sp[0] == "주계약"), p["specs"][0])
        life = main[2] == "종신"
        extras = [sp for sp in p["specs"] if sp is not main]
        terms = [int(re.sub(r"\D", "", sp[2])) for sp in p["specs"] if re.sub(r"\D", "", sp[2])]
        if life:
            head_end, e2 = "이 계약의 보장은 종신까지 이어져요", "종신"
        else:
            e2 = f"{max(terms)}년" if terms else main[2]
            head_end = f"이 계약의 보장은 {e2} 동안 이어져요"
        sub2 = " / ".join(f"{sp[0]} {sp[2]}" for sp in extras) if extras else f"납기 {main[3]}"
        best = {}
        for b in p["bens"]:
            if b["amts"] and (b["name"] not in best or max(b["amts"]) > best[b["name"]]):
                best[b["name"]] = max(b["amts"])
        items = sorted(best.items(), key=lambda kv: -kv[1])
        shown_all = items[:X_BARS_PER_PAGE * X_MAX_PAGES]
        note = (f"외 {len(items) - len(shown_all)}개 급부는 금액이 작아 생략. " if len(items) > len(shown_all) else "") + \
               "막대는 급부별로 가장 큰 보장금액(일당 급부는 1일 금액)."
        def man(a):
            return f"{a // 10000:,}" if a % 10000 == 0 else f"{a:,}원"
        bars_all = [(lab, a / 10000.0, PC_BAR_COLORS[i % len(PC_BAR_COLORS)], man(a)) for i, (lab, a) in enumerate(shown_all)]    # 1.82: 막대마다 연한 색
        pgs = [bars_all[i:i + X_BARS_PER_PAGE] for i in range(0, len(bars_all), X_BARS_PER_PAGE)] or [[]]
        cards = [("특약", f"주계약 + 특약 {len(extras)}개" if extras else "주계약 1개", f"급부 {len(items)}개"),
                 ("보험 기간", e2, sub2),
                 ("월납입보험료", f"{prem:,}원", f"납기 {main[3]}")]
        who = f"{p['insured']}님 / " if p["insured"] else ""
        for pi, bars in enumerate(pgs):
            slides.append(dict(kind="other", fs_up=PC_UP, label=f"{_short_name(p['name'])} / 상품별 가입 현황" + (f" ({pi + 1}/{len(pgs)})" if len(pgs) > 1 else ""),
                               headline=head_end, sub=f"{who}발급 {p['issued']}" + (f" / 발급자 {p['by']}" if p["by"] else ""),
                               bars=bars, cards=cards, note=note.strip(),
                               quotes=[f"{prem:,}원", e2]))
    return slides


def other_slides(entries):
    cons = []
    for e in entries:
        t = e["text"]
        if "타사 상품별 가입 현황" not in t.split("\n")[0]:
            continue
        m = re.search(r"\n(\S+)\s+조회시점\s*:\s*(\d{4}-\d{2}-\d{2}\s+[\d:]+)\n(.+)\n", t)
        if m and _drop_product(m.group(3)):
            cons.append(dict(company=m.group(1), name=m.group(3).strip(), drop=True, rows=[], pages=[e["n"]]))   # 1.41: 이어지는 쪽도 함께 건너뛰기 위해 표시만 남김
            continue
        if not m and cons and cons[-1].get("drop"):
            continue
        if m:
            def g(p):
                mm = re.search(p, t)
                return mm.group(1) if mm else ""
            cur = dict(company=m.group(1), at=m.group(2), name=m.group(3).strip(), start=g(r"가입일자\s*\|\s*(\S+)"),
                       age=g(r"만기연령\s*\|\s*(\S+)"), term=g(r"납입기간\s*\|\s*(\S+)"), prem=g(r"\n([\d,]+)\n가입일자"), rows=[], pages=[])
            cons.append(cur)
        elif cons:
            cur = cons[-1]
        else:
            continue
        cur["pages"].append(e["n"])
        for tb in e["page"].extract_tables():
            for r in tb:
                if len(r) >= 8 and re.fullmatch(r"\d+", (r[0] or "").strip()):
                    cur["rows"].append([clean(c) for c in r[:8]])
    slides = []
    no_body = []                                                  # 1.54: 보장내용이 없어 쪽을 만들지 않은 계약
    for c in cons:
        if c.get("drop"):
            continue
        specs, last = [], None
        for r in c["rows"]:
            _no, tk, _bj, _amt, item, iamt, st, en = r
            if tk:
                last = dict(name=tk, items=[])
                specs.append(last)
            if last is not None and item and _num(iamt):
                last["items"].append((item, int(_num(iamt)), en))
        if not any(sp["items"] for sp in specs):                  # 1.54: 분석 보장항목에 연결된 보장금액이 하나도 없으면 쪽을 만들지 않는다(내용 없음)
            no_body.append(c["name"])
            continue
        ends = sorted(r[7] for r in c["rows"] if re.fullmatch(r"\d{4}\.\d{2}\.\d{2}", r[7]))
        life = any(r[7] == "종신" for r in c["rows"])
        if not ends and not life:
            print(f"[주의] 분석: 타사 가입 현황 {c['name']} (원본 {c['pages'][0]}쪽)의 보장종료를 읽지 못해 슬라이드를 넣지 않았습니다.")
            continue
        if life:
            e2 = "종신"
            e1 = ends[0] if ends else "종신"
            if ends:
                span = f"{int(ends[0][:4])}년부터 종신"
                head_end = f"이 계약의 보장은 {span}까지 이어져요"
            else:
                span = "종신"
                head_end = "이 계약의 보장은 종신까지 이어져요"
        else:
            e1, e2 = ends[0], ends[-1]
            y1, y2 = int(e1[:4]), int(e2[:4])
            span = f"{y1}년" if y1 == y2 else f"{y1}~{y2}년"
            head_end = f"이 계약의 보장은 {span}에 끝나요"
        best = {}
        for sp in specs:
            for lab, amt, en in sp["items"]:
                if lab not in best or amt > best[lab][0]:
                    best[lab] = (amt, en)
        items = sorted(best.items(), key=lambda kv: -kv[1][0])
        unlinked = sum(1 for sp in specs if not sp["items"])
        renew = sum(1 for sp in specs if sp["name"].startswith("[갱신형]"))
        shown_all = items[:X_BARS_PER_PAGE * X_MAX_PAGES]
        shown = shown_all
        note = (f"분석 보장항목에 연결되지 않은 특약 {unlinked}개는 막대에서 제외. " if unlinked else "") + \
               (f"외 {len(items) - len(shown_all)}개 항목은 금액이 작아 생략." if len(items) > len(shown_all) else "")
        def man(a):
            return f"{a // 10000:,}" if a % 10000 == 0 else f"{a:,}원"
        bars_all = [(lab, a / 10000.0, AN_C_NEED, man(a)) for lab, (a, en) in shown_all]
        pgs = [bars_all[i:i + X_BARS_PER_PAGE] for i in range(0, len(bars_all), X_BARS_PER_PAGE)] or [[]]
        cards = [("특약", f"{len(specs)}개 (갱신형 {renew}개)", f"분석 항목에 연결된 특약 {len(specs) - unlinked}개"),
                 ("보장 종료", e2, f"가장 빠른 종료 {e1}" if e1 != e2 else f"가입 {c['start']}"),
                 ("월납입보험료", f"{c['prem']}원", f"만기연령 {c['age']} / 납입 {c['term']}")]
        for pi, bars in enumerate(pgs):
            slides.append(dict(kind="other", label=f"{_short_name(c['name'])} / 타사 가입 현황" + (f" ({pi + 1}/{len(pgs)})" if len(pgs) > 1 else ""),
                               headline=head_end,
                               sub=f"{c['company']} / 가입 {c['start']} / 조회시점 {c['at']}", bars=bars, cards=cards, note=note.strip(),
                               quotes=[c["start"], e2, c["prem"] + "원"] + ([e1] if e1 != e2 else [])))
    if no_body:
        print(f"[안내] 타사 가입 현황: 분석 보장항목에 연결된 보장내용이 없는 계약 {len(no_body)}건은 쪽을 만들지 않았습니다 — " + ", ".join(_short_name(n) for n in no_body))
    return slides


def proposal_slide(entries):
    e = next((x for x in entries if "컨설팅 제안 전" in x["text"]), None)
    if not e:
        return None
    t = e["text"]
    heads = re.findall(r"가입건수\s*(\d+)건\s*월보험료\s*([\d,]+)원", t)
    sts = re.findall(r"충분\s*(\d+)개\s*부족\s*(\d+)개\s*미보장\s*(\d+)개", t)
    ch = re.search(r"신규 상품\s*(\d+)건,\s*계약 변경\s*(\d+)건,\s*상품 제외\s*(\d+)건,\s*계약 유지\s*(\d+)건", t)
    dl = re.search(r"\(\s*([+-]?\d+)건,\s*([+-]?[\d,]+)원\s*\)", t)
    tot = re.search(r"분석항목\s*(\d+)개", t)
    if len(heads) < 2 or len(sts) < 2 or not ch:
        print("[주의] 분석: 보장 제안(전/후 비교)을 읽지 못해 슬라이드를 넣지 않았습니다.")
        return None
    new, chg, out, keep = ch.groups()
    same = int(new) + int(chg) + int(out) == 0
    head = f"제안 전후 변경 없이 계약 {keep}건 유지" if same else f"제안: 신규 {new}건, 변경 {chg}건, 제외 {out}건"
    sub = (f"가입 건수 {dl.group(1)}건, 월보험료 {dl.group(2)}원 변화" if dl else "컨설팅 제안 전과 후를 같은 기준으로 비교")
    ins = [(f"신규 {new}건 / 변경 {chg}건 / 제외 {out}건 / 유지 {keep}건", True)]
    ins2 = [(f"제안 전 가입 {heads[0][0]}건, 월보험료 {heads[0][1]}원. 제안 후 가입 {heads[1][0]}건, 월보험료 {heads[1][1]}원.", False)]
    return dict(kind="proposal", label="보장 제안 전/후 비교", headline=head, sub=sub, cats=["충분", "부족", "미보장"],
                before=[int(x) for x in sts[0]], after=[int(x) for x in sts[1]], insight1=ins, insight2=ins2,
                insight1_lines=[f"신규 {new}건", f"변경 {chg}건", f"제외 {out}건", f"유지 {keep}건"],     # 1.62: 한 항목 한 줄
                insight2_lines=[f"제안 전 가입 {heads[0][0]}건", f"월보험료 {heads[0][1]}원", f"제안 후 가입 {heads[1][0]}건", f"월보험료 {heads[1][1]}원"],
                note=("보험계약 변경사항 표 없음." if same else ""),
                quotes=[heads[0][1] + "원", heads[1][1] + "원"])


X_BARS_PER_PAGE = 10                           # 막대 그래프 쪽: 한 쪽에 넣는 막대 수(넘으면 1~5쪽으로 나눔)
X_MAX_PAGES = 5
ENROLL_SHOW_EXCLUDED = False                         # 1.42: 내용이 없는 계약은 건수에만 넣고 목록·안내에는 쓰지 않는다
DROP_PRODUCT_RE = re.compile(r"자동차보험")          # 1.41: 분석 PDF 가입 현황에서 뺄 상품(개인용자동차보험 등). 원본 숫자(유지 N건 등)는 그대로 둔다.


def _drop_product(name):
    return bool(DROP_PRODUCT_RE.search(re.sub(r"\s+", "", name or "")))


ENROLL_PER_PAGE = 8                           # 2쪽 표: 한 쪽에 넣는 줄 수(넘으면 보험사 묶음 단위로 나눠 최대 5쪽)
ENROLL_MAX_PAGES = 5


def enroll_slide(entries):
    """분석 PDF 2쪽: 계약 및 납입 현황(원본 2쪽). 왼쪽 계약 목록(큰 글자) + 오른쪽 카드 2개와 보험사별 월 보험료 막대."""
    es_ = [x for x in entries if x["kind"] == "enrollment" and x["mode"] == "전용"]
    if not es_:
        return []
    # 1.38: 보험 가입 현황은 여러 쪽(우성래: 4~5쪽)에 이어진다. 첫 쪽의 요약 줄(유지계약 N건 등)은 그대로 쓰고 계약 목록은 모든 쪽을 합친다.
    data_ = dict(info=es_[0]["data"]["info"], contracts=[c for x in es_ for c in x["data"]["contracts"] if not _drop_product(c["name"])])
    m = enrollment_model(data_)
    rows = []
    def lite(kind, company):
        t = re.sub(r"^무배당\s*", "", kind)
        for w_ in (company, company[:2]):
            if w_ and t.startswith(w_):
                t = t[len(w_):].strip()
                break
        return t or kind
    for g in m["groups"]:
        for k, it in enumerate(g["items"]):
            rows.append((f"{g['company'].replace('화재해상', '')} {len(g['items'])}건" if k == 0 else "", lite(it["kind"], g["company"].replace("화재해상", "")), it["status"], it["done"]))
    comp = []
    for g in m["groups"]:
        tot, ok = 0, True
        for it in g["items"]:
            mm_ = re.fullmatch(r"월 ([\d,]+)원 납입 중", it["status"])
            if mm_:
                tot += int(mm_.group(1).replace(",", ""))
            elif not it["done"]:
                ok = False
        comp.append((g["company"], tot, ok))
    paid_sum = sum(t for _, t, _ in comp)
    bars_ok = bool(comp) and paid_sum == int((m["monthly"] or "0").replace(",", "") or 0)
    q = [m["monthly"], m["paid_total"]] + [r[2] for r in rows]
    ex = len(m["excluded"])
    n_done = sum(1 for it in m["items"] if it["done"])
    sub_short = f"유지 {m['n']}건 중 납입 중 {len(m['items']) - n_done}건, 완납 {n_done}건" + (f", 목록 제외 {ex}건" if ex and ENROLL_SHOW_EXCLUDED else "")
    base = dict(kind="enroll", label="계약 및 납입 현황", headline=m["title"], sub=sub_short, monthly=m["monthly"],
                paid_total=m["paid_total"], n=m["n"], card1_sub=m["card1_sub"], card2_sub=m["card2_sub"],
                comp=comp if bars_ok else [], note=(f"월 보험료 0원, 납입 0회인 계약 {ex}건은 목록에서 제외." if ex and ENROLL_SHOW_EXCLUDED else ""),
                excl=[f"{c_['company']} {c_['name']}" for c_ in m["excluded"]] if ENROLL_SHOW_EXCLUDED else [])
    # 1.37: 줄이 많으면 보험사 묶음을 쪼개지 않고 ENROLL_PER_PAGE 줄씩 나눈다(1~5쪽)
    groups, cur = [], []
    for r in rows:
        if r[0] and cur:
            groups.append(cur)
            cur = []
        cur.append(r)
    if cur:
        groups.append(cur)
    pages, page = [], []
    for g in groups:
        if page and len(page) + len(g) > ENROLL_PER_PAGE:
            pages.append(page)
            page = []
        page += g
    if page:
        pages.append(page)
    if len(pages) > ENROLL_MAX_PAGES:                      # 5쪽을 넘으면 뒤쪽을 마지막 쪽에 합쳐 줄 수만 늘린다
        pages = pages[:ENROLL_MAX_PAGES - 1] + [sum(pages[ENROLL_MAX_PAGES - 1:], [])]
    if not pages:
        pages = [[]]
    k_ = len(m["excluded"]) if ENROLL_SHOW_EXCLUDED else 0
    if k_ and len(pages[-1]) * 44 + 30 + 30 * k_ > 356:     # 1.40: 표 아래 안내(제외 계약 목록)가 쪽 바닥을 넘으면 다음 쪽에 쓴다
        pages.append([])
    out = []
    for i, pg in enumerate(pages):
        s_ = dict(base, last=(i == len(pages) - 1), rows=pg, quotes=[m["monthly"], m["paid_total"]] + [r[2] for r in pg])
        if len(pages) > 1:
            s_["label"] = f"계약 및 납입 현황 ({i + 1}/{len(pages)})"
        out.append(s_)
    return out


def extra_slides(entries, ctx, A):
    """원본의 나머지 쪽을 분석 슬라이드로 만든다. 만들 수 없는 것은 건너뛰고 알린다."""
    texts = [e["text"] for e in entries]
    m = next((re.search(r"\((\d{18,})\)", t) for t in texts if re.search(r"\((\d{18,})\)", t)), None)
    ctx["docno"] = m.group(1) if m else ""
    out = []
    for fn in (lambda: enroll_slide(entries), lambda: [score_slide(entries)], lambda: contract_slides(entries, ctx), lambda: [bodyfig_slide(entries)], lambda: [bodymap_slide(entries)],
               lambda: age_table_slides(A), lambda: other_slides(entries), lambda: prodcov_main_slides(entries), lambda: prodcov_slides(entries), lambda: prodcov_detail_slides(entries, True), lambda: [proposal_slide(entries)]):
        try:
            out += [s for s in fn() if s]
        except Exception as ex:
            print(f"[주의] 분석: 보충 슬라이드 하나를 만들지 못했습니다(나머지는 정상): {ex}")
    return out


def _insight(D, s, y0=196, h=400):
    """1.62: 분석 인사이트 상자. 항목은 한 항목 = 한 줄(insight1_lines / insight2_lines). 줄 목록이 없으면 문장(insight1/insight2)을 줄바꿈해 쓴다."""
    l1, l2 = s.get("insight1_lines") or [], s.get("insight2_lines") or []
    n = len(l1) + len(l2)
    big, step = (22, 34) if n <= 6 else (20, 30)
    if n:
        h = min(548, max(h, 250 + step * n + (40 if s.get("insight2") and l2 else 0) + 30))
    D.box(918, y0, 470, h, fill=AN_BOX, r=12)
    D.text(950, y0 + 66, "분석 인사이트", 27, AN_INK, True)
    if l1:
        yy = y0 + 112
        for t_ in l1:
            D.text(950, yy, _fit_txt(D, t_, big, 410), big, AN_INK, True)
            yy += step
    else:
        yy = D.para(950, y0 + 112, 410, s["insight1"], 22, AN_INK, 1.5)
    D.line(950, yy - 10, 1356, yy - 10, "#D5DAE2", 3)
    if s.get("insight2") and not (l2 and s.get("kind") in ("proposal", "bodymap")):
        yy = D.para(950, yy + 34, 410, s["insight2"], 22, AN_INK, 1.5)
    else:
        yy += 34
    for t_ in l2:
        D.text(950, yy, _fit_txt(D, t_, big if n > 6 else 20, 410), big if n > 6 else 20, AN_INK, True)      # 한 항목 = 한 줄
        yy += step
    return yy


def _fit_txt(D, txt, size, maxw):
    """글이 maxw 보다 길면 끝을 … 로 줄인다."""
    while len(txt) > 4 and D.width(txt, size, False) > maxw:
        txt = txt[:-2] + "…"
    return txt


def _fit(D, txt, size, maxw, bold=False, lo=14):
    while size > lo and D.width(txt, size, bold) > maxw:
        size -= 0.5
    return size


AMT_R = 770                                   # 2쪽 표: 금액 칸 오른쪽 끝 (상태 칸은 AMT_R + 16 부터)


def _split_status(st):
    """납입 상태 글을 두 칸으로: '월 10,355원 납입 중' → ('월 10,355원', '납입 중'), '건강 120/120회 완납' → ('건강 120/120회', '완납')."""
    m = re.fullmatch(r"(월 [\d,]+원)\s+(납입 중)", st) or re.fullmatch(r"(기납입 [\d,]+원)\s+(완납)", st) or re.fullmatch(r"(.*회)\s+(완납)", st)
    return (m.group(1), m.group(2)) if m else (st, "")


def _draw_enroll(D, s):
    """2쪽: 왼쪽 2/3 = 카드 2개 + 계약 목록(큰 글자), 오른쪽 1/3 = 스퀘어 엠블럼 그림(체크리스트+KYOBO)."""
    # 오른쪽 그림 (요약 쪽 보험 가입 현황과 같은 make_emblem_png)
    pw, ph = 470.0, 540.0
    png = make_emblem_png(pw * D.K, ph * D.K)
    D.c.drawImage(ImageReader(io.BytesIO(png)), D.X(918), D.Y(196 + ph), width=pw * D.K, height=ph * D.K, mask="auto")
    # 카드 2개
    for i, (lab, val, sub) in enumerate((("현재 월 납입보험료", s["monthly"], ""), ("누적 기납입보험료", s["paid_total"], ""))):
        x = 67 + i * 405
        D.box(x, 196, 385, 112, fill=AN_CARD, stroke=AN_CARD_LINE, r=10, lw=2)
        D.text(x + 24, 232, lab, 17, "#374151")
        wv = D.width(val, 42, True) + 4 + D.width("원", 22, True)           # 1.34: 카드 숫자는 오른쪽 정렬
        xe = D.text(x + 385 - 24 - wv, 282, val, 42, AN_INK, True)
        D.text(xe + 4, 282, "원", 22, AN_INK, True)
    # 목록
    x0, cw1, cw2 = 67, 190, 400
    if s["rows"]:                                          # 안내만 있는 이어지는 쪽에는 표 머리글을 그리지 않는다
        D.text(x0 + 8, 356, "보험사", 19, AN_INK, True)
        D.text(x0 + cw1, 356, "계약 현황", 19, AN_INK, True)
        D.text(AMT_R, 356, "납입 현황", 19, AN_INK, True, "R")
        D.text(AMT_R + 16, 356, "상태", 19, AN_INK, True)
        D.line(x0, 370, 857, 370, "#BFC5CF", 2)
    n = len(s["rows"])
    step = 44.0 if n <= 8 else 300.0 / n                   # 1.37: 8줄 이하는 같은 간격(큰 글자), 더 많으면 줄여서 맞춤
    fs = min(19.0, step * 0.55)
    for i, (co, kind, st, done) in enumerate(s["rows"]):
        yy = 404 + i * step
        if co:
            D.text(x0 + 8, yy, co, _fit(D, co, fs, cw1 - 18, True, 13), AN_INK, True)
        D.text(x0 + cw1, yy, kind, _fit(D, kind, fs, AMT_R - 150 - (x0 + cw1), False, 13), AN_INK)
        a_, b_ = _split_status(st)                                  # 1.35: 가상 셀 — 금액 칸(오른쪽 정렬) + 상태 칸(왼쪽 정렬), 같은 글자 크기·굵기
        col_ = AN_T_OK if done else AN_C_NEED
        D.text(AMT_R, yy, a_, fs, col_, True, "R")
        if b_:
            D.text(AMT_R + 16, yy, b_, fs, col_, True)
        last_in_group = (i + 1 == n) or bool(s["rows"][i + 1][0])        # 1.37: 보험사 묶음의 마지막 줄 아래선만 진하게(글자를 가로지르지 않음)
        D.line(x0, yy + 12, 857, yy + 12, "#BFC5CF" if last_in_group else "#E1E5EB", 1.5 if last_in_group else 1)
    if s.get("note") and s.get("last"):                                  # 1.38: 목록에서 뺀 계약을 마지막 쪽 표 아래에 알림
        y_ = (404 + n * step + 30) if n else 380
        D.text(x0 + 8, y_, s["note"], 14, AN_GRAY)
        for j_, nm_ in enumerate(s.get("excl", [])[:8]):                # 1.39: 빠진 계약을 한 줄에 하나씩 아래로 나열
            D.text(x0 + 24, y_ + 30 * (j_ + 1), f"{j_ + 1}. {_fit_txt(D, nm_, 16, 760)}", 16, AN_INK)



def _draw_extra(D, s):
    k = s["kind"]
    if k == "enroll":
        _draw_enroll(D, s)
        return
    if k in ("score", "bodymap", "contracts", "other"):
        rows = s["bars"]
        titles = {"score": ("영역별 점수 (100점 만점)", "점수 (점)"), "bodymap": ("신체부위별 보장금액 (보장이 있는 항목)", "보장금액 (만원)"),
                  "contracts": ("계약별 보장 항목 수", "분석 항목 수 (개)"), "other": ("보장항목별 보장금액 (금액 큰 순)", "보장금액 (만원)")}
        title, axis = titles[k]
        if k == "score":
            vmax, step = 100, 25
        else:
            vmax = _nice_max(max([r[1] for r in rows] + [1]))
            step = max(1, round(vmax / 5)) if k == "contracts" else vmax / 5
        up = s.get("fs_up", 0)
        D.text(67, 235, title, (BASE_FS + up) if up else 16, "#1F2937", True)
        n = len(rows)
        bar_h = 34 if n <= 8 else (30 if n <= 10 else 26)
        gap = 14 if n <= 8 else 10
        lw_ = {"score": 110, "bodymap": 130, "contracts": 230, "other": 230 + 6 * up}[k]
        if rows:
            D.hbars(67, 250, 790, [(a, b, c) for a, b, c, _ in rows], vmax, step, axis, lw_, bar_h, gap, show_val=False, up=up)
        pw_ = 790 - lw_
        for i, (nm, v, col, lab) in enumerate(rows):
            by = 250 + 20 + i * (bar_h + gap)
            bw = max(8.0, (pw_ - 20) * v / vmax)
            tx = 67 + lw_ + 10 + bw
            if bw >= 100:
                D.text(tx - 12, by + bar_h / 2 + 6 + up / 2, lab, (BASE_FS + up - 2) if up else 15, "#111111" if (col == AN_C_LOW or col in PC_BAR_COLORS) else "#FFFFFF", True, "R")
            else:
                D.text(tx + 10, by + bar_h / 2 + 6 + up / 2, lab, (BASE_FS + up - 2) if up else 15, "#111111")
        if k == "other":
            if not rows:
                D.text(110, 420, "분석 보장항목에 연결된 특약 없음.", 22, AN_GRAY)
            for i, (t, l1, l2) in enumerate(s["cards"]):
                y0 = 192 + i * 130
                D.box(918, y0, 470, 112, fill="#FFFFFF", stroke=AN_CARD_LINE, r=10, lw=2)
                D.text(942, y0 + 34, t, (BASE_FS + up - 2) if up else 16, "#4B5563")
                D.text(1364, y0 + 68, l1, 24 + up, AN_INK, True, "R")
                D.text(1364, y0 + 98, l2, (NOTE_FS + up - 2) if up else 14, AN_GRAY, False, "R")
            if s["note"]:
                D.para(918, 600, 470, [(s["note"], False)], (NOTE_FS + up - 2) if up else 14, AN_GRAY, 1.5)
        else:
            _insight(D, s, 196, 420 if k != "bodymap" else 440)
            if k == "bodymap":
                xx = D.chip(1080, 135, AN_C_OK, "충분")          # 1.62: 인사이트 줄이 늘어 범례를 머리 아래 오른쪽으로 옮김
                D.chip(xx, 135, AN_C_LOW, "부족")
    elif k == "agetable":
        D.text(67, 235, "연령별로 보장 중인 항목 수 (개)", 17, "#1F2937", True)
        D.vbars(67, 252, 790, 250, s["cats"], [("v", AN_C_NEED, s["vals"])], _nice_max(max(s["vmax"], 1)), "연령")
        for i, (t, l1, l2) in enumerate(s["cards"][:3]):
            y0 = 192 + i * 130
            D.box(918, y0, 470, 112, fill="#FFFFFF", stroke=AN_CARD_LINE, r=10, lw=2)
            D.text(942, y0 + 34, t, 16, "#4B5563")
            D.text(942, y0 + 68, l1, 21, AN_INK)
            D.text(942, y0 + 98, l2, 21, AN_INK, True)
    elif k == "proposal":
        x = D.chip(67, 200, AN_C_NEED, "제안 전 (개)")
        D.chip(x, 200, AN_C_PREP, "제안 후 (개)")
        ymax = _nice_max(max(s["before"] + s["after"] + [1]))
        D.vbars(67, 262, 790, 230, s["cats"], [("전", AN_C_NEED, s["before"]), ("후", AN_C_PREP, s["after"])], ymax, "보장 상태")
        _insight(D, s, 196, 330)
        if s["note"]:
            D.text(918, 640, s["note"], 14, AN_GRAY)
    elif k == "stablechart":
        ch = s["chart"]
        x = D.chip(67, 200, AN_C_NEED, "필요액 (만원)")
        D.chip(x, 200, AN_C_PREP, "준비액 (만원)")
        D.vbars(67, 262, 790, 230, ch["cats"], [("필요", AN_C_NEED, ch["need"]), ("준비", AN_C_PREP, ch["prep"])], _nice_max(max(ch["need"] + ch["prep"])), ch["xlabel"])
        D.text(932, 235, "구분", 19, AN_INK, True)
        D.text(1250, 235, "준비/필요", 19, AN_INK, True, "R")
        D.text(1370, 235, "준비율", 19, AN_INK, True, "R")
        D.line(918, 252, 1388, 252, "#BFC5CF", 2)
        for i, (a, b_, r_) in enumerate(s["table"]):
            yy = 290 + i * 52
            D.text(932, yy, a, 19, AN_INK, True)
            D.text(1250, yy, b_, 18, AN_INK, False, "R")
            D.text(1370, yy, r_, 19, AN_C_PREP, True, "R")
            D.line(918, yy + 18, 1388, yy + 18, "#E1E5EB", 1.5)
        D.para(918, 290 + len(s["table"]) * 52 + 62, 470, [(s["note"], False)], 14, AN_GRAY, 1.5)


def _base_stem(out):
    """결과 파일 이름에서 _분석 / _요약 꼬리를 뗀 이름."""
    stem = Path(out).stem
    for tail in ("_분석", "_요약"):
        if stem.endswith(tail):
            return stem[:-len(tail)]
    return stem


def analysis_path(out):
    """분석 PDF(주 결과) 경로: <이름>_분석.pdf"""
    return Path(out).with_name(_base_stem(out) + "_분석.pdf")


def summary_path(out):
    """요약 PDF(함께 저장) 경로: <이름>_요약.pdf"""
    return Path(out).with_name(_base_stem(out) + "_요약.pdf")


def report_path(out):
    """요약 리포트 PDF 경로: <이름>_요약리포트.pdf"""
    return Path(out).with_name(_base_stem(out) + "_요약리포트.pdf")


def _report_info(ap):
    """분석 PDF 의 글을 읽어 리포트에 쓸 값을 모은다(없는 값은 None). 값은 모두 분석 PDF 에 적힌 그대로다."""
    pages = []
    with pdfplumber.open(str(ap)) as pdf:
        for pg in pdf.pages:
            pages.append(pg.extract_text() or "")
    allt = "\n".join(pages)
    flat = re.sub(r"\s+", " ", allt)

    def g(pat, txt=None, grp=1):
        m = re.search(pat, flat if txt is None else txt)
        return m.group(grp) if m else None
    info = dict(name=g(r"(\S+) 고객님을 위한"), fp=(g(r"(\S+) Financial Planner") or g(r"Financial Planner (?!소속)(\S+)")), branch=g(r"소속: (\S+)"))
    d = re.search(r"조회시점 (\d{4})-(\d{2})-(\d{2})", flat) or re.search(r"출력 \| (\d{4})-(\d{2})-(\d{2})", flat)
    info["date"] = f"{int(d.group(1))}년 {int(d.group(2))}월 {int(d.group(3))}일" if d else None
    info["age"] = g(r"영역별 보장 준비 현황 \S+ \((\d+)세\)")
    m = re.search(r"유지 계약 (\d+)건, 월 보험료는 ([\d,]+)원", flat)
    info["n_con"], info["prem"] = (m.group(1), m.group(2)) if m else (None, None)
    info["score"] = g(r"종합점수 (\d+)점")
    m = re.search(r"(\d+)개 항목 중 적정 (\d+)개, 보완 필요 (\d+)개", flat)
    info["total"], info["ok"], info["need"] = m.groups() if m else (None, None, None)
    info["full_areas"] = g(r"필요액을 모두 채운 영역 (\d+)개")
    _ar = r"(?:수술|입원|사망|항암|통원|실손|진단)"
    info["strong"] = g(r"(" + _ar + r"(?:, ?" + _ar + r")*) 충분, 간단 점검")
    info["death"] = g(r"사망 보장은 필요액의 ([\d~]+)% 수준")
    info["diag"] = g(r"진단비는 필요액의 약 (\d+)%만 준비")
    info["chemo_need"], info["chemo_prep"] = (None, None)
    m = re.search(r"필요액 ([\d,]+)만원 중 현재 (\S+?)만원만 보장", flat)
    if m:
        info["chemo_need"], info["chemo_prep"] = m.group(1), m.group(2)
    _tk = r"(?:[A-Za-z]{2,}|[가-힣]+)"
    m = re.search(r"(" + _tk + r"(?:, ?" + _tk + r"){0,2}) 등 (\d+)개 항목 보장 없음", flat)
    info["miss_names"], info["miss_n"] = (re.split(r", ?", m.group(1))[:3], m.group(2)) if m else (None, None)
    m = re.search(r"신체부위 (\d+)개 항목 중 보장 없음 (\d+)개", flat)
    info["body_total"], info["body_none"] = m.groups() if m else (None, None)
    info["age_start"] = g(r"(\d+)세부터 보장금액 감소 시작")
    m = re.search(r"(\d+)세에는 (\d+)개 항목 중 (\d+)개만 유지", flat)
    info["age_end"], info["age_all"], info["age_keep"] = m.groups() if m else (None, None, None)
    m = re.findall(r"부족액: (\S+) ([\d,]+)만원, (\S+) ([\d,]+)만원", flat)          # 1.65: 보완 순서의 부족액(암 진단비, 뇌·심장 진단비)
    info["cancer"] = m[0] if len(m) > 0 else None
    info["brain"] = m[1] if len(m) > 1 else None
    m = re.search(r"필요액: LTC ([\d,]+)만원, 중증치매 ([\d,]+)만원", flat)
    info["ltc"] = m.groups() if m else None
    ch = []
    for nm_, amt_ in re.findall(r"(항암약물치료|항암중입자 치료|항암방사선 치료) (?:항암 치료 항목 )?필요 [\d,]+ / 준비 \S+? (?:[\d.]+k? )*([\d,]+)만원 부족", flat):
        if (nm_, amt_) not in ch:
            ch.append((nm_, amt_))
    info["chemo_items"] = ch
    return info


def _report_parts(i):
    """리포트 문장 조각. 조각마다 길이가 다른 표현을 여러 개 두고, 합계가 REPORT_CHARS 가 되게 고른다. 6하 원칙·서술형·구어체(해요체)."""
    nm = i["name"] or "고객"
    who = f"{i['age']}세 {nm}" if i.get("age") else nm
    P = []
    # 1.65: 부제와 첫 문단(누가·언제·왜)은 넣지 않는다
    if i["n_con"]:
        P.append([f"고객님은 유지 계약이 {i['n_con']}건이고 매달 {i['prem']}원을 보험료로 내고 계세요.", f"고객님은 유지 계약 {i['n_con']}건에 매달 {i['prem']}원을 보험료로 내고 계세요."])
    if i["score"] and i["ok"]:
        low = int(i["score"]) < 80
        P.append([f"{'그런데도' if low else '그래서'} 종합점수는 {i['score']}점이에요. {i['total']}개 항목 중 {i['ok']}개만 적정하고 {i['need']}개는 보완이 필요하기 때문이에요.",
                  f"{'그런데도' if low else '그래서'} 종합점수는 {i['score']}점이에요. {i['total']}개 항목 중 {i['ok']}개가 적정하고 {i['need']}개는 보완이 필요해요."])
    if i["full_areas"]:
        P.append([f"7개 보장 영역 중 필요액을 모두 채운 영역은 {i['full_areas']}개예요.", f"7개 보장 영역 중 필요액을 다 채운 영역은 {i['full_areas']}개예요.", ""])
    st = i["strong"] or ""
    chemo = ("하나도 없어요" if i["chemo_prep"] in ("-", "0") else None)
    if st and i["death"] and "사망" in st:
        P.append([f"{st} 보장은 든든해서 사망은 필요액의 {i['death']}%까지 준비돼 있어요.", f"{st} 보장은 아주 든든해서 사망은 필요액의 {i['death']}%까지 준비돼 있어요."])
        if i["diag"]:
            P.append([f"반면 진단비는 필요액의 약 {i['diag']}%만 준비됐고, 항암 치료비는 " + (chemo or f"필요액 {i['chemo_need']}만원 중 {i['chemo_prep']}만원만 준비돼 있어요") + "."])
    else:
        if st and i["diag"] and i["death"]:
            P.append([f"{st}은 충분하지만 진단비는 필요액의 약 {i['diag']}%뿐이고, 사망 보장도 필요액의 {i['death']}% 수준이에요.", f"{st}은 충분하지만 진단비는 필요액의 {i['diag']}%뿐이고, 사망 보장도 필요액의 {i['death']}% 수준이에요."])
        if i["chemo_need"]:
            P.append(["항암 치료비는 하나도 없어요." if chemo else f"항암 치료비도 필요액 {i['chemo_need']}만원 중 {i['chemo_prep']}만원만 준비돼 있어요.", ""] if chemo else [f"항암 치료비도 필요액 {i['chemo_need']}만원 중 {i['chemo_prep']}만원만 준비돼 있어요.", f"항암 치료비도 필요액 {i['chemo_need']}만원 중 {i['chemo_prep']}만원 준비돼 있어요."])
    if i["miss_n"] and i["body_none"]:
        names = ", ".join(i["miss_names"])
        P.append([f"{names} 같은 {i['miss_n']}개 항목은 아예 보장이 없고, 신체부위 {i['body_total']}개 항목 중 {i['body_none']}개도 보장이 없어요.",
                  f"{names} 같은 {i['miss_n']}개 항목은 보장이 없고, 신체부위 {i['body_total']}개 항목 중 {i['body_none']}개도 보장이 없어요."])
    if i["age_start"]:
        P.append([f"{i['age_start']}세부터는 보장금액도 줄기 시작해요.", ""])
    # 1.70: 권장 사항부터는 줄을 나누고 번호(1. 2. 3.)와 쌍점(:)으로 항목을 구분한다. 앞의 "\n" 은 줄바꿈 표시(글자 수에는 공백 하나로 셈)
    P.append(["\n그래서 이렇게 순서를 정해 채우시길 권해 드려요.", "\n그래서 이 순서대로 채우시길 권해 드려요."])
    n_ = 0
    def nn():
        nonlocal n_
        n_ += 1
        return f"\n{n_}. "
    if i.get("cancer"):
        a_, x_, b_, y_ = i["cancer"]
        k = nn()
        P.append([f"{k}암 진단비: {a_} {x_}만원, {b_} {y_}만원이 부족해요.", f"{k}암 진단비: {a_} {x_}만원, {b_} {y_}만원 부족."])
    if i.get("chemo_items"):
        full = ", ".join(f"{n} {a}만원" for n, a in i["chemo_items"])
        two = ", ".join(f"{n} {a}만원" for n, a in i["chemo_items"][:2])
        k = nn()
        P.append([f"{k}항암 치료비: {full}이 부족해요.", f"{k}항암 치료비: {two}이 부족해요.", f"{k}항암 치료비."])
    if i.get("brain"):
        a_, x_, b_, y_ = i["brain"]
        k = nn()
        P.append([f"{k}뇌와 심장 진단비: {a_} {x_}만원, {b_} {y_}만원을 채워요.", f"{k}진단비: {a_}, {b_}를 채워요."])
    if i.get("ltc"):
        k = nn()
        P.append([f"{k}간병과 치매: LTC {i['ltc'][0]}만원, 중증치매 {i['ltc'][1]}만원을 검토해 보세요.", f"{k}간병과 치매: LTC, 중증치매를 검토해 보세요."])
    return P


REPORT_CLOSING = ("보험은 큰 병이나 사고가 갑자기 닥쳤을 때 치료비와 생활비 걱정 없이 치료에 집중하게 해 주는 안전망이에요. "
                  "지금 미리 준비해 두면 가족에게 짐을 남기지 않고, 나이가 들어 가입이 어려워지기 전에 대비할 수 있어요.")   # 1.71: 맨 끝 2~3줄(보험이 필요한 이유). 500자 글자 수에는 넣지 않음. 문구는 여기서 수정

def _report_text(info, target=None):
    """조각마다 표현을 골라 공백 포함 target 자에 맞춘 글을 만든다. 맞는 조합이 없으면 target 이하에서 가장 긴 조합."""
    target = target or REPORT_CHARS
    parts = _report_parts(info)
    best = {0: ((), 0)}                                      # 글자 수 -> (고른 표현 번호들, 비용). 뒤쪽 조각(끝 권고)일수록 자세한 표현(앞 번호)을 우선한다
    for j, opts in enumerate(parts):
        nxt = {}
        for tot, (pick, cost) in best.items():
            for k, t in enumerate(opts):
                add = len(t) + (1 if (t and not t.startswith("\n") and pick and any(parts[q][pick[q]] for q in range(len(pick)))) else 0)
                n = tot + add
                c = cost + k * (j + 1)
                if n <= target and (n not in nxt or c < nxt[n][1]):
                    nxt[n] = (pick + (k,), c)
        best = nxt
    n = max(best)
    pick = best[n][0]
    text = ""
    for j, k in enumerate(pick):
        t = parts[j][k]
        if t:
            text += t if (t.startswith("\n") or not text) else " " + t
    return text


def make_report_pdf(ap, out):
    """분석 PDF 의 결과를 6하 원칙 서술형·구어체 500자로 요약한 1쪽 PDF 를 만든다. -> (경로, 글자 수)"""
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer
    from reportlab.lib.styles import ParagraphStyle
    info = _report_info(ap)
    if not info.get("name"):
        raise ValueError("분석 PDF 에서 고객 이름을 찾지 못했습니다")
    text = _report_text(info)
    h = ParagraphStyle("h", fontName=FONT_B, fontSize=20, leading=28, textColor=colors.HexColor("#1F3F7A"))
    sm = ParagraphStyle("s", fontName=FONT, fontSize=11, leading=16, textColor=colors.HexColor("#6B7280"))
    b = ParagraphStyle("b", fontName=FONT_B, fontSize=14, leading=27, textColor=colors.HexColor("#0A0A0A"), wordWrap="CJK")
    doc = SimpleDocTemplate(str(out), pagesize=A4, leftMargin=60, rightMargin=60, topMargin=70, bottomMargin=60, title=f"{info['name']} 보장분석 요약 리포트")
    doc.build([Paragraph(f"{info['name']} 고객님 보장분석 요약 리포트", h), Spacer(1, 6),
               Spacer(1, 24),
               Paragraph(text.replace("\n", "<br/>"), b), Spacer(1, 14),
               Paragraph(REPORT_CLOSING, b), Spacer(1, 26),
               Paragraph("※ 분석 PDF 의 원본 수치를 정리한 요약이며 보험금 지급 근거가 아님. 약관, 증권 우선.", sm)])
    return Path(out), len(text)


def verify_analysis(path, slides, offset=0):
    """분석 쪽 검사: 쪽 수·16:9 와, 원본에서 그대로 인용한 값이 해당 쪽에 모두 나오는지 확인한다. 빠지면 오류로 멈춘다.
    offset = 분석 쪽 앞에 있는 쪽 수(요약 PDF 안에 붙인 경우 원본 쪽 수, 별도 파일이면 0)."""
    with pdfplumber.open(str(path)) as pdf:
        pages = pdf.pages[offset:]
        if len(pages) != len(slides):
            raise RuntimeError(f"분석 쪽 수({len(pages)})가 슬라이드 수({len(slides)})와 다릅니다.")
        for k_, (pg, s) in enumerate(zip(pages, slides), 1):
            if abs(pg.width / pg.height - 16 / 9) > 0.01:
                raise RuntimeError(f"분석 {k_}쪽이 16:9 가 아닙니다.")
            txt = pg.extract_text() or ""
            miss = [q for q in s["quotes"] if q not in txt]
            if miss:
                raise RuntimeError(f"분석 {k_}쪽(전체 {offset + k_}쪽, {s['label']}) 검사 실패: 원본 값 {miss} 가 쪽에 없습니다.")
    where = f"분석 PDF {offset + 1}~{offset + len(slides)}쪽" if offset else "분석 PDF"
    print(f"[검사] {where} 분석 {len(slides)}쪽 16:9·원본 인용 값 {sum(len(s['quotes']) for s in slides)}개 대조 일치")


def build_analysis_pdf(entries, ctx, out_path):
    from reportlab.pdfgen import canvas as rl_canvas
    slides = analysis_slides(entries, ctx)
    if not slides:
        print("[분석] 분석할 상품별 분석 데이터가 없어 분석 PDF 를 만들지 않았습니다.")
        return None
    c = rl_canvas.Canvas(str(out_path), pagesize=(WIDE_W, WIDE_H))
    c.setTitle(f"{ctx.get('name', '')} 고객님 보장분석 정리")
    D = Deck(c)
    for n, s in enumerate(slides, 1):
        _draw_slide(D, s, n, len(slides), ctx)
        c.showPage()
    c.save()
    verify_analysis(out_path, slides)
    return slides


# ----------------------------------------------------------------------------
# 7. PDF 선택 창 (tkinter)
# ----------------------------------------------------------------------------
def open_path(path):
    """운영체제 기본 프로그램으로 파일/폴더 열기."""
    path = str(path)
    try:
        if sys.platform.startswith("win"):
            os.startfile(path)                                # noqa: S606 (Windows 전용)
        elif sys.platform == "darwin":
            subprocess.Popen(["open", path])
        else:
            subprocess.Popen(["xdg-open", path])
    except Exception as ex:                                   # 열 프로그램이 없는 환경(서버 등)
        print(f"[안내] 자동으로 열 수 없습니다. 직접 여세요: {path}  ({ex})")


class _QueueWriter(io.TextIOBase):
    """print 출력을 창의 로그로 보내기 위한 쓰기 도우미."""

    def __init__(self, q):
        self.q = q

    def write(self, text):
        if text:
            self.q.put(("log", text))
        return len(text)


class App:
    def __init__(self, root):
        self.root = root
        self.q = queue.Queue()
        self.result = None
        self.running = False
        self.finished = False                 # (테스트·점검용) 한 번 변환이 끝나면 True
        self.manual_out = False               # 저장 위치를 직접 골랐는가
        self.last_dir = str(Path.home())
        self.src_var, self.out_var = tk.StringVar(), tk.StringVar()
        self.status_var = tk.StringVar(value="PDF를 선택하세요.")

        root.title(f"보장분석 PDF 만들기 v{APP_VERSION}")
        root.geometry("760x540")
        root.minsize(640, 460)
        frm = ttk.Frame(root, padding=14)
        frm.pack(fill="both", expand=True)
        frm.columnconfigure(1, weight=1)
        frm.rowconfigure(5, weight=1)

        ttk.Label(frm, text="교보생명 보장분석 보고서 PDF를 골라, 요약한 내용으로 분석 PDF를 만듭니다.",
                  foreground="#555555").grid(row=0, column=0, columnspan=3, sticky="w", pady=(0, 10))

        ttk.Label(frm, text="원본 PDF").grid(row=1, column=0, sticky="w", padx=(0, 8))
        ttk.Entry(frm, textvariable=self.src_var, state="readonly").grid(row=1, column=1, sticky="ew")
        self.btn_pick = ttk.Button(frm, text="PDF 선택...", command=self.pick_src)
        self.btn_pick.grid(row=1, column=2, padx=(8, 0))

        ttk.Label(frm, text="저장 위치").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=(8, 0))
        ttk.Entry(frm, textvariable=self.out_var).grid(row=2, column=1, sticky="ew", pady=(8, 0))
        self.btn_out = ttk.Button(frm, text="저장 위치...", command=self.pick_out)
        self.btn_out.grid(row=2, column=2, padx=(8, 0), pady=(8, 0))

        bar = ttk.Frame(frm)
        bar.grid(row=4, column=0, columnspan=3, sticky="ew", pady=(12, 8))
        bar.columnconfigure(1, weight=1)
        self.btn_run = ttk.Button(bar, text="PDF 만들기", command=self.start)
        self.btn_run.grid(row=0, column=0)
        self.progress = ttk.Progressbar(bar, mode="indeterminate")
        self.progress.grid(row=0, column=1, sticky="ew", padx=10)
        self.btn_open = ttk.Button(bar, text="PDF 열기", command=self.open_result, state="disabled")
        self.btn_open.grid(row=0, column=2)
        self.btn_folder = ttk.Button(bar, text="폴더 열기", command=self.open_folder, state="disabled")
        self.btn_folder.grid(row=0, column=3, padx=(6, 0))

        box = ttk.Frame(frm)
        box.grid(row=5, column=0, columnspan=3, sticky="nsew")
        box.rowconfigure(0, weight=1)
        box.columnconfigure(0, weight=1)
        self.text = tk.Text(box, height=12, wrap="word", state="disabled", background="#F7F8FA", relief="flat",
                            borderwidth=1)
        sb = ttk.Scrollbar(box, command=self.text.yview)
        self.text.configure(yscrollcommand=sb.set)
        self.text.grid(row=0, column=0, sticky="nsew")
        sb.grid(row=0, column=1, sticky="ns")
        ttk.Label(frm, textvariable=self.status_var).grid(row=6, column=0, columnspan=3, sticky="w", pady=(8, 0))
        self._center()
        self.root.after(100, self._poll)

    # ---- 화면 도우미
    def _center(self):
        self.root.update_idletasks()
        w, h = self.root.winfo_width(), self.root.winfo_height()
        x = (self.root.winfo_screenwidth() - w) // 2
        y = (self.root.winfo_screenheight() - h) // 3
        self.root.geometry(f"+{max(x, 0)}+{max(y, 0)}")

    def log(self, text):
        self.text.configure(state="normal")
        self.text.insert("end", text)
        self.text.see("end")
        self.text.configure(state="disabled")

    def set_busy(self, busy):
        self.running = busy
        state = "disabled" if busy else "normal"
        for w in (self.btn_pick, self.btn_out, self.btn_run):
            w.configure(state=state)
        if busy:
            self.progress.start(12)
            for w in (self.btn_open, self.btn_folder):
                w.configure(state="disabled")
        else:
            self.progress.stop()

    # ---- 파일 선택
    def set_source(self, path):
        path = str(path)
        self.src_var.set(path)
        self.last_dir = str(Path(path).parent)
        if not self.manual_out:
            self.out_var.set(str(Path(path).with_name(Path(path).stem + "_분석.pdf")))
        self.status_var.set("[PDF 만들기]를 누르세요.")

    def pick_src(self):
        path = filedialog.askopenfilename(title="원본 보장분석 보고서 PDF 선택", initialdir=self.last_dir,
                                          filetypes=[("PDF 파일", "*.pdf"), ("모든 파일", "*.*")])
        if path:
            self.set_source(path)

    def pick_out(self):
        cur = Path(self.out_var.get()) if self.out_var.get() else None
        path = filedialog.asksaveasfilename(title="분석 PDF 저장 위치", defaultextension=".pdf",
                                            initialdir=str(cur.parent) if cur else self.last_dir,
                                            initialfile=cur.name if cur else "분석.pdf",
                                            filetypes=[("PDF 파일", "*.pdf")])
        if path:
            self.out_var.set(path)
            self.manual_out = True

    # ---- 변환
    def start(self):
        if self.running:
            return
        src = Path(self.src_var.get().strip().strip('"'))
        if not src.is_file():
            messagebox.showwarning("PDF 선택", "먼저 원본 PDF를 선택하세요.")
            return
        if src.suffix.lower() != ".pdf":
            messagebox.showwarning("PDF 선택", "PDF 파일(.pdf)을 선택하세요.")
            return
        out = Path(self.out_var.get().strip().strip('"'))
        if not out.name:
            messagebox.showwarning("저장 위치", "저장할 파일 이름을 입력하세요.")
            return
        if out.suffix.lower() != ".pdf":
            out = out.with_suffix(".pdf")
            self.out_var.set(str(out))
        if out.resolve() == src.resolve():
            messagebox.showerror("저장 위치", "원본 PDF와 같은 파일에는 저장할 수 없습니다.\n저장 위치를 바꿔 주세요.")
            return
        if out.exists() and not self.manual_out:
            if not messagebox.askyesno("덮어쓰기", f"같은 이름의 파일이 이미 있습니다.\n덮어쓸까요?\n\n{out}"):
                return
        try:
            out.parent.mkdir(parents=True, exist_ok=True)
        except OSError as ex:
            messagebox.showerror("저장 위치", f"저장 폴더를 만들 수 없습니다.\n{ex}")
            return
        self.text.configure(state="normal")
        self.text.delete("1.0", "end")
        self.text.configure(state="disabled")
        self.finished = False
        self.result = None
        self.status_var.set("변환 중입니다...")
        self.set_busy(True)
        threading.Thread(target=self._worker, args=(src, out), daemon=True).start()

    def _worker(self, src, out):
        try:
            with contextlib.redirect_stdout(_QueueWriter(self.q)):
                res = convert(src, out)
            self.q.put(("done", (res,)))
        except Exception as ex:                                    # 어떤 오류든 창에 보여 준다
            self.q.put(("log", traceback.format_exc()))
            self.q.put(("error", ex))

    def _poll(self):
        try:
            while True:
                kind, payload = self.q.get_nowait()
                if kind == "log":
                    self.log(payload)
                elif kind == "done":
                    self._on_done(*payload)
                elif kind == "error":
                    self._on_error(payload)
        except queue.Empty:
            pass
        self.root.after(100, self._poll)

    def _on_done(self, res):
        self.set_busy(False)
        self.finished = True
        main = res.get("main")
        self.result = Path(main) if main else None            # 열기·폴더 열기는 분석 PDF(우선)를 가리킨다
        for w in (self.btn_open, self.btn_folder):
            w.configure(state="normal")
        n_src, n_sum, n_ana = res["n_src"], res["n_sum"], res["n_ana"]
        parts = []
        if res.get("analysis"):
            parts.append(f"분석 {n_ana}쪽")
        if res.get("summary"):
            parts.append(f"요약 {n_sum}쪽")
        if res.get("report"):
            parts.append("요약 리포트 1쪽")
        what = " + ".join(parts) if parts else "결과 없음"
        files = "\n".join(str(p) for p in (res.get("analysis"), res.get("report"), res.get("summary")) if p)
        self.status_var.set(f"완료: 원본 {n_src}쪽 → {what}  |  {main}")
        if res.get("summary") and n_sum != n_src:
            messagebox.showwarning("쪽수 확인", f"요약 {n_src}쪽이 되어야 하는데 {n_sum}쪽입니다.\n로그를 확인하세요.")
        elif messagebox.askyesno("완료", f"PDF를 만들었습니다. ({what})\n{files}\n\n분석 PDF를 지금 열어 볼까요?"):
            self.open_result()

    def _on_error(self, ex):
        self.set_busy(False)
        self.finished = True
        self.status_var.set("오류가 발생했습니다. 아래 로그를 확인하세요.")
        hint = ""
        if isinstance(ex, PermissionError):
            hint = "\n\n저장하려는 PDF가 다른 프로그램에서 열려 있으면 닫고 다시 시도하세요."
        messagebox.showerror("변환 실패", f"{ex}{hint}")

    # ---- 결과 열기
    def open_result(self):
        if self.result and self.result.exists():
            open_path(self.result)

    def open_folder(self):
        if self.result:
            open_path(self.result.parent)


def run_gui():
    try:                                              # 윈도우 고해상도 화면에서 글자 흐림 방지
        import ctypes
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
    except Exception:
        pass
    root = tk.Tk()
    App(root)
    root.mainloop()


def _clean_path(text):
    """따옴표·앞뒤 공백을 지우고 ~ 와 환경변수를 풀어 Path 로 돌려준다."""
    return Path(os.path.expandvars(os.path.expanduser(str(text).strip().strip('"').strip("'"))))


def _writable_output(out, src):
    """결과를 저장할 수 있는 경로를 돌려준다. 원본 폴더에 쓸 수 없으면 현재 폴더 → 홈 폴더로 대체."""
    out = Path(out)
    for folder in (out.parent, Path.cwd(), Path.home()):
        try:
            folder.mkdir(parents=True, exist_ok=True)
            probe = folder / ".summary_report_write_test"
            probe.write_bytes(b"")
            probe.unlink()
        except OSError:
            continue
        final = out if folder == out.parent else folder / out.name
        if final != out:
            print(f"[안내] {out.parent} 에 저장할 수 없어 {folder} 에 저장합니다.")
        return final
    return out


def _usage_and_exit(reason):
    print(reason)
    print("\n사용법: python summary_report_v12.py <원본.pdf> [결과_분석.pdf]")
    sys.exit(1)


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    old_opts = [a for a in sys.argv[1:] if a.startswith("--")]
    if old_opts:                                      # 1.25: 선택 옵션이 없어졌다
        print(f"[안내] 선택 옵션({' '.join(old_opts)})은 없어졌습니다. 항상 분석 PDF 를 만듭니다.")
    if not args:                                      # 인자가 없으면 PDF 선택 창을 연다
        if tk is not None:
            try:
                run_gui()
                return
            except tk.TclError as ex:                 # 화면이 없는 환경(서버·SSH 등)
                print(f"[안내] 창을 열 수 없습니다({ex}).")
        if sys.stdin is not None and sys.stdin.isatty():
            typed = input("원본 PDF 경로를 입력하세요 (끌어다 놓아도 됩니다): ").strip()
            if not typed:
                _usage_and_exit("경로가 입력되지 않았습니다.")
            args = [typed]
        else:
            _usage_and_exit("PDF 경로가 필요합니다.")
    src = _clean_path(args[0])
    if not src.is_file():
        _usage_and_exit(f"원본 PDF를 찾을 수 없습니다: {src}")
    out = _clean_path(args[1]) if len(args) > 1 else src.with_name(src.stem + "_분석.pdf")
    if out.suffix.lower() != ".pdf":
        out = out.with_suffix(".pdf")
    if out.resolve() == src.resolve():
        _usage_and_exit("원본 PDF와 같은 파일에는 저장할 수 없습니다. 결과 파일 이름을 다르게 지정하세요.")
    out = _writable_output(out, src)
    try:
        convert(src, out)
    except PermissionError as ex:
        sys.exit(f"저장하지 못했습니다. 결과 PDF 가 다른 프로그램에서 열려 있으면 닫고 다시 시도하세요.\n{ex}")


if __name__ == "__main__":
    main()
